INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_351', 'tryb czuwania', '/trɨp t͡suˈvaɲa/', 'm', 375, 'environment', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_352', 'Jeszcze kilka lat temu, kiedy mówiłem znajomym, że jestem cyfrowym nomadą, patrzyli się na mnie, jakbym zwariował.', '/ˈjɛʂtʂɛ ˈkilka lat ˈtɛmu .../', NULL, 400, 'digital_nomad', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_353', 'To określenie jest bardziej znane, ponieważ styl pracy i życia zwany cyfrowym nomadyzmem staje się coraz popularniejszy.', '/tɔ ɔkrɛɕˈlɛɲɛ .../', NULL, 401, 'digital_nomad', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_354', 'Na czym to wszystko polega?', '/na tʂɨm tɔ ˈfʂɨstkɔ pɔˈlɛga/', NULL, 402, 'digital_nomad', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_355', 'Cyfrowym nomadom do pracy potrzebny jest tylko komputer i internet.', '/t͡sɨˈfrɔvɨm nɔˈmadɔm dɔ ˈprat͡sɨ .../', NULL, 403, 'digital_nomad', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_356', 'Łączą taką formę zarobkowania z podróżowaniem.', '/ˈwɔ̃nt͡ʂɔ̃ ˈtakɔ̃ ˈfɔrmɛ zarɔbkɔˈvaɲa s pɔdrɔʐɔˈvaɲɛm/', NULL, 404, 'digital_nomad', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_357', 'Zwykle zatrzymują się na jakiś czas w ciekawym miejscu i po pracy korzystają z jego atutów.', '/ˈzvɨklɛ zatr̥ɨˈmujɔ̃ ɕɛ .../', NULL, 405, 'digital_nomad', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_358', 'Czasami postanawiają zostać gdzieś na dłużej.', '/t͡ʂaˈɕamʲi pɔstaˈnavʲɔ̃ ˈzɔstat͡ɕ gd͡ʑɛɕ na ˈdwuʐɛj/', NULL, 406, 'digital_nomad', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_359', 'Nawiązują nowe znajomości, poznają kulturę kraju, w którym przebywają, i uczą się języka.', '/navʲɔ̃ˈzujɔ̃ ˈnɔvɛ znaˈjɔmɔɕt͡ɕi .../', NULL, 407, 'digital_nomad', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_360', 'Wiele osób myśli, że cyfrowym nomadą może zostać tylko singiel. To nieprawda.', '/ˈvʲɛlɛ ˈusɔp mɨɕli .../', NULL, 408, 'digital_nomad', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_361', 'Znam ludzi, którzy wyjeżdżają całymi rodzinami i organizują sobie życie w nowym miejscu.', '/znam ˈlʲud͡ʑi .../', NULL, 409, 'digital_nomad', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_362', 'Dzieci uczęszczają do szkół lub uczą się w trybie edukacji domowej, a rodzice pracują.', '/ˈd͡ʑɛt͡ɕi ut͡ʂɛʂt͡ʂajɔ̃ dɔ ʂkuf .../', NULL, 410, 'digital_nomad', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_363', 'Sam od pięciu lat jestem cyfrowym nomadą i nie żałuję, że się na to zdecydowałem.', '/sam ɔt ˈpʲɛɲt͡ʂu lat ˈjɛstɛm .../', NULL, 411, 'digital_nomad', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_364', 'Moim zdaniem to wspaniałe doświadczenie.', '/ˈmɔim ˈzdaɲɛm tɔ fspʲaˈwawɛ dɔɕfʲat͡ʂɛɲt͡ɕɛ/', NULL, 412, 'digital_nomad', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_365', 'Osobiście lubię zatrzymać się na dłużej w jakimś miejscu, żeby dobrze je poznać.', '/ɔsɔˈbʲiɕt͡ɕɛ ˈlubʲɛ .../', NULL, 413, 'digital_nomad', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_366', 'Spędziłem rok w Tajlandii i rok na Bali, a teraz mieszkam w Hiszpanii, na Fuerteventurze.', '/ˈspɛnd͡ʑiwɛm rɔk .../', NULL, 414, 'digital_nomad', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_367', 'Ale myślę już o kolejnym kraju. Może wybiorę Meksyk? Jeszcze nie wiem.', '/alɛ ˈmɨɕlɛ juʂ ɔ ˈkɔlɛjnɨm ˈkraj u .../', NULL, 415, 'digital_nomad', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_368', 'Prowadzę swój sklep internetowy i zarabiam naprawdę dobrze.', '/prɔˈvad͡zɛ sfuj ˈsklɛp intɛrnɛˈtɔvɨ i zaˈrabʲam napˈradɛ ˈdɔbʐɛ/', NULL, 416, 'digital_nomad', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_369', 'Dzięki temu nie muszę się martwić o koszty życia i podróżowania.', '/ˈd͡ʑɛ̃ŋkʲi ˈtɛmu ɲɛ ˈmuʂɛ ɕɛ ˈmart͡ɕit͡ɕ .../', NULL, 417, 'digital_nomad', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_370', 'Jedynym minusem według mnie jest to, że rzadko widuję się z rodziną i przyjaciółmi z Katowic, skąd pochodzę.', '/jɛˈdɨnɨm ˈmin uːsɛm .../', NULL, 418, 'digital_nomad', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_371', 'Nasze kontakty się rozluźniają i nie jest łatwo podtrzymywać je na odległość.', '/ˈnaʂɛ kɔnˈtaktɨ ɕɛ rɔzˈluɕɲajɔ̃ .../', NULL, 419, 'digital_nomad', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_372', 'Znajomi pytają mnie, czy nie brak mi stabilizacji i czy nie chciałbym się ustatkować.', '/znaˈjɔmʲi pɨˈtajɔ̃ mɲɛ .../', NULL, 420, 'digital_nomad', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_373', 'Mówią, że najwyższy czas założyć rodzinę i kupić mieszkanie, jednak ja na razie o tym nie myślę.', '/ˈmuvʲɔ̃ ʐɛ .../', NULL, 421, 'digital_nomad', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_374', 'Korzystam z życia i dobrze się bawię.', '/kɔˈʐɨstam z ˈʐɨt͡ɕa i ˈdɔbʐɛ ɕɛ ˈbavʲɛ/', NULL, 422, 'digital_nomad', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_375', 'cyfrowy nomada', '/t͡sɨˈfrɔvɨ nɔˈmada/', 'm', 376, 'digital_nomad', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_376', 'pracować zdalnie', '/praˈt͡sɔvat͡ɕ ˈzd alɲɛ/', NULL, 377, 'digital_nomad', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_377', 'zarabiać na życie', '/zaˈrabʲat͡ɕ na ˈʐɨt͡ɕɛ/', NULL, 378, 'digital_nomad', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_378', 'koszty życia', '/ˈkɔʂtɨ ˈʐɨt͡ɕa/', NULL, 379, 'digital_nomad', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_379', 'ustatkować się', '/ust atˈkɔvat͡ɕ ɕɛ/', NULL, 380, 'digital_nomad', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_380', 'edukacja domowa', '/ɛduˈkat͡sja dɔˈmɔva/', 'f', 381, 'digital_nomad', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_381', 'singiel', '/ˈɕiŋɡʲɛl/', 'm', 382, 'digital_nomad', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_382', 'korzystać z życia', '/kɔˈʐɨstat͡ɕ z ˈʐɨt͡ɕa/', NULL, 383, 'digital_nomad', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_383', 'coś jest komuś potrzebne do czegoś', '/t͡ʂɔɕ ˈjɛst ˈkɔmuɕ pɔˈtʂɛbnɛ dɔ ˈt͡ʂɛɡɔɕ/', NULL, 423, 'constructions', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_384', 'łączyć coś z czymś', '/ˈwɔ̃nt͡ʂɨt͡ɕ ˈt͡ʂɔɕ s ˈt͡ʂɨmɕ/', NULL, 424, 'constructions', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_385', 'łączyć pracę z życiem rodzinnym', '/ˈwɔ̃nt͡ʂɨt͡ɕ ˈprat͡sɛ z ˈʐɨt͡ɕɛm rɔˈd͡ʑinnɨm/', NULL, 425, 'constructions', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_386', 'zatrzymać się w ciekawym miejscu / w jakimś mieście', '/zatʂɨˈmat͡ɕ ɕɛ f t͡ɕɛˈkavɨm ˈmʲɛjst͡su .../', NULL, 426, 'constructions', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_387', 'korzystać z atutów / z udogodnień / z basenu', '/kɔˈʐɨstat͡ɕ z aˈtutuf / z udɔˈɡɔdɲɛɲ / z baˈsɛnu/', NULL, 427, 'constructions', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_388', 'nawiązywać kontakty, znajomości, przyjaźnie', '/navʲɔ̃ˈzɨvat͡ɕ kɔnˈtaktɨ, znaˈjɔmɔɕt͡ɕi, pʂɨˈjaɕɲɛ/', NULL, 428, 'constructions', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_389', 'zostać cyfrowym nomadą, podróżnikiem', '/ˈzɔstat͡ɕ t͡sɨˈfrɔvɨm nɔˈmada, pɔˈdrɔʐɲikʲɛm/', NULL, 429, 'constructions', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_390', 'uczęszczać do szkoły', '/ut͡ʂɛʂt͡ʂat͡ɕ dɔ ˈʂkɔwɨ/', NULL, 430, 'constructions', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_391', 'wybierać kraj, zawód, studia', '/vɨˈbʲɛrat͡ɕ ˈkraj, ˈzavut, ˈstudʲa/', NULL, 431, 'constructions', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_392', 'zachowywać optymizm', '/zaˈxɔvɨvat͡ɕ ɔptɨˈmizm/', NULL, 432, 'constructions', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_393', 'prowadzić sklep internetowy, firmę, działalność gospodarczą', '/prɔˈvad͡ʑit͡ɕ ˈsklɛp .../', NULL, 433, 'constructions', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_394', 'martwić się o pieniądze, o pracę, o dzieci, o bezpieczeństwo', '/ˈmart͡ɕit͡ɕ ɕɛ ɔ pʲɔˈɲɔnd͡zɛ .../', NULL, 434, 'constructions', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_395', 'widywać się z rodziną, z przyjaciółmi, ze znajomymi', '/vʲiˈdɨvat͡ɕ ɕɛ z rɔˈd͡ʑinɔ̃ .../', NULL, 435, 'constructions', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_396', 'Żyjemy w świecie, w którym jednym kliknięciem możemy dowiedzieć się, co robią nasi znajomi.', '/ˈʐɨjɛmɨ f ˈɕfʲɛt͡ɕɛ .../', NULL, 436, 'social_media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_397', 'Gdzie zjadł kolację ich ulubiony muzyk lub jaką sukienkę kupiła koleżanka, której nie widzieliśmy od paru lat.', '/gd͡ʑɛ ˈzjat kwɔˈlat͡sʲɛ .../', NULL, 437, 'social_media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_398', 'Media społecznościowe stworzyły rzeczywistość, w której na wyciągnięcie ręki mamy dostęp do niekończącego się przypływu informacji.', '/ˈmɛdja spɔwɛt͡ʂɲɔˈt͡ʂɔvɛ stfɔˈʐɨwɨ .../', NULL, 438, 'social_media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_399', 'Nietrudno się zgodzić z twierdzeniem, że świat nigdy wcześniej nie był tak dobrze połączony.', '/ɲɛˈtrudnɔ ɕɛ zˈɡɔd͡ʑit͡ɕ .../', NULL, 439, 'social_media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_400', 'Jednak im bardziej popularny stał się Instagram, Facebook czy Twitter, tym więcej osób zaczęło zastanawiać się, gdzie zmierza rzeczywistość.', '/ˈjɛdnak im ˈbard͡ʑɛj pɔpuˈlarnɨ .../', NULL, 440, 'social_media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_401', 'Liczba użytkowników mediów społecznościowych szacowana jest na trzy miliardy osób, czyli około 40% populacji.', '/ˈlʲid͡ʑba uʐɨtkɔˈvɲikuf .../', NULL, 441, 'social_media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_402', 'Przeciętnie spędzamy dwie godziny dziennie na Instagramie, Facebooku czy Twitterze.', '/pʂɛˈt͡ɕɛnt͡ɕɛ ˈspɛnd͡ʐamɨ .../', NULL, 442, 'social_media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_403', 'Statystyki pokazują, iż każdego dnia na Instagramie pojawia się 80 milionów zdjęć.', '/staˈtɨstɨkʲi pɔˈkazujɔ̃ .../', NULL, 443, 'social_media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_404', 'A w przeciągu sekundy przybywa ponad 8 tysięcy postów na Twitterze.', '/a f pʂɛˈt͡ɕɔŋgu sɛˈkundɨ .../', NULL, 444, 'social_media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_405', 'Nic dziwnego, że media społecznościowe wpływają nie tylko na formowanie dzisiejszego świata czy kultury, ale mają również znaczenie dla naszego funkcjonowania i zdrowia psychicznego.', '/ɲit͡ɕ ˈd͡ʑivnɛɡɔ .../', NULL, 445, 'social_media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_406', 'Nie jest tajemnicą fakt, iż media społecznościowe wywołują u niejednej osoby przypływ zazdrości.', '/ɲɛ ˈjɛst tajɛmˈɲit͡sɔ̃ fakt .../', NULL, 446, 'social_media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_407', 'Widok zdjęć znajomych odpoczywających na rajskich plażach czy w luksusowych apartamentach dla wielu potrafi być trudny do zniesienia.', '/ˈvidɔk zd͡ʑɛt͡ɕ znaˈjɔmɨx .../', NULL, 447, 'social_media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_408', 'Szczególnie że porównujemy naszą rzeczywistość z tym, co zobaczymy na portalu.', '/ʂt͡ʂɛˈɡulɲɛ ʐɛ pɔruˈwnujɛmɨ .../', NULL, 448, 'social_media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_409', 'Badanie przeprowadzone w zeszłym roku pokazały, iż prawie połowa użytkowników mediów społecznościowych czuła smutek po obejrzeniu zdjęć z życia znajomych.', '/baˈdaɲɛ .../', NULL, 449, 'social_media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_410', 'A dwadzieścia pięć procent osób było zazdrosnych, gdy znajomy polubił zdjęcie kogoś innego, zamiast zwrócić uwagę na ich posty.', '/a dvaˈd͡ʑɛɕt͡ɕɛ pʲɛɲt͡ɕ prɔˈt͡sɛnt .../', NULL, 450, 'social_media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_411', 'To jedna strona medalu.', '/tɔ ˈjɛdna ˈstrɔna mɛˈdalu/', NULL, 451, 'social_media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_412', 'Druga pokazuje, że większość użytkowników (66%) celowo tworzy wpisy w mediach społecznościowych w taki sposób, aby ukazywały ich życie ciekawiej niż wygląda ono w rzeczywistości.', '/ˈdruɡa pɔˈkazuje .../', NULL, 452, 'social_media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_413', 'Ponad 52 procent badanych przyznało także, iż publikowane przez nich zdjęcia mają wywołać zazdrość wśród rodziny i znajomych.', '/ˈpɔnat ˈpʲɛɲt͡ʂɛt d͡ʑɛˈɕɔnt dˈvat .../', NULL, 453, 'social_media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_414', 'W ten sposób podbudowują swoje poczucie wartości.', '/f tɛn ˈspɔsup pɔdbuˈdɔvujɔ̃ ˈsfɔjɛ pɔˈt͡ʂut͡ɕɛ ˈwartɔɕt͡ɕi/', NULL, 454, 'social_media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_415', 'Większość z nas jest świadoma negatywnych skutków niewłaściwego korzystania z mediów społecznościowych.', '/ˈvʲɛŋkʂɔɕt͡ɕ z nas .../', NULL, 455, 'social_media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_416', 'Jednak mimo wszystko nie możemy oprzeć się pokusie ich oglądania kilka razy dziennie.', '/ˈjɛdnak ˈmimɔ ˈfʂɨstkɔ .../', NULL, 456, 'social_media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_417', 'Dlatego niektórzy badacze uznali, że publikowanie postów jest trudniejsze do opanowania, niż powstrzymanie się od palenia papierosów czy picia alkoholu.', '/dlaˈtɛɡɔ .../', NULL, 457, 'social_media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_418', 'Mogłoby brzmieć to jak szaleństwo, dopóki nie zwrócimy uwagi na fakt, że w tym momencie miliony ludzi na całym świecie przesuwają palcem po ekranie telefonu, przeglądając Instagram.', '/mɔˈɡwɔbɨ .../', NULL, 458, 'social_media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_419', 'A w kolejnej minucie YouTube zaleje fala trzystu godzin przeróżnych nagrań.', '/a f ˈkɔlɛjnɛj mʲiˈnutɛ .../', NULL, 459, 'social_media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_420', 'jednym kliknięciem', '/ˈjɛdnɨm klʲikˈɲɛnt͡ɕɛm/', NULL, 460, 'social_media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_421', 'na wyciągnięcie ręki', '/na vɨt͡ɕɔŋɡˈɲɛnt͡ɕɛ ˈrɛŋkʲi/', NULL, 461, 'social_media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_422', 'przypływ informacji', '/ˈpʂɨpwɨf ˌiɱfɔrˈmat͡sji/', 'm', 462, 'social_media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_423', 'liczba użytkowników', '/ˈlʲid͡ʑba uʐɨtkɔˈvɲikuf/', 'f', 463, 'social_media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_424', 'publikować posty', '/publʲiˈkɔvat͡ɕ ˈpɔstɨ/', NULL, 464, 'social_media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_425', 'polubić zdjęcie', '/pɔˈlubʲit͡ɕ ˈzd͡ʑɛt͡ɕɛ/', NULL, 465, 'social_media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_426', 'subskrybować kanał', '/supsˈkrɨbɔvat͡ɕ ˈkanaw/', NULL, 466, 'social_media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_427', 'prowadzić kanał', '/prɔˈvad͡ʑit͡ɕ ˈkanaw/', NULL, 467, 'social_media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_428', 'wykupić abonament', '/vɨˈkupʲit͡ɕ abɔnaˈmɛnt/', NULL, 468, 'social_media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_429', 'przypływ zazdrości', '/ˈpʂɨpwɨf zazˈdrɔɕt͡ɕi/', 'm', 469, 'social_media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_430', 'trudny do zniesienia', '/ˈtrudnɨ dɔ znʲɛˈɕɛɲa/', NULL, 470, 'social_media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_431', 'poczucie wartości', '/pɔˈt͡ʂut͡ɕɛ ˈvartɔɕt͡ɕi/', 'n', 471, 'social_media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_432', 'oprzeć się pokusie', '/ˈɔpʂɛt͡ɕ ɕɛ pɔˈkusʲɛ/', NULL, 472, 'social_media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_433', 'być trudniejszym do opanowania', '/bɨt͡ɕ trudˈɲɛjʂɨm dɔ ɔpanɔˈvaɲa/', NULL, 473, 'social_media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_434', 'powstrzymać się od palenia', '/pɔfˈtʂɨmat͡ɕ ɕɛ ɔt paˈlɛɲa/', NULL, 474, 'social_media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_435', 'przesuwać palcem po ekranie', '/pʂɛˈsuvat͡ɕ ˈpalt͡sɛm pɔ ɛkˈraɲɛ/', NULL, 475, 'social_media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_436', 'Nie wyobrażam sobie śniadania bez czytania gazety.', '/ɲɛ vɨɔˈbraʐam ˈsɔbʲɛ ɕɲaˈdaɲa bɛs t͡ʂɨˈtaɲa ɡaˈzɛtɨ/', NULL, 476, 'media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_437', 'To taki mój „święty czas”, przeznaczony wyłącznie dla mnie.', '/tɔ ˈtaki muf ˈɕfʲɛntɨ t͡ʂas .../', NULL, 477, 'media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_438', 'Wstaję tak, abym nie musiał się spieszyć, robię sobie kanapki, parzę kawę i zasiadam przy stole.', '/ˈfstajɛ tak .../', NULL, 478, 'media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_439', 'Przez jakieś 40 minut czytam sobie w spokoju wiadomości i nie ma mnie dla nikogo.', '/pʂɛz ˈjakʲɛɕ .../', NULL, 479, 'media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_440', 'W domu wszyscy od dawna wiedzą, że można ze mną rozmawiać dopiero, gdy skończę czytać.', '/v dɔmu ˈfʂɨst͡sɨ ɔd ˈdavna .../', NULL, 480, 'media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_441', 'Uwielbiam muzykę. Nie znoszę jednak radia, jeszcze żadna stacja mi się nie spodobała na tyle, żeby jej słuchać.', '/uˈvʲɛlbʲam muˈzɨkɛ .../', NULL, 481, 'media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_442', 'W każdej za dużo gadają i w każdej puszczają za dużo reklam.', '/f ˈkaʐdɛj za ˈduʐɔ ɡaˈdajɔ̃ .../', NULL, 482, 'media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_443', 'Dlatego kiedyś słuchałam tylko swoich płyt, ale odkąd odkryłam Spotify, już tego nie robię.', '/dlaˈtɛɡɔ ˈkʲɛdɨɕ .../', NULL, 483, 'media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_444', 'Mam teraz dostęp do wszystkiego, co lubię.', '/mam ˈtɛraz ˈdɔstɛmp dɔ ˈfʂɨstkʲɛɡɔ t͡ʂɔ ˈlubʲɛ/', NULL, 484, 'media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_445', 'Od zawsze czytałam książki wszędzie, gdzie się dało — w domu, szkole, poczekalni, autobusie.', '/ɔd ˈzafʂɛ ˈt͡ʂɨtawam ˈkɕɔ̃ʐkʲi .../', NULL, 485, 'media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_446', 'Nawet przy jedzeniu, co zwykle doprowadzało moją mamę do szału.', '/ˈnavɛt pʂɨ jɛˈd͡zɛɲu .../', NULL, 486, 'media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_447', 'W moim rodzinnym domu najważniejszy był telewizor.', '/v ˈmɔim rɔˈd͡ʑinnɨm ˈdɔmu .../', NULL, 487, 'media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_448', 'Właściwie nie pamiętam, aby rodzice go wyłączali, nawet zasypiali przy nim.', '/ˈwwaɕt͡ɕivʲɛ ɲɛ paˈmʲɛntam .../', NULL, 488, 'media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_449', 'Był włączony w czasie posiłków, a także podczas wizyt gości i nikt nigdy nie powiedział, że mu przeszkadza.', '/bwɨ ˈfwɔ̃nt͡ʂɔnɨ .../', NULL, 489, 'media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_450', 'Dopiero na studiach nauczyłem się żyć bez tego pudła i do tej pory obywam się bez niego.', '/dɔˈpʲɛrɔ na ˈstudʲax .../', NULL, 490, 'media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_451', 'Internet, tylko Internet.', '/ˈintɛrnɛt ˈtɨlkɔ ˈintɛrnɛt/', NULL, 491, 'media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_452', 'Zupełnie nie rozumiem po co ludziom jakaś telewizja czy radio.', '/zuˈpɛwɲɛ ɲɛ rɔˈzumʲɛm .../', NULL, 492, 'media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_453', 'Zresztą, jak bardzo kochają te media, to znajdą je również w Internecie, co jasno pokazuje jego wyższość.', '/ˈzrɛʂtɔ̃ .../', NULL, 493, 'media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_454', 'Dla mnie Internet jest całym światem, bo mogę z niego dowiedzieć się praktycznie wszystkiego.', '/dla mɲɛ ˈintɛrnɛt .../', NULL, 494, 'media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_455', 'Nie muszę sprawdzać w słownikach, chodzić do biblioteki czy kupować gazet.', '/ɲɛ ˈmuʂɛ ˈspravd͡zat͡ɕ .../', NULL, 495, 'media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_456', 'A i kontakty ze znajomymi mam na wyciągnięcie ręki.', '/a i kɔnˈtaktɛ z znaˈjɔmɨmʲi .../', NULL, 496, 'media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_457', 'Bardzo lubię słuchać radia. Często coś gotuję (to moja kolejna pasja), więc radio znakomicie umila mi przy tym czas.', '/ˈbardzɔ ˈlubʲɛ .../', NULL, 497, 'media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_458', 'Mam swoją ulubioną stację, choć muszę przyznać, że nie wszystkie audycje mi się podobają.', '/mam ˈsfɔjɔ̃ uluˈbʲɔnɔ̃ ˈstat͡sʲɛ .../', NULL, 498, 'media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_459', 'Drażni mnie też to, że pojawia się coraz więcej reklam.', '/ˈdraʐɲi mɲɛ tɛʂ tɔ .../', NULL, 499, 'media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_460', 'Ale lubię muzykę tam nadawaną, a poza tym mogę w ten sposób wysłuchać wielu ważnych informacji.', '/alɛ ˈlubʲɛ .../', NULL, 500, 'media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_461', 'Jeśli tylko mam czas, oglądam filmy. Najchętniej seriale, mam kilka ulubionych.', '/ˈjɛɕlʲi ˈtɨlkɔ mam t͡ʂas .../', NULL, 501, 'media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_462', 'Oczywiście nie w telewizji, bo nie pozwala ona oglądać tego, co lubię i wtedy, kiedy mogę.', '/ɔt͡ʂɨˈvʲiɕt͡ɕɛ .../', NULL, 502, 'media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_463', 'Pracuję na zmiany, więc mój rozkład dnia jest co chwilę inny.', '/praˈt͡sujɛ na ˈzmʲanɨ .../', NULL, 503, 'media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_464', 'Dlatego jestem gorącym zwolennikiem platform takich jak Netflix czy Showmax i wszystkich znajomych namawiam na wykupienie sobie abonamentu, na którejś z nich.', '/dlaˈtɛɡɔ ˈjɛstɛm .../', NULL, 504, 'media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_465', 'Większość wiadomości czytam w Internecie, ale nie znaczy to, że nie kupuję gazet.', '/ˈvʲɛŋkʂɔɕt͡ɕ .../', NULL, 505, 'media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_466', 'Kupuję, tylko nie są to dzienniki.', '/kuˈpujɛ ˈtɨlkɔ ɲɛ sɔ̃ tɔ d͡ʑɛɲˈɲikʲi/', NULL, 506, 'media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_467', 'Wolę magazyny kobiece, w których znajdę interesujące mnie artykuły i wywiady.', '/ˈvɔlɛ maɡaˈzɨnɨ kɔˈbʲɛt͡sɛ .../', NULL, 507, 'media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_468', 'Bardzo lubię też miesięcznik Charaktery, bo drukują tam naprawdę ważne i ciekawe teksty.', '/ˈbardzɔ ˈlubʲɛ tɛʂ mʲɛˈɕɛ̃nt͡ʂɲik .../', NULL, 508, 'media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_469', 'Muszę się przyznać, że najwięcej czasu spędzam, przeglądając YouTube.', '/ˈmuʂɛ ɕɛ pʂɨˈznaʨ .../', NULL, 509, 'media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_470', 'Nie tylko ze względu na teledyski czy filmiki. Tam naprawdę można znaleźć wszystko!', '/ɲɛ ˈtɨlkɔ zɛ zˈɡlɛndu .../', NULL, 510, 'media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_471', 'Subskrybuję kilka kanałów i powoli przymierzam się do prowadzenia własnego.', '/supsˈkrɨbujɛ .../', NULL, 511, 'media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_472', 'Ale na razie nie zdradzę, o czym on będzie.', '/alɛ na ˈraʑɛ ɲɛ ˈzdrad͡ʐɛ ɔ t͡ʂɛm ɔn ˈbɛnd͡ʑɛ/', NULL, 512, 'media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_473', 'Chyba jestem urodzonym graczem.', '/ˈxɨba ˈjɛstɛm uˈrɔd͡ʐɔnɨm ˈɡrat͡ʂɛm/', NULL, 513, 'media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_474', 'Na przejście ulubionej gry mogę poświęcić naprawdę dużo czasu, choć staram się przy tym nie zawalać spraw zawodowych.', '/na pʂɛjˈɕt͡ɕɛ .../', NULL, 514, 'media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_475', 'Wiadomo, z czegoś żyć trzeba. Ale wolny czas spędzam najczęściej przy konsoli.', '/vʲaˈdɔmɔ z ˈt͡ʂɛɡɔɕ ʐɨt͡ɕ ˈtʂɛba .../', NULL, 515, 'media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_476', 'Kiedyś robiłem to tylko na pececie, jednak wymaga to zbyt wielu nakładów finansowych.', '/ˈkʲɛdɨɕ ˈrɔbʲiwɛm .../', NULL, 516, 'media', 'seed');
INSERT INTO vocab (id, target, ipa, gender, freq, theme, source) VALUES ('pl_477', 'Gry stają się coraz lepsze i coraz bardziej wymagające, a sprzęt szybko się starzeje i nie nadąża za tymi zmianami.', '/ˈɡrɨ ˈstajɔ̃ ɕɛ .../', NULL, 517, 'media', 'seed');
