INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_350', 'ru', 'восстановить');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_351', 'ru', 'режим ожидания');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_352', 'ru', 'Ещё несколько лет назад, когда я говорил знакомым, что я цифровой номад, они смотрели на меня, как будто я сошёл с ума.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_353', 'ru', 'Это определение более известно, потому что стиль работы и жизни, называемый цифровым номадизмом, становится всё более популярным.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_354', 'ru', 'В чём всё это заключается?');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_355', 'ru', 'Цифровым номадам для работы нужен только компьютер и интернет.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_356', 'ru', 'Они совмещают такую форму заработка с путешествиями.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_357', 'ru', 'Обычно они останавливаются на какое-то время в интересном месте и после работы пользуются его преимуществами.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_358', 'ru', 'Иногда они решают остаться где-то надолго.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_359', 'ru', 'Они заводят новые знакомства, узнают культуру страны, в которой пребывают, и учат её язык.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_360', 'ru', 'Многие думают, что цифровым номадом может стать только одинокий человек. Это неправда.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_361', 'ru', 'Я знаю людей, которые уезжают целыми семьями и устраивают себе жизнь на новом месте.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_362', 'ru', 'Дети ходят в школы или учатся в режиме домашнего обучения, а родители работают.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_363', 'ru', 'Я сам уже пять лет как цифровой номад и не жалею, что решился на это.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_364', 'ru', 'По моему мнению, это замечательный опыт.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_365', 'ru', 'Лично я люблю задержаться надолго в каком-то месте, чтобы хорошо его узнать.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_366', 'ru', 'Я провёл год в Таиланде и год на Бали, а сейчас живу в Испании, на Фуэртевентуре.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_367', 'ru', 'Но я уже думаю о следующей стране. Может, выберу Мексику? Пока не знаю.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_368', 'ru', 'Я веду свой интернет-магазин и зарабатываю действительно хорошо.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_369', 'ru', 'Благодаря этому мне не нужно беспокоиться о стоимости жизни и путешествиях.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_370', 'ru', 'Единственный минус, по моему мнению, это то, что я редко вижусь с семьёй и друзьями из Катовице, откуда я родом.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_371', 'ru', 'Наши контакты ослабевают, и нелегко поддерживать их на расстоянии.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_372', 'ru', 'Знакомые спрашивают меня, не не хватает ли мне стабильности и не хотел бы я остепениться.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_373', 'ru', 'Они говорят, что самое время создать семью и купить квартиру, однако я пока об этом не думаю.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_374', 'ru', 'Я наслаждаюсь жизнью и хорошо провожу время.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_375', 'ru', 'цифровой номад');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_376', 'ru', 'работать удалённо');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_377', 'ru', 'зарабатывать на жизнь');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_378', 'ru', 'стоимость жизни');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_379', 'ru', 'остепениться');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_380', 'ru', 'домашнее обучение');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_381', 'ru', 'одиночка, холостяк');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_382', 'ru', 'наслаждаться жизнью');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_383', 'ru', 'что-то кому-то нужно для чего-то (дат. + род.)');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_384', 'ru', 'соединять что-то с чем-то (вин. + твор.)');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_385', 'ru', 'соединять работу с семейной жизнью');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_386', 'ru', 'остановиться в интересном месте / в каком-то городе (местн.)');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_387', 'ru', 'пользоваться преимуществами / удобствами / бассейном (род.)');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_388', 'ru', 'заводить контакты, знакомства, дружеские отношения (вин.)');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_389', 'ru', 'стать цифровым номадом, путешественником (твор.)');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_390', 'ru', 'ходить в школу, посещать школу (род.)');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_391', 'ru', 'выбирать страну, профессию, учёбу (вин.)');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_392', 'ru', 'сохранять оптимизм (вин.)');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_393', 'ru', 'вести интернет-магазин, фирму, индивидуальное предпринимательство (вин.)');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_394', 'ru', 'беспокоиться о деньгах, о работе, о детях, о безопасности (вин.)');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_395', 'ru', 'видеться с семьёй, с друзьями, со знакомыми (твор.)');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_396', 'ru', 'Мы живём в мире, в котором одним кликом можем узнать, что делают наши знакомые.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_397', 'ru', 'Где они ужинали, какой их любимый исполнитель или какое платье купила подруга, которую мы не видели несколько лет.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_398', 'ru', 'Социальные сети создали реальность, в которой у нас на расстоянии вытянутой руки доступ к бесконечному потоку информации.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_399', 'ru', 'Нетрудно согласиться с утверждением, что мир никогда раньше не был так хорошо связан.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_400', 'ru', 'Однако чем популярнее становились Instagram, Facebook или Twitter, тем больше людей начало задумываться, куда движется реальность.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_401', 'ru', 'Количество пользователей социальных сетей оценивается в три миллиарда человек, то есть около 40% населения.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_402', 'ru', 'В среднем мы проводим два часа в день в Instagramie, Facebooku или Twitterze.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_403', 'ru', 'Статистика показывает, что каждый день в Instagramie появляется 80 миллионов фотографий.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_404', 'ru', 'А за секунду в Twittere прибавляется более 8 тысяч постов.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_405', 'ru', 'Неудивительно, что социальные сети влияют не только на формирование сегодняшнего мира или культуры, но также имеют значение для нашего функционирования и психического здоровья.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_406', 'ru', 'Не секрет, что социальные сети вызывают у некоторых людей прилив зависти.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_407', 'ru', 'Вид фотографий знакомых, отдыхающих на райских пляжах или в роскошных апартаментах, для многих может быть тяжело переносимым.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_408', 'ru', 'Особенно потому, что мы сравниваем нашу реальность с тем, что видим на портале.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_409', 'ru', 'Исследование, проведённое в прошлом году, показало, что почти половина пользователей социальных сетей чувствовала грусть после просмотра фотографий из жизни знакомых.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_410', 'ru', 'А двадцать пять процентов людей завидовали, когда знакомый лайкнул фото кого-то другого, вместо того чтобы обратить внимание на их посты.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_411', 'ru', 'Это одна сторона медали.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_412', 'ru', 'Другая показывает, что большинство пользователей (66%) намеренно создаёт записи в соцсетях так, чтобы они показывали их жизнь интереснее, чем она выглядит в реальности.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_413', 'ru', 'Более 52 процентов опрошенных признали также, что публикуемые ими фотографии должны вызвать зависть среди семьи и знакомых.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_414', 'ru', 'Таким образом они укрепляют своё чувство собственной значимости.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_415', 'ru', 'Большинство из нас осознаёт негативные последствия неправильного использования социальных сетей.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_416', 'ru', 'Однако несмотря на всё, мы не можем устоять перед искушением заглянуть в них несколько раз в день.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_417', 'ru', 'Поэтому некоторые исследователи признали, что публикация постов труднее поддаётся контролю, чем воздержание от курения сигарет или употребления алкоголя.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_418', 'ru', 'Это могло бы звучать как безумие, пока мы не обратим внимание на тот факт, что в эту минуту миллионы людей по всему миру водят пальцем по экрану телефона, просматривая Instagram.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_419', 'ru', 'А в следующую минуту YouTube захлестнёт волна из трёхсот часов самых разных записей.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_420', 'ru', 'в один клик');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_421', 'ru', 'на расстоянии вытянутой руки');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_422', 'ru', 'поток информации');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_423', 'ru', 'количество пользователей');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_424', 'ru', 'публиковать посты');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_425', 'ru', 'лайкнуть фото');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_426', 'ru', 'подписаться на канал');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_427', 'ru', 'вести канал');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_428', 'ru', 'купить подписку');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_429', 'ru', 'прилив зависти');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_430', 'ru', 'тяжело переносимый');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_431', 'ru', 'чувство собственной значимости');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_432', 'ru', 'устоять перед искушением');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_433', 'ru', 'труднее поддаваться контролю');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_434', 'ru', 'воздерживаться от курения');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_435', 'ru', 'водить пальцем по экрану');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_436', 'ru', 'Не представляю себе завтрак без чтения газеты.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_437', 'ru', 'Это моё «святое время», предназначенное исключительно для меня.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_438', 'ru', 'Встаю так, чтобы не пришлось спешить, делаю себе бутерброды, завариваю кофе и сажусь за стол.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_439', 'ru', 'Около 40 минут спокойно читаю новости, и меня ни для кого нет.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_440', 'ru', 'Дома все давно знают, что со мной можно разговаривать только тогда, когда закончу читать.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_441', 'ru', 'Обожаю музыку. Однако не выношу радио, ни одна радиостанция мне не понравилась настолько, чтобы её слушать.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_442', 'ru', 'В каждой слишком много болтают и в каждой крутят слишком много рекламы.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_443', 'ru', 'Поэтому когда-то я слушала только свои пластинки, но с тех пор как открыла Spotify, уже этого не делаю.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_444', 'ru', 'Теперь у меня есть доступ ко всему, что я люблю.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_445', 'ru', 'Я всегда читала книги везде, где только можно — дома, в школе, в приёмной, в автобусе.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_446', 'ru', 'Даже во время еды, что обычно доводило мою маму до бешенства.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_447', 'ru', 'В моём родном доме самым важным был телевизор.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_448', 'ru', 'Собственно, не помню, чтобы родители его выключали, даже засыпали при нём.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_449', 'ru', 'Он был включён во время еды, а также во время визитов гостей, и никто никогда не сказал, что он мешает.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_450', 'ru', 'Только в университете я научился жить без этого ящика и до сих пор обхожусь без него.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_451', 'ru', 'Интернет, только Интернет.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_452', 'ru', 'Совершенно не понимаю, зачем людям какое-то телевидение или радио.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_453', 'ru', 'Впрочем, как бы они ни любили эти медиа, они найдут их также в Интернете, что ясно показывает его превосходство.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_454', 'ru', 'Для меня Интернет — это весь мир, потому что из него я могу узнать практически всё.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_455', 'ru', 'Мне не нужно проверять в словарях, ходить в библиотеку или покупать газеты.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_456', 'ru', 'А контакты со знакомыми у меня на расстоянии вытянутой руки.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_457', 'ru', 'Очень люблю слушать радио. Часто что-то готовлю (это моё другое увлечение), поэтому радио прекрасно скрашивает мне время.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_458', 'ru', 'У меня есть любимая радиостанция, хотя должна признать, что не все передачи мне нравятся.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_459', 'ru', 'Меня раздражает также, что появляется всё больше рекламы.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_460', 'ru', 'Но мне нравится транслируемая там музыка, и кроме того, я могу таким образом услышать много важной информации.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_461', 'ru', 'Если только есть время, смотрю фильмы. Больше всего сериалы, у меня несколько любимых.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_462', 'ru', 'Конечно не по телевизору, потому что он не позволяет смотреть то, что я люблю, и тогда, когда я могу.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_463', 'ru', 'Я работаю по сменам, поэтому моё расписание дня каждую минуту другое.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_464', 'ru', 'Поэтому я горячий сторонник таких платформ, как Netflix или Showmax, и всех знакомых уговариваю купить себе подписку на какую-нибудь из них.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_465', 'ru', 'Большинство новостей читаю в Интернете, но это не значит, что не покупаю газет.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_466', 'ru', 'Покупаю, только это не ежедневные издания.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_467', 'ru', 'Предпочитаю женские журналы, в которых найду интересующие меня статьи и интервью.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_468', 'ru', 'Очень люблю также ежемесячник «Charaktery», потому что там печатают по-настоящему важные и интересные тексты.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_469', 'ru', 'Должен признаться, что больше всего времени я провожу, просматривая YouTube.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_470', 'ru', 'Не только из-за клипов или видео — там действительно можно найти всё!');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_471', 'ru', 'Я подписан на несколько каналов и понемногу готовлюсь к ведению собственного.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_472', 'ru', 'Но пока не выдам, о чём он будет.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_473', 'ru', 'Кажется, я прирождённый игрок.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_474', 'ru', 'На прохождение любимой игры могу посвятить действительно много времени, хотя стараюсь при этом не запускать рабочие дела.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_475', 'ru', 'Известно, на что-то жить надо. Но свободное время чаще всего провожу за консолью.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_476', 'ru', 'Когда-то я делал это только на компьютере, однако это требует слишком больших финансовых затрат.');
INSERT INTO vocab_translation (vocab_id, lang, text) VALUES ('pl_477', 'ru', 'Игры становятся всё лучше и всё требовательнее, а оборудование быстро устаревает и не успевает за этими изменениями.');
