INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_295', 'ru', 'ТРОМПЕ → ''тромп-лёй'' (trompe l''oeil) — обманка!');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_296', 'ru', 'ТЮЕ → ТЮ = короткое и резкое, как удар → убивать');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_297', 'ru', 'ЮЗЕ → ''юзать'' (use) → изнашивать от использования');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_298', 'ru', 'ЮТИЛИЗЕ → ''утилизировать'' — использовать!');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_299', 'ru', 'ВАРЬЕ → ''вариация'' — разнообразие!');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_300', 'ru', 'ВЕРИФЬЕ → ''верификация'' — проверка!');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_301', 'ru', 'ВЕРСЕ → ''версия'' → наливать (другую порцию)');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_302', 'ru', 'ВИЗЕ → ''визор'' — прицел → целиться!');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_303', 'ru', 'ВИЗИТЕ → ''визит'' — посещение!');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_304', 'ru', 'ВОЛЕ → ''вольный'' → свободно летать или... красть!');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_305', 'ru', 'ВОТЕ → ''вотум'' — голосование!');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_306', 'ru', 'АШЕТЕ → ''ашет'' звучит как ''я шёл'' в магазин → покупать!');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_307', 'ru', 'ЭСЭЙЕ → ''эссе'' — пробное сочинение → пробовать!');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_308', 'ru', 'КОМАНСЕ → ''команда — старт!'' → начинать!');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_309', 'ru', 'АШ-ЕВ → ''ашеватый'' — завершённый, готовый');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_310', 'ru', 'А-МЕН-Е → амёна! — приведи друга с собой');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_311', 'ru', 'ЭМ-МЕН-Е → эмм... мой друг идёт со мной');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_312', 'ru', 'АН-Л-Е → унлИ — сними это с себя');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_313', 'ru', 'ЛЕВ-Е → как ''лев'' — поднимай как лев лапу');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_314', 'ru', 'РЕ-ЛЕВ-Е → РЕ-ЛИЗЫ очков: подхватываешь упавшие');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_316', 'ru', 'МЕН-Е → ментор ведёт, менеджер управляет');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_317', 'ru', 'ПРО-МЕН-Е → прОгулка — мы ведём собаку');
