INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_001', 'pl', 'BON = dobry + JOUR = dzień → ''dzień dobry!''');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_002', 'pl', 'Brzmi jak ''merci'' — już znamy to słowo!');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_003', 'pl', 'Brzmi jak ''oui'' — ''u-u-i, zgadzam się!''');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_004', 'pl', 'Podobne do ''non-stop'' → prefix negacji');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_005', 'pl', '''Sza'' — kot syczy na ciebie: ''szszsz!''');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_006', 'pl', 'ME-ZON → ''mezonina'' — piętro w domu');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_007', 'pl', 'Brzmi jak ''O'' — narysuj O, to kropla wody');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_008', 'pl', 'MAN-ŻER → człowiek (man) je → jeść');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_009', 'pl', 'DOR-MIR → dormitorium — miejsce do spania');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_010', 'pl', 'FAM → ''familia'' — kobieta w rodzinie');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_011', 'pl', 'OM → ''homo sapiens'' — człowiek');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_012', 'pl', 'GRAN → ''grandiozowy'' — wielki, ogromny');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_013', 'pl', 'P''TIT → ''petit'' — mały (jest już w polskim!)');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_014', 'pl', 'RŻ → ''rumieńce'' (rouge) — czerwony kolor na policzkach');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_015', 'pl', 'BLÖ → ''blue'' po angielsku, podobne!');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_016', 'pl', 'PAR-LE → ''parlament'' — miejsce, gdzie mówią');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_017', 'pl', 'ALLE → ''Ale!'' — naprzód! (słychać na stadionach)');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_018', 'pl', 'WENIR → ''weni, widzi, wici'' = przyszedłem...');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_019', 'pl', 'PEN → brzmi jak ''chleb'' po hiszpańsku');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_020', 'pl', 'WIN → ''wintage'' pochodzi od wina!');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_021', 'pl', 'BO → ''beau'' = przystojny mężczyzna');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_022', 'pl', 'MĄTNAN → MĄT = ręka + NAN = trzyma → trzyma czas TERAZ');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_023', 'pl', 'TUŻUR → TU = wszystkie + ŻUR = dni → każdego dnia, zawsze');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_024', 'pl', 'ŻAME → ŻAM = zamek → drzwi nigdy się nie otworzą');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_025', 'pl', 'PÖ = może + ETRE = być → ''być może''');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_026', 'pl', 'KOM + PRANDR → ''komprehend'' — zrozumieć umysłem');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_027', 'pl', 'SAWUAR-FER → ''savoir-faire'' już jest w polskim!');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_028', 'pl', 'KONETR → ''koneser'' = znawca — ten, kto wie!');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_029', 'pl', 'WIL → ''willi'' — dom na wsi w mieście');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_030', 'pl', 'TRAWAJ → ''travel'' — podróż = trud');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_031', 'pl', 'SZUA-ZIR → ''choice'' — wybór!');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_032', 'pl', 'DIFISIL → podobne do ''difficult'' — trudny');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_033', 'pl', 'FASIL → ''facility'' — łatwość, wygoda');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_034', 'pl', 'SUWAN → SU = pod + WAN = wiatr → ''pod wiatrem''');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_035', 'pl', 'ANSAMBL → ''ansambl'' — grupa grająca RAZEM!');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_036', 'pl', 'PERDR → ''perdita'' — zagubiona');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_037', 'pl', 'TRUWE → truwer — średniowieczny poeta');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_038', 'pl', 'ATANDR → ''attend'' kiedyś znaczyło ''czekać''');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_039', 'pl', 'KRUAR → ''creed'' — w co wierzysz');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_040', 'pl', 'LIR → ''legible'' — co można przeczytać');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_041', 'pl', 'EKRIr → ''scribe'' — ten, kto pisze');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_042', 'pl', 'KESTION → prawie jak ''question'' — pytanie');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_043', 'pl', 'REPONS → ''response'' — odpowiedź');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_044', 'pl', 'PANSĘ → ''pensive'' — zadumany');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_045', 'pl', 'SANTIR → ''sentiment'' — uczucie');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_046', 'pl', 'SZOMEN → ''cheminée'' — komin, droga dymu');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_047', 'pl', 'LUMIER → ''luminescencja'' — świecenie, światło. Bracia Lumière wynaleźli kino!');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_048', 'pl', 'NUWO → ''nuwo'' już jest w polskim: secesja, beaujolais nouveau');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_049', 'pl', 'PROPR → ''proper'' — czysty, właściwy');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_050', 'pl', 'LIBR → ''liberty'' — wolność!');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_051', 'pl', 'KONFJANS → ''konfidencja'' — zaufanie, sekret');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_052', 'pl', 'KRĄT → KRĄDR = bać się → sam strach');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_053', 'pl', 'PURTAN → PUR = dla + TAN = tyle → ''przy tym wszystkim, jednak''');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_054', 'pl', 'KAN MEM → MEM = ten sam → ''to samo, i tak''');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_055', 'pl', 'AN EFE → ''efekt'' — rzeczywiście, tak jest');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_056', 'pl', 'DEMARSZ → ''demarsz'' już jest w polskim! — zdecydowany krok');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_057', 'pl', 'ME = źle + FJE = ufać → źle ufać');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_058', 'pl', 'REZUD → ''rezolucja'' — rozwiązanie problemu');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_059', 'pl', 'PRE = przed + WENIR = przyjść → przyjść wcześniej = ostrzec');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_060', 'pl', 'KOMPORTMAN → ''komfort'' — jak się zachowujesz');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_061', 'pl', 'AN ŻÖ → ''w grze'' → co jest na szali');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_062', 'pl', 'DEZORME → DE = od + OR = teraz → odtąd');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_063', 'pl', 'DE KIO → DE = od (momentu) + KIO = że → jak tylko');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_064', 'pl', 'SZO RĄDR KONT → dać sobie sprawę → uświadomić');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_065', 'pl', 'NUANS → słowo ''nuans'' przyszło do polskiego z francuskiego!');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_066', 'pl', 'ME + KONETR → źle znać = nie rozumieć');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_067', 'pl', 'ABUTIR → ABUT = koniec → dojść do końca/rezultatu');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_068', 'pl', 'MIZ AN EWUER → MIZA = położyć + W DZIELE → zrealizować');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_069', 'pl', 'TEL KIO → TEL = taki → taki jak (przykład)');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_070', 'pl', 'PARWENIR → PAR = przez + WENIR = przyjść → przyjść przez = osiągnąć');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_071', 'pl', 'SAWERE → ''weryfikować'' — potwierdzić jako prawdę');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_072', 'pl', 'AMBIGUITĘ → ''ambiguitas'' — dwuznaczność (prawie jak po polsku!)');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_073', 'pl', 'DEKLANSE → DE = od + KLENŻ = klamka → ''zdjąć klamkę'', uruchomić');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_074', 'pl', 'PREKONIZE → PRE + KONIZE → doradzać wcześniej = zalecać');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_075', 'pl', 'PERTINANS → ''pertinentny'' = stosowny, na temat');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_076', 'pl', 'ATENIUE → ''atenuacja'' — osłabienie sygnału');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_077', 'pl', 'ESOR → ''wzlot'' — jak ptak wznosi się w górę');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_078', 'pl', 'METR AN EGZERG → wystawić na widoczne miejsce, podkreślić');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_079', 'pl', 'O DETRIMĄ DE → ''detryment'' — szkoda, uszczerbek');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_080', 'pl', 'SĄN EKWIWOK → ''ekwiwok'' = dwuznaczny → BEZ dwuznaczności');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_081', 'pl', 'EME → ''emocja'' — miłość = silna emocja!');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_082', 'pl', 'DONE → ''donor'' — ten, kto daje');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_083', 'pl', 'TRAWAJE → ''trawaj'' = praca (jak ''travel'' — podróż = trud)');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_084', 'pl', 'ARIWE → ''arrive'' po angielsku — przybywać!');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_085', 'pl', 'DEMĄDE → ''demand'' — żądanie, zapytanie');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_086', 'pl', 'REGARDE → ''re'' (znów) + ''guard'' (pilnować) → uważnie patrzeć');
INSERT INTO vocab_hint (vocab_id, lang, text) VALUES ('fr_087', 'pl', 'EKUTE → ''akustyka'' — to, czego słuchają');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_001', 1, 'fr', 'Bonjour, comment allez-vous ?', 'Здравствуйте, как вы поживаете?');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_002', 1, 'fr', 'Merci beaucoup pour votre aide.', 'Большое спасибо за вашу помощь.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_003', 1, 'fr', 'Oui, je comprends.', 'Да, я понимаю.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_004', 1, 'fr', 'Non, ce n''est pas possible.', 'Нет, это невозможно.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_005', 1, 'fr', 'Le chat dort sur le canapé.', 'Кот спит на диване.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_006', 1, 'fr', 'La maison est grande et belle.', 'Дом большой и красивый.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_007', 1, 'fr', 'Je voudrais un verre d''eau, s''il vous plaît.', 'Я бы хотел стакан воды, пожалуйста.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_008', 1, 'fr', 'Nous allons manger au restaurant ce soir.', 'Мы пойдём есть в ресторан сегодня вечером.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_009', 1, 'fr', 'Les enfants doivent dormir tôt.', 'Дети должны ложиться спать рано.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_010', 1, 'fr', 'La femme lit un livre dans le parc.', 'Женщина читает книгу в парке.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_011', 1, 'fr', 'L''homme marche dans la rue.', 'Мужчина идёт по улице.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_012', 1, 'fr', 'C''est un grand arbre.', 'Это большое дерево.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_013', 1, 'fr', 'Il habite dans un petit appartement.', 'Он живёт в маленькой квартире.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_014', 1, 'fr', 'Elle porte une robe rouge.', 'Она носит красное платье.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_015', 1, 'fr', 'Le ciel est bleu aujourd''hui.', 'Небо сегодня голубое.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_016', 1, 'fr', 'Tu parles très bien français.', 'Ты очень хорошо говоришь по-французски.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_017', 1, 'fr', 'Je vais à l''école tous les jours.', 'Я хожу в школу каждый день.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_018', 1, 'fr', 'Est-ce que tu viens avec nous ?', 'Ты идёшь с нами?');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_019', 1, 'fr', 'J''achète du pain à la boulangerie.', 'Я покупаю хлеб в булочной.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_020', 1, 'fr', 'Ce vin rouge est excellent.', 'Это красное вино превосходно.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_021', 1, 'fr', 'Il fait beau aujourd''hui.', 'Сегодня хорошая погода.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_022', 1, 'fr', 'Je dois partir maintenant.', 'Мне нужно уйти сейчас.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_023', 1, 'fr', 'Il est toujours en retard.', 'Он всегда опаздывает.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_024', 1, 'fr', 'Je n''ai jamais visité Paris.', 'Я никогда не был в Париже.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_025', 1, 'fr', 'Peut-être qu''il viendra demain.', 'Может быть, он придёт завтра.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_026', 1, 'fr', 'Je ne comprends pas cette phrase.', 'Я не понимаю это предложение.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_027', 1, 'fr', 'Je sais que c''est difficile.', 'Я знаю, что это трудно.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_028', 1, 'fr', 'Tu connais mon frère ?', 'Ты знаешь моего брата?');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_029', 1, 'fr', 'La ville est très animée le soir.', 'Город очень оживлённый по вечерам.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_030', 1, 'fr', 'Le travail commence à neuf heures.', 'Работа начинается в девять часов.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_031', 1, 'fr', 'Il faut choisir entre les deux.', 'Нужно выбрать между двумя.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_032', 1, 'fr', 'Cet exercice est très difficile.', 'Это упражнение очень трудное.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_033', 1, 'fr', 'Le français n''est pas facile à apprendre.', 'Французский нелегко выучить.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_034', 1, 'fr', 'Je vais souvent au cinéma.', 'Я часто хожу в кино.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_035', 1, 'fr', 'Nous travaillons ensemble sur ce projet.', 'Мы работаем вместе над этим проектом.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_036', 1, 'fr', 'Ne perds pas tes clés !', 'Не потеряй свои ключи!');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_037', 1, 'fr', 'J''ai trouvé un bon restaurant.', 'Я нашёл хороший ресторан.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_038', 1, 'fr', 'Attendez-moi, s''il vous plaît.', 'Подождите меня, пожалуйста.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_039', 1, 'fr', 'Je crois qu''il a raison.', 'Я думаю, что он прав.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_040', 1, 'fr', 'Elle aime lire avant de dormir.', 'Она любит читать перед сном.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_041', 1, 'fr', 'Il écrit une lettre à sa mère.', 'Он пишет письмо своей маме.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_042', 1, 'fr', 'C''est une bonne question.', 'Это хороший вопрос.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_043', 1, 'fr', 'La réponse est simple.', 'Ответ простой.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_044', 1, 'fr', 'Qu''est-ce que tu penses de ce film ?', 'Что ты думаешь об этом фильме?');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_045', 1, 'fr', 'Je me sens bien aujourd''hui.', 'Я чувствую себя хорошо сегодня.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_046', 1, 'fr', 'Quel est le chemin le plus court ?', 'Какой путь самый короткий?');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_047', 1, 'fr', 'La lumière du soleil entre par la fenêtre.', 'Солнечный свет проникает через окно.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_048', 1, 'fr', 'J''ai un nouveau téléphone.', 'У меня новый телефон.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_049', 1, 'fr', 'La chambre est propre.', 'Комната чистая.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_050', 1, 'fr', 'Es-tu libre ce week-end ?', 'Ты свободен в эти выходные?');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_051', 1, 'fr', 'J''ai confiance en toi.', 'Я тебе доверяю.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_052', 1, 'fr', 'Il vit dans la crainte de perdre son emploi.', 'Он живёт в страхе потерять работу.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_053', 1, 'fr', 'Il est fatigué, pourtant il continue.', 'Он устал, однако продолжает.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_054', 1, 'fr', 'Il pleut, mais je sors quand même.', 'Идёт дождь, но я всё равно выхожу.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_055', 1, 'fr', 'En effet, vous avez raison.', 'Действительно, вы правы.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_056', 1, 'fr', 'C''est une démarche importante.', 'Это важный шаг.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_057', 1, 'fr', 'Méfiez-vous des apparences.', 'Не доверяйте внешности.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_058', 1, 'fr', 'Nous devons résoudre ce problème.', 'Мы должны решить эту проблему.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_059', 1, 'fr', 'Il faut prévenir la police.', 'Нужно предупредить полицию.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_060', 1, 'fr', 'Son comportement est étrange.', 'Его поведение странное.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_061', 1, 'fr', 'L''enjeu est considérable.', 'Ставки очень высоки.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_062', 1, 'fr', 'Désormais, je ferai attention.', 'Отныне я буду осторожен.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_063', 1, 'fr', 'Appelle-moi dès que tu arrives.', 'Позвони мне, как только приедешь.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_064', 1, 'fr', 'Il s''est rendu compte de son erreur.', 'Он осознал свою ошибку.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_065', 1, 'fr', 'Il y a une nuance entre les deux mots.', 'Между двумя словами есть нюанс.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_066', 1, 'fr', 'Il ne faut pas méconnaître l''importance de ce problème.', 'Не стоит недооценивать важность этой проблемы.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_067', 1, 'fr', 'Les négociations ont abouti à un accord.', 'Переговоры привели к соглашению.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_070', 1, 'fr', 'Elle est parvenue à terminer le projet à temps.', 'Ей удалось завершить проект вовремя.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_071', 1, 'fr', 'Cette méthode s''est avérée efficace.', 'Этот метод оказался эффективным.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_073', 1, 'fr', 'L''alarme a déclenché une panique générale.', 'Сигнализация вызвала всеобщую панику.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_074', 1, 'fr', 'Le médecin préconise un régime équilibré.', 'Врач рекомендует сбалансированную диету.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_076', 1, 'fr', 'Ce médicament atténue la douleur.', 'Это лекарство смягчает боль.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_078', 1, 'fr', 'Le rapport met en exergue les risques principaux.', 'Доклад подчёркивает основные риски.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_081', 1, 'fr', 'J''aime beaucoup la musique.', 'Я очень люблю музыку.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_082', 1, 'fr', 'Donne-moi ton avis.', 'Скажи мне своё мнение.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_083', 1, 'fr', 'Elle travaille dans un hôpital.', 'Она работает в больнице.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_084', 1, 'fr', 'Le train arrive à midi.', 'Поезд прибывает в полдень.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_085', 1, 'fr', 'Je voudrais demander un conseil.', 'Я хотел бы попросить совет.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_086', 1, 'fr', 'Regarde le coucher de soleil !', 'Посмотри на закат!');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_087', 1, 'fr', 'Écoute cette chanson.', 'Послушай эту песню.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_088', 1, 'fr', 'Le gouvernement a décidé d''abaisser les impôts.', 'Правительство решило снизить налоги.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_089', 1, 'fr', 'Elle a accepté l''invitation avec plaisir.', 'Она с удовольствием приняла приглашение.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_090', 1, 'fr', 'Je vais t''accompagner à la gare.', 'Я провожу тебя на вокзал.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_091', 1, 'fr', 'Le directeur a accordé une pause aux employés.', 'Директор предоставил сотрудникам перерыв.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_092', 1, 'fr', 'Accroche ton manteau dans l''entrée.', 'Повесь пальто в прихожей.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_093', 1, 'fr', 'On l''accuse d''avoir menti.', 'Его обвиняют во лжи.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_094', 1, 'fr', 'Les touristes admirent la tour Eiffel.', 'Туристы любуются Эйфелевой башней.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_095', 1, 'fr', 'Les enfants adorent le chocolat.', 'Дети обожают шоколад.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_096', 1, 'fr', 'Il a adressé une lettre au maire.', 'Он направил письмо мэру.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_097', 1, 'fr', 'Peux-tu m''aider à porter ces sacs ?', 'Можешь помочь мне нести эти сумки?');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_098', 1, 'fr', 'N''oublie pas d''ajouter du sel.', 'Не забудь добавить соль.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_099', 1, 'fr', 'Ce spectacle amuse beaucoup les enfants.', 'Это представление очень забавляет детей.');
