INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_212', 1, 'fr', 'Laisse-moi tranquille, s''il te plaît.', 'Оставь меня в покое, пожалуйста.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_213', 1, 'fr', 'Je dois laver la voiture ce week-end.', 'Мне нужно помыть машину в выходные.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_214', 1, 'fr', 'Nous avons loué un appartement près de la mer.', 'Мы сняли квартиру возле моря.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_215', 1, 'fr', 'Tu me manques beaucoup.', 'Я очень по тебе скучаю.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_216', 1, 'fr', 'Nous marchons le long de la rivière.', 'Мы гуляем вдоль реки.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_217', 1, 'fr', 'Tu mérites des vacances après tout ce travail.', 'Ты заслуживаешь отпуск после всей этой работы.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_218', 1, 'fr', 'Il mesure un mètre quatre-vingts.', 'Его рост — метр восемьдесят.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_219', 1, 'fr', 'Monte au deuxième étage.', 'Поднимись на второй этаж.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_220', 1, 'fr', 'Montre-moi tes photos de vacances.', 'Покажи мне свои фотографии из отпуска.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_221', 1, 'fr', 'Ne te moque pas de lui.', 'Не смейся над ним.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_222', 1, 'fr', 'Ils négocient les conditions du contrat.', 'Они обсуждают условия контракта.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_223', 1, 'fr', 'Il nie avoir commis cette erreur.', 'Он отрицает, что совершил эту ошибку.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_224', 1, 'fr', 'On l''a nommé directeur de l''école.', 'Его назначили директором школы.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_225', 1, 'fr', 'Note cette adresse dans ton carnet.', 'Запиши этот адрес в блокнот.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_226', 1, 'fr', 'Ce travail occupe tout mon temps.', 'Эта работа занимает всё моё время.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_227', 1, 'fr', 'J''ai oublié mon parapluie au bureau.', 'Я забыл свой зонтик в офисе.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_228', 1, 'fr', 'Pardonne-moi, je suis en retard.', 'Прости меня, я опоздал.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_229', 1, 'fr', 'Tout le monde peut participer au concours.', 'Все могут участвовать в конкурсе.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_230', 1, 'fr', 'Je passe devant ta maison chaque matin.', 'Я прохожу мимо твоего дома каждое утро.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_231', 1, 'fr', 'Il pêche dans la rivière tous les dimanches.', 'Он рыбачит на реке каждое воскресенье.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_232', 1, 'fr', 'Peigne-toi les cheveux avant de sortir.', 'Расчеши волосы перед выходом.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_233', 1, 'fr', 'Elle m''a persuadé d''accepter l''offre.', 'Она убедила меня принять предложение.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_234', 1, 'fr', 'Je plaisante, ne t''inquiète pas !', 'Я шучу, не волнуйся!');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_235', 1, 'fr', 'Nous avons planté des roses dans le jardin.', 'Мы посадили розы в саду.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_236', 1, 'fr', 'Le bébé pleure parce qu''il a faim.', 'Малыш плачет, потому что голоден.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_237', 1, 'fr', 'Plie ta serviette après le repas.', 'Сложи салфетку после еды.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_238', 1, 'fr', 'Elle porte une jolie robe bleue.', 'Она носит красивое голубое платье.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_239', 1, 'fr', 'Pose tes affaires sur la table.', 'Положи свои вещи на стол.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_240', 1, 'fr', 'Ne pousse pas dans la file d''attente !', 'Не толкайся в очереди!');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_241', 1, 'fr', 'Maman prépare le dîner dans la cuisine.', 'Мама готовит ужин на кухне.');
