INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_246', 1, 'fr', 'Il doit prouver son innocence.', 'Он должен доказать свою невиновность.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_247', 1, 'fr', 'Ce fromage pue, mais il est délicieux.', 'Этот сыр воняет, но он восхитительный.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_248', 1, 'fr', 'Il a quitté la ville pour la campagne.', 'Он уехал из города в деревню.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_249', 1, 'fr', 'Raconte-moi ce qui s''est passé.', 'Расскажи мне, что произошло.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_250', 1, 'fr', 'Ne t''inquiète pas, je te rassure, tout ira bien.', 'Не волнуйся, уверяю тебя, всё будет хорошо.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_251', 1, 'fr', 'Il a refusé de répondre à la question.', 'Он отказался отвечать на вопрос.');
