INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_253', 1, 'fr', 'As-tu remarqué quelque chose d''étrange ?', 'Ты заметил что-то странное?');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_254', 1, 'fr', 'Je vous remercie de votre gentillesse.', 'Благодарю вас за вашу доброту.');
