INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_274', 1, 'fr', 'Une rivière sépare les deux villages.', 'Река разделяет две деревни.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_275', 1, 'fr', 'L''arbitre siffle la fin du match.', 'Судья свистит конец матча.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_276', 1, 'fr', 'Je voudrais signaler un problème.', 'Я хотел бы сообщить о проблеме.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_277', 1, 'fr', 'Signez en bas de la page, s''il vous plaît.', 'Подпишитесь внизу страницы, пожалуйста.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_278', 1, 'fr', 'Que signifie ce mot en français ?', 'Что означает это слово по-французски?');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_279', 1, 'fr', 'Nous allons skier dans les Alpes cet hiver.', 'Мы поедем кататься на лыжах в Альпы этой зимой.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_280', 1, 'fr', 'Le téléphone sonne sans arrêt.', 'Телефон звонит без остановки.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_281', 1, 'fr', 'Le vent souffle très fort ce soir.', 'Ветер дует очень сильно сегодня вечером.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_282', 1, 'fr', 'Je vous souhaite un joyeux anniversaire.', 'Желаю вам счастливого дня рождения.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_283', 1, 'fr', 'Je ne supporte pas le bruit.', 'Я не выношу шум.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_284', 1, 'fr', 'Je suppose que tu as raison.', 'Полагаю, что ты прав.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_285', 1, 'fr', 'Je te téléphonerai ce soir.', 'Я тебе позвоню сегодня вечером.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_286', 1, 'fr', 'Il a tenté de battre le record.', 'Он попытался побить рекорд.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_287', 1, 'fr', 'J''ai terminé mon travail pour aujourd''hui.', 'Я закончил свою работу на сегодня.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_288', 1, 'fr', 'Tire la porte vers toi.', 'Потяни дверь на себя.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_289', 1, 'fr', 'Les feuilles tombent en automne.', 'Листья падают осенью.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_290', 1, 'fr', 'Ne touche pas à la peinture, elle est fraîche.', 'Не трогай краску, она свежая.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_291', 1, 'fr', 'Tournez à gauche au feu rouge.', 'Поверните налево на светофоре.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_292', 1, 'fr', 'Il tousse depuis une semaine.', 'Он кашляет уже неделю.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_293', 1, 'fr', 'Ce médecin traite les maladies de peau.', 'Этот врач лечит кожные заболевания.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_294', 1, 'fr', 'Regarde à gauche et à droite avant de traverser la rue.', 'Посмотри налево и направо перед тем, как перейти улицу.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_295', 1, 'fr', 'Les apparences peuvent tromper.', 'Внешность может быть обманчива.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_296', 1, 'fr', 'Le froid a tué toutes les plantes.', 'Мороз погубил все растения.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_297', 1, 'fr', 'Il a usé ses chaussures à force de marcher.', 'Он износил обувь от долгой ходьбы.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_298', 1, 'fr', 'Utilisez un mot de passe sécurisé.', 'Используйте надёжный пароль.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_299', 1, 'fr', 'Les prix varient selon la saison.', 'Цены варьируются в зависимости от сезона.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_300', 1, 'fr', 'Vérifie que la porte est bien fermée.', 'Проверь, что дверь хорошо закрыта.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_301', 1, 'fr', 'Verse-moi un peu de lait, s''il te plaît.', 'Налей мне немного молока, пожалуйста.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_302', 1, 'fr', 'L''entreprise vise le marché international.', 'Компания нацелена на международный рынок.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_303', 1, 'fr', 'Nous avons visité le musée du Louvre.', 'Мы посетили музей Лувр.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_304', 1, 'fr', 'Les oiseaux volent vers le sud en hiver.', 'Зимой птицы летят на юг.');
INSERT INTO vocab_example (vocab_id, sort_order, lang, source_text, target_text) VALUES ('fr_305', 1, 'fr', 'Les citoyens votent dimanche prochain.', 'Граждане голосуют в следующее воскресенье.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_088', '{"baisser","diminuer","réduire"}', 'Абстрактное понижение: уровень, температура, цена, планка.', 'В отличие от baisser (физическое опускание вниз), abaisser — переносное: abaisser le prix (снизить цену), abaisser le seuil (понизить порог). Baisser la tête — опустить голову, но abaisser la température — понизить температуру.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_113', '{"abaisser","diminuer","réduire"}', 'Физическое опускание или снижение. Часто с частями тела или конкретными предметами.', 'Baisser — опускать вниз физически: baisser la tête (опустить голову), baisser le volume (убавить звук). Abaisser — абстрактное понижение. Diminuer — уменьшение количества.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_158', '{"baisser","réduire","abaisser"}', 'Уменьшение количества, размера, интенсивности.', 'Diminuer — уменьшать в количестве или степени: diminuer les dépenses (сократить расходы). Baisser — опускать. Réduire — сокращать (более формально).');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_027', '{"connaître"}', 'Знать факты, информацию, уметь что-то делать. После savoir часто идёт инфинитив или que.', 'Savoir = знать факт / уметь: Je sais nager (умею плавать), Je sais qu''il est parti (знаю, что он ушёл). Connaître = быть знакомым с: Je connais Paris (знаю Париж). Нельзя сказать *Je connais que...');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_028', '{"savoir"}', 'Быть знакомым с человеком, местом, произведением. Всегда с прямым дополнением (существительным).', 'Connaître = быть знакомым: Je connais cette chanson (я знаю эту песню). Savoir = владеть информацией / уметь. Connaître никогда не используется с que или инфинитивом.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_256', '{"retourner","revenir"}', 'Возвращаться домой или внутрь привычного места.', 'Rentrer = вернуться домой / в привычное место: Je rentre à la maison. Retourner = вернуться куда-то, где уже был раньше (не обязательно домой): Je retourne à Paris. Revenir = вернуться сюда (к говорящему).');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_263', '{"rentrer","revenir"}', 'Вернуться в место, где уже был. Также: перевернуть (предмет).', 'Retourner = вернуться ТУДА (от говорящего): Il retourne en France. Rentrer = вернуться домой. Revenir = вернуться СЮДА (к говорящему): Il revient demain.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_152', '{"souhaiter","vouloir"}', 'Желать с сильным личным влечением. Более интенсивно, чем souhaiter.', 'Désirer — сильное, часто страстное желание: désirer le succès. Souhaiter — вежливое пожелание: Je vous souhaite bonne chance. Vouloir — нейтральное «хотеть».');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_282', '{"désirer","vouloir","espérer"}', 'Вежливое пожелание или надежда. Формальнее, чем vouloir.', 'Souhaiter = желать (вежливо): Je souhaite vous aider. Désirer = желать (сильно, лично). Espérer = надеяться (с оттенком ожидания).');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_262', '{"demeurer"}', 'Оставаться на месте или в состоянии. Повседневное слово.', 'Rester — обычное «оставаться»: Je reste ici (я остаюсь здесь). Demeurer — литературное / формальное: Il demeure silencieux (он пребывает в молчании). Demeurer также = проживать (формально).');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_148', '{"rester","habiter"}', 'Литературное «оставаться» или формальное «проживать».', 'Demeurer = пребывать (книжн.): La question demeure (вопрос остаётся). Также = проживать: Il demeure à Lyon. Habiter — обычное слово для «жить где-то». Rester — повседневное «оставаться».');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_199', '{"demeurer","vivre","séjourner"}', 'Жить, проживать постоянно. Самое обычное слово.', 'Habiter = жить где-то постоянно: J''habite à Moscou. Demeurer = то же, но формальнее. Séjourner = временное пребывание (гостить).');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_272', '{"habiter","demeurer","rester"}', 'Временно пребывать, гостить.', 'Séjourner = быть где-то временно: séjourner à l''hôtel (остановиться в отеле). Habiter = жить постоянно. Rester = оставаться (не уезжать).');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_242', '{"représenter","montrer"}', 'Представлять (кого-то кому-то), предъявлять, излагать.', 'Présenter = познакомить, показать, изложить: présenter un ami (представить друга), présenter un projet. Représenter = быть представителем или символом: Il représente la France (он представляет Францию).');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_260', '{"présenter","symboliser"}', 'Быть представителем, символизировать, изображать.', 'Représenter = представлять (от чьего-то имени) или символизировать: Ce tableau représente la liberté. Présenter = лично представить / изложить.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_112', '{"risquer","oser"}', 'Рисковать, отваживаться на что-то новое. Чаще возвратный: s''aventurer.', 'S''aventurer = отважиться, пуститься в приключение: s''aventurer dans la forêt. Risquer = подвергаться риску: risquer sa vie (рисковать жизнью). Aventurer — про действие, risquer — про опасность.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_267', '{"aventurer","oser"}', 'Подвергаться опасности, ставить на кон.', 'Risquer = рисковать (есть опасность): risquer un accident. S''aventurer = смело идти в неизведанное. Risquer de + inf = есть вероятность: Il risque de pleuvoir (может пойти дождь).');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_115', '{"plaisanter"}', 'Шутить (разговорное). Чаще в неформальной речи.', 'Blaguer — разговорное «шутить, прикалываться»: Tu blagues? (Ты шутишь?). Plaisanter — нейтральное, можно в формальной речи: Je plaisantais (я пошутил).');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_234', '{"blaguer"}', 'Шутить (нейтральное). Подходит для любого контекста.', 'Plaisanter — универсальное «шутить»: Vous plaisantez? (Вы шутите?). Blaguer — более фамильярное, разговорное.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_093', '{"blâmer","inculper"}', 'Обвинять (официально или неформально). Часто с de + inf.', 'Accuser = обвинить (конкретно): accuser quelqu''un de vol (обвинить в краже). Blâmer = порицать, осуждать (моральная оценка): blâmer son comportement.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_116', '{"accuser","critiquer","reprocher"}', 'Порицать, осуждать поведение. Моральная оценка.', 'Blâmer = моральное осуждение: On le blâme pour sa paresse. Accuser = формальное обвинение. Reprocher = упрекнуть (мягче).');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_037', '{"retrouver","découvrir"}', 'Находить (что-то новое или в результате поиска). Также: считать, полагать.', 'Trouver = найти: J''ai trouvé mes clés. Также = считать: Je trouve ça bizarre. Retrouver = найти СНОВА (то, что было потеряно) или встретиться с кем-то: Je retrouve mes amis au café.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_264', '{"trouver"}', 'Находить снова (утерянное). Встречаться (с друзьями).', 'Retrouver = re + trouver: найти повторно / воссоединиться: retrouver la santé (восстановить здоровье), retrouver un ami (встретиться с другом). Trouver = найти впервые.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_016', '{"causer","discuter","bavarder"}', 'Говорить, разговаривать. Самый общий глагол речи.', 'Parler = говорить (общее): parler français, parler à quelqu''un. Discuter = обсуждать (тему). Raconter = рассказывать (историю). Causer = беседовать (разг.) / вызывать.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_249', '{"dire","narrer"}', 'Рассказывать историю, описывать события.', 'Raconter = рассказать историю: raconter une aventure. Dire = сказать (конкретные слова). Parler = говорить (в общем).');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_123', '{"parler","bavarder","provoquer"}', '1) Беседовать (разг.) 2) Вызывать, быть причиной.', 'Causer имеет ДВА значения: 1) causer avec qqn = болтать (разг.); 2) causer un problème = вызвать проблему. Parler — нейтральное «говорить». Bavarder — болтать без дела.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_114', '{"causer","parler","papoter"}', 'Болтать, трепаться. Лёгкий непринуждённый разговор.', 'Bavarder = болтать (ни о чём серьёзном): bavarder entre amis. Discuter = обсуждать серьёзную тему. Parler — нейтральное.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_160', '{"parler","débattre"}', 'Обсуждать тему, дискутировать.', 'Discuter = обсуждать (конкретную тему): discuter du projet. Parler = говорить (общее). Débattre = спорить (формально, с аргументами).');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_151', '{"gaspiller","consommer"}', 'Тратить (деньги, энергию). Нейтральное слово.', 'Dépenser = тратить (нейтрально): dépenser de l''argent. Gaspiller = тратить ВПУСТУЮ, расточать: gaspiller l''eau.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_194', '{"dépenser","dilapider"}', 'Тратить впустую, расточать. Всегда негативная коннотация.', 'Gaspiller = бесполезная трата: gaspiller son talent (растрачивать талант). Dépenser — нейтрально: можно dépenser wisely.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_058', '{"décider","régler"}', 'Решать проблему, находить решение.', 'Résoudre = решить ПРОБЛЕМУ: résoudre une équation, résoudre un conflit. Décider = принять РЕШЕНИЕ (выбор): décider de partir. Régler = урегулировать.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_146', '{"résoudre","trancher","choisir"}', 'Принимать решение, делать выбор.', 'Décider = сделать выбор: J''ai décidé de rester. Résoudre = найти решение проблемы. Choisir = выбирать из вариантов. Trancher = решить категорично.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_238', '{"apporter","emporter","transporter"}', 'Нести, носить (на себе). Также: носить одежду.', 'Porter = нести/носить (на себе): porter un sac, porter une robe. Apporter = принести (сюда). Emporter = унести (отсюда). Transporter = перевозить.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_100', '{"porter","amener","emporter"}', 'Приносить (предмет сюда, к говорящему).', 'Apporter = принести ВЕЩЬ сюда: Apporte-moi le livre. Amener = привести ЧЕЛОВЕКА сюда. Emporter = унести вещь отсюда. Emmener = увести человека отсюда.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_283', '{"endurer","tolérer","soutenir"}', 'Выдерживать, терпеть. Внимание: НЕ значит «поддерживать» (= soutenir).', 'Faux ami! Supporter ≠ англ. support. Supporter = терпеть: Je ne supporte pas le bruit. Для «поддерживать» используйте soutenir.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_220', '{"indiquer","démontrer","présenter"}', 'Показывать (жестом, действием, наглядно).', 'Montrer = показать (наглядно): Montre-moi ta photo. Indiquer = указать (направление, информацию): indiquer le chemin. Démontrer = доказать/продемонстрировать.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_203', '{"montrer","signaler","désigner"}', 'Указывать, обозначать. Часто о направлении или информации.', 'Indiquer = указать/подсказать: Pouvez-vous m''indiquer la gare? Montrer = показать наглядно. Signaler = обратить внимание, сообщить.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_128', '{"rechercher","fouiller"}', 'Искать. Chercher à + inf = пытаться.', 'Chercher = искать (процесс): Je cherche mes clés. Trouver = найти (результат). Fouiller = обыскивать (тщательно, в вещах). Rechercher = разыскивать (целенаправленно).');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_105', '{"cesser","stopper"}', 'Останавливать, прекращать. Также: арестовывать.', 'Arrêter = остановить (действие или человека): arrêter la voiture, arrêter un criminel. Cesser = прекратить (формальнее, абстрактнее): cesser les hostilités. Arrêter de + inf = перестать делать.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_125', '{"arrêter","interrompre"}', 'Прекращать (формальное, книжное).', 'Cesser = прекратить (формально): cesser de fumer, sans cesse (не переставая). Arrêter — более разговорное: Arrête de parler! (Перестань говорить!).');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_193', '{"conserver","préserver","retenir"}', 'Хранить, сохранять, оберегать. Также: сторожить.', 'Garder = хранить / оберегать: garder un secret, garder les enfants. Conserver = сохранять (в хорошем состоянии): conserver les aliments. Préserver = защитить от разрушения.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_111', '{"accroître","élever","hausser"}', 'Увеличивать (цену, количество, зарплату).', 'Augmenter = увеличить (нейтрально, повседневно): augmenter le prix. Accroître = наращивать (формально, книжно): accroître la productivité.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_085', '{"prier","interroger","questionner"}', 'Просить или спрашивать. Самый общий глагол.', 'Demander = просить / спрашивать: demander de l''aide, demander le chemin. Prier = просить (вежливо/умоляюще): Je vous prie de m''excuser. Interroger = допрашивать / задавать вопросы.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_244', '{"demander","supplier","implorer"}', 'Молиться. Также: вежливо просить (Je vous prie).', 'Prier = молиться: prier Dieu. Также вежливая просьба: Je vous en prie (пожалуйста). Demander — обычная просьба. Supplier = умолять.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_174', '{"pénétrer"}', 'Входить. Самое обычное слово.', 'Entrer = войти (нейтрально): entrer dans la maison. Pénétrer = проникнуть (с усилием или глубоко): pénétrer dans la forêt. Pénétrer — более драматичное.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_248', '{"sortir","partir","abandonner"}', 'Покидать (место, человека). Оттенок окончательности.', 'Quitter = покинуть (с оттенком «насовсем»): quitter son emploi, quitter quelqu''un. Sortir = просто выйти. Partir = отправиться в путь.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_216', '{"promener","fonctionner"}', '1) Ходить пешком. 2) Работать, функционировать (разг.).', 'Marcher = идти пешком: marcher vite. Также = работать: Ça marche! (Работает! / Договорились!). Se promener = гулять (для удовольствия). Fonctionner = функционировать (формально).');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_044', '{"croire","réfléchir","songer"}', 'Думать, полагать. Penser à = думать о. Penser de = считать (мнение).', 'Penser = думать/полагать: Je pense que oui. Croire = верить / считать (менее уверенно): Je crois qu''il viendra. Réfléchir = размышлять (глубоко, обдумывать): Laissez-moi réfléchir.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_039', '{"penser","estimer"}', 'Верить, полагать. Croire en = верить в. Croire à = верить (во что-то).', 'Croire = верить: croire en Dieu. Также = полагать (с меньшей уверенностью, чем penser): Je crois que c''est vrai. Penser — более взвешенное мнение.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_038', '{"espérer","patienter"}', 'Ждать (кого-то/чего-то). Физическое ожидание.', 'Attendre = ждать (конкретно): attendre le bus, attendre quelqu''un. Espérer = надеяться: J''espère qu''il viendra. Patienter = терпеливо ждать (вежливое): Veuillez patienter.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_045', '{"ressentir"}', '1) Чувствовать. 2) Пахнуть. Многозначный глагол.', 'Sentir = чувствовать (физически) + пахнуть: sentir le parfum (чувствовать аромат), ça sent bon (хорошо пахнет). Ressentir = испытывать (эмоции, глубокие чувства): ressentir de la joie.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_298', '{"employer","user","se servir de"}', 'Использовать. Самый общий и нейтральный глагол.', 'Utiliser = использовать (универсальное). Employer = применять (формальнее) / нанимать (людей). Se servir de = пользоваться (инструментом). User = изнашивать.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_241', '{"apprêter","organiser"}', 'Готовить, подготавливать. Универсальное слово.', 'Préparer = готовить (общее): préparer le dîner, préparer un examen. S''apprêter = собираться (что-то сделать): Je m''apprête à partir.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_012', '{"gros","vaste","large"}', 'Большой (по размеру, высоте, значимости). Также: высокий (о росте).', 'Grand = большой по размеру/высоте/значимости: un grand homme (великий человек), une grande maison. Gros = большой по объёму/толщине: un gros chat (толстый кот), un gros problème (большая проблема).');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_032', '{"dur","compliqué","ardu"}', 'Трудный, сложный. Нейтральное слово.', 'Difficile = трудный (нейтрально): un exercice difficile. Dur = 1) твёрдый физически: un lit dur; 2) тяжёлый (разг.): C''est dur! Compliqué = запутанный.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_089', '{"accorder","admettre","consentir"}', 'Принимать (предложение, ситуацию). Accepter de + inf.', 'Accepter = принять (то, что предложено): accepter une invitation. Accorder = предоставить (одобрение, разрешение): accorder un prêt. Admettre = признать (факт).');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_091', '{"accepter","donner","attribuer"}', 'Предоставлять, согласовывать. Также: настраивать (инструмент).', 'Accorder = предоставить (формально): accorder une faveur. Accepter = принять (от другого). Accorder может также = согласовывать (грамматически): accorder l''adjectif.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_212', '{"quitter","abandonner","permettre"}', 'Оставлять, позволять. Laisser + inf = позволить делать.', 'Laisser = оставить / позволить: Laisse-moi tranquille (оставь меня), laisser entrer (позволить войти). Quitter = покинуть (уйти). Abandonner = бросить (насовсем).');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_215', '{"rater"}', 'ВНИМАНИЕ: конструкция обратная русскому! Tu me manques = Я скучаю по тебе (ты мне недостаёшь).', 'Manquer = 1) скучать (обратная конструкция!): Tu me manques (= я скучаю по тебе); 2) не хватать: Il manque du sel; 3) пропустить: manquer le train. Rater = провалить / пропустить (разг.).');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_133', '{"calculer","envisager"}', 'Считать (числа). Также: намереваться (compter + inf).', 'Compter = считать числа: compter jusqu''à dix. Также = рассчитывать: Je compte sur toi (рассчитываю на тебя). Compter + inf = намереваться: Je compte partir demain.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_226', '{"remplir"}', 'Занимать (пространство, время, должность). S''occuper de = заниматься чем-то.', 'Occuper = занимать: occuper un poste. S''occuper de = заботиться / заниматься: Je m''occupe des enfants. Emprunter = занимать ДЕНЬГИ (брать в долг).');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_169', '{"prêter"}', 'Занимать (брать в долг). Противоположность prêter.', 'Emprunter = БРАТЬ в долг: emprunter de l''argent (занять денег). Prêter = ДАВАТЬ в долг: prêter un livre. Не путайте! Emprunter — берёшь, prêter — даёшь.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_243', '{"emprunter"}', 'Давать в долг, одалживать. Противоположность emprunter.', 'Prêter = ДАВАТЬ в долг: prêter de l''argent à un ami. Emprunter = БРАТЬ в долг. Мнемоника: prêter — «пре-доставлять».');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_049', '{}', 'ДВА значения в зависимости от позиции!', 'ПЕРЕД существительным: собственный — mon propre avis (моё собственное мнение). ПОСЛЕ существительного: чистый — une chambre propre (чистая комната). Позиция меняет смысл!');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_304', '{}', 'ДВА значения: 1) красть 2) летать.', 'Voler = 1) летать: L''oiseau vole; 2) красть: voler de l''argent. Контекст решает. Un vol = 1) полёт; 2) кража.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_214', '{}', 'ДВА значения: 1) арендовать 2) хвалить.', 'Louer = 1) арендовать/сдавать: louer un appartement; 2) хвалить (книжн.): louer ses qualités. В повседневной речи обычно = арендовать.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_106', '{"aider","participer"}', 'Faux ami! Assister à = присутствовать при. НЕ «помогать»!', 'Assister à = присутствовать: assister à un concert (побывать на концерте). Для «помогать» используйте aider. Assister quelqu''un = помогать (только с прямым дополнением, формально).');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_186', '{"se méfier"}', 'Se fier à = доверять. Антоним: se méfier de.', 'Se fier à = доверять: Je me fie à toi. Se méfier de = не доверять, остерегаться: Méfiez-vous de lui. Также: fier (прил.) = гордый.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_057', '{"fier","douter"}', 'Не доверять, остерегаться. Антоним se fier.', 'Se méfier de = остерегаться: Méfie-toi de cette offre. Se fier à = доверять (антоним). Douter = сомневаться (менее категорично).');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_280', '{"téléphoner","klaxonner"}', 'Звонить, звенеть (о звуке). Не «звонить по телефону»!', 'Sonner = издавать звук: Le téléphone sonne (телефон звонит). Téléphoner = звонить по телефону (действие человека). Klaxonner = сигналить (в машине).');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_048', '{"neuf"}', 'Новый (для владельца). Не обязательно с завода.', 'Nouveau = новый для тебя: une nouvelle voiture (новая для тебя машина, может быть б/у). Neuf = совсем новый, с завода: une voiture neuve (новёхонькая машина).');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_050', '{"gratuit"}', 'Свободный. НЕ путать с gratuit (бесплатный).', 'Libre = свободный: un homme libre, une place libre. Gratuit = бесплатный: l''entrée est gratuite. «Свободный вход» = entrée libre (НЕ gratuite, если имеется в виду «можно войти»).');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_081', '{"adorer","apprécier"}', 'Любить, нравиться. Aimer bien = нравиться (слабее, чем aimer!).', 'Aimer = любить: J''aime mes parents. Aimer bien = нравиться (СЛАБЕЕ!): Je l''aime bien (он мне нравится, но не любовь). Adorer = обожать (сильнее aimer для вещей).');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_095', '{"aimer","idolâtrer"}', 'Обожать. Сильнее aimer для хобби/вещей, но слабее для людей.', 'Adorer = обожать (вещи/действия): J''adore le chocolat! Для людей aimer сильнее: J''aime mon mari (люблю) vs J''adore mon prof (обожаю, но не романтично).');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_255', '{"retrouver","croiser"}', 'Встретить (впервые или случайно).', 'Rencontrer = встретить (впервые/случайно): J''ai rencontré un ami. Retrouver = встретиться (по договорённости): On se retrouve au café. Croiser = столкнуться мельком.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_084', '{"parvenir","aboutir","venir"}', '1) Приезжать, прибывать. 2) Случаться: Il arrive que...', 'Arriver = прибыть: Le train arrive. Также = случаться: Qu''est-ce qui est arrivé? Parvenir = достичь (с трудом): parvenir au sommet. Aboutir = привести к результату.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_067', '{"arriver","parvenir","mener"}', 'Приводить к результату, завершаться чем-то.', 'Aboutir = привести к результату: Les négociations ont abouti (переговоры увенчались успехом). Aboutir à = закончиться чем-то. Parvenir = достичь (лично, с усилием).');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_137', '{"poursuivre","persévérer"}', 'Продолжать. Самый обычный глагол.', 'Continuer = продолжать (нейтрально): continuer à travailler. Poursuivre = продолжать (формальнее) + преследовать: poursuivre un objectif (преследовать цель).');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_287', '{"finir","achever","accomplir"}', 'Заканчивать, завершать.', 'Terminer = завершить (нейтрально): terminer un projet. Finir = закончить (разговорнее): J''ai fini! Achever = довести до конца (книжн.) / добить.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_276', '{"signifier","indiquer"}', 'Сигнализировать, сообщить о чём-то.', 'Signaler = обратить внимание / сообщить: signaler un problème. Signifier = означать: Que signifie ce mot? Indiquer = указать.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_278', '{"signaler","vouloir dire"}', 'Означать, значить.', 'Signifier = означать (формально): Que signifie ce mot? Vouloir dire = значить (разг.): Qu''est-ce que ça veut dire? Signaler = сообщить о чём-то.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_071', '{"se révéler","sembler"}', 'Оказаться, выясниться.', 'S''avérer = оказаться (при проверке): Il s''est avéré que... (оказалось, что...). Sembler = казаться (впечатление). Se révéler = обнаружиться.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_295', '{"duper","mentir"}', 'Обманывать. Se tromper = ошибаться!', 'Tromper = обмануть: Il m''a trompé. Se tromper = ОШИБИТЬСЯ: Je me suis trompé de porte (я ошибся дверью). Mentir = лгать (словами).');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_225', '{"remarquer","enregistrer"}', 'Отмечать, записывать. Также: ставить оценку.', 'Noter = записать: noter une adresse. Также = заметить (формально): Il faut noter que... Remarquer = заметить (обратить внимание): J''ai remarqué son absence.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_253', '{"noter","observer"}', 'Замечать, обращать внимание.', 'Remarquer = заметить (визуально/ментально): As-tu remarqué? Noter = записать / отметить (формально). Observer = наблюдать (длительно).');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_230', '{"traverser","dépasser"}', 'Очень многозначный! Проходить, проводить (время), передавать, сдавать (экзамен).', 'Passer = 1) проходить мимо: passer devant; 2) проводить время: passer la journée; 3) передать: passe-moi le sel; 4) сдавать: passer un examen (НЕ «сдать успешно» = réussir!). Se passer = происходить.');
INSERT INTO vocab_lexicon (vocab_id, synonyms, usage, semantics) VALUES ('fr_289', '{}', 'Падать. Также в устойчивых выражениях.', 'Tomber = падать. Идиомы: tomber amoureux (влюбиться), tomber malade (заболеть), tomber bien/mal (быть к месту / не к месту), laisser tomber (бросить, забить).');
