INSERT INTO theme (id, lang, pack_id, "order", title, title_ru, description, description_ru, unlock_theme_id, unlock_min_score) VALUES ('fr_theme30', 'fr', 'fr-foundations', 30, 'Comparatives & Superlatives', 'Степени сравнения', 'Plus...que, moins...que, le plus...', 'Больше чем, меньше чем, самый...', 'fr_theme29', 60);
