INSERT INTO theme (id, lang, pack_id, "order", title, title_ru, description, description_ru, unlock_theme_id, unlock_min_score) VALUES ('pl_theme02', 'pl', 'pl-telc', 2, 'Ortografia: dwuznaki (cz, dz, dź, dż, ch, rz, sz)', 'Правописание: диграфы (cz, dz, dź, dż, ch, rz, sz)', 'В польском языке 7 диграфов — буквосочетаний, обозначающих один звук', 'В польском языке 7 диграфов — буквосочетаний, обозначающих один звук', NULL, 60);
INSERT INTO theme (id, lang, pack_id, "order", title, title_ru, description, description_ru, unlock_theme_id, unlock_min_score) VALUES ('pl_theme03', 'pl', 'pl-telc', 3, 'Ortografia: miękkie spółgłoski (ć/ci, ń/ni, ś/si, ź/zi)', 'Правописание: мягкость согласных (kreska vs i)', 'Два способа обозначить мягкость: надстрочная чёрточка и буква i', 'Два способа обозначить мягкость: надстрочная чёрточка (kreska) и буква i', NULL, 60);
INSERT INTO theme (id, lang, pack_id, "order", title, title_ru, description, description_ru, unlock_theme_id, unlock_min_score) VALUES ('pl_theme04', 'pl', 'pl-telc', 4, 'Ortografia: ż i rz', 'Правописание: ż и rz', 'Буква ż и диграф rz обозначают один звук [ж] — когда писать что', 'Буква ż и диграф rz обозначают один звук [ж] — когда писать что', NULL, 60);
INSERT INTO theme (id, lang, pack_id, "order", title, title_ru, description, description_ru, unlock_theme_id, unlock_min_score) VALUES ('pl_theme05', 'pl', 'pl-telc', 5, 'Ortografia: ch i h', 'Правописание: ch и h', 'Заднеязычный звук [х] — когда пишем ch, а когда h', 'Заднеязычный звук [х] — когда пишем диграф ch, а когда букву h', NULL, 60);
INSERT INTO theme (id, lang, pack_id, "order", title, title_ru, description, description_ru, unlock_theme_id, unlock_min_score) VALUES ('pl_theme06', 'pl', 'pl-telc', 6, 'Ortografia: j i i', 'Правописание: j и i (для звука [й])', 'Звук [й] обозначается буквами j или i — когда какую выбрать', 'Звук [й] в польском может обозначаться буквами j или i — есть чёткие правила', NULL, 60);
