INSERT INTO theme_section (theme_id, type, sort_order, content) VALUES ('pl_theme01', 'grammar', 0, '{"notes":[{"title":"Звук [u] — две буквы","text":"Буквы u и ó обозначают один и тот же звук [u]. Их написание объясняется историческим развитием польского языка: буква u обозначает исконный звук [u], а буква ó — звук, который произошёл из гласного [o] (в других славянских языках, например, в русском, [o] сохранился).","examples":[]},{"title":"Когда пишем Ó — правило (а): чередование [u/ó]","text":"Ó пишется в словах, где возможно чередование [u/ó] в формах одного и того же слова или в однокоренных словах:","examples":[{"pl":"sól — soli","ru":"соль — соли"},{"pl":"stój — stoi","ru":"стой — (он) стоит"},{"pl":"nie bój się — boi się","ru":"не бойся — боится"},{"pl":"ból — boli","ru":"боль — болит"},{"pl":"uspokój się — uspokoi się","ru":"успокойся — успокоится"},{"pl":"nóg — noga","ru":"ног — нога"},{"pl":"Bóg — Boga","ru":"Бог — Бога"},{"pl":"ósmy — osiem","ru":"восьмой — восемь"},{"pl":"zawód — zawody","ru":"профессия — профессии"},{"pl":"wytwór — wytwory","ru":"изделие — изделия"},{"pl":"wzór — wzory","ru":"образец — образцы"},{"pl":"podróż — droga","ru":"путешествие — дорога"}]},{"title":"Когда пишем Ó — правило (б): соответствие в русском","text":"Ó пишется, когда в похожих по звучанию словах русского, белорусского или украинского языков этой букве соответствует и или о, хотя чередования [u/ó] в польском не наблюдается:","examples":[{"pl":"chór","ru":"хор"},{"pl":"miód","ru":"мёд"},{"pl":"góra","ru":"гора"},{"pl":"kłócić","ru":"колотить"},{"pl":"król","ru":"король"},{"pl":"krótki","ru":"короткий"},{"pl":"mózg","ru":"мозг"},{"pl":"płótno","ru":"полотно"},{"pl":"póki","ru":"пока"},{"pl":"prócz","ru":"кроме"},{"pl":"równy","ru":"ровный"},{"pl":"różny","ru":"разный"},{"pl":"stróż","ru":"сторож"},{"pl":"tchórz","ru":"хорёк"},{"pl":"róża","ru":"роза"},{"pl":"włóczyć","ru":"тащить"},{"pl":"włókno","ru":"волокно"},{"pl":"wróbel","ru":"воробей"},{"pl":"póty","ru":"до тех пор"},{"pl":"późno","ru":"поздно"},{"pl":"próba","ru":"проба"},{"pl":"wróżba","ru":"ворожба"},{"pl":"źródło","ru":"средство (источник)"},{"pl":"żółty","ru":"жёлтый"}]},{"title":"Исключение","text":"Слово ogórek (огурец) пишется через o, хотя по смыслу подходило бы ó.","examples":[{"pl":"ogórek","ru":"огурец"}]},{"title":"Когда пишем Ó — правило (в): окончания","text":"Ó пишется в следующих окончаниях:","examples":[{"pl":"-ów (в географических названиях): Tarnów, Kraków, Chorzów, Janów","ru":""},{"pl":"-ów (род. п. мн. ч. существительных): chłopców, domów, bloków, projektów","ru":"мальчиков, домов, блоков, проектов"},{"pl":"-ówna: Rodziewiczówna, Iłłakowiczówna, Bednarzówna","ru":"(фамилии незамужних дочерей)"},{"pl":"-ówka: mieszkaniówka, placówka, żarówka, pocztówka","ru":"жилищный вопрос, пост, лампочка, открытка"}]}],"tables":[],"exercises":[]}'::jsonb);
INSERT INTO theme_section (theme_id, type, sort_order, content) VALUES ('pl_theme01', 'grammar', 1, '{"notes":[{"title":"Когда пишем U — правило (а)","text":"U пишется в большинстве польских слов, которым в других славянских языках также соответствуют слова со звуком [u]:","examples":[{"pl":"artykuł","ru":"статья (не «артыкул»)"},{"pl":"szukać","ru":"искать (не «шукаць»)"},{"pl":"suchy","ru":"сухой"},{"pl":"futro","ru":"мех (не «футра»)"},{"pl":"ucho","ru":"ухо"},{"pl":"ulica","ru":"улица"}]},{"title":"Когда пишем U — правило (б): суффиксы","text":"U пишется в многочисленных суффиксах:","examples":[{"pl":"-un: zwiastun, opiekun","ru":"вестник, опекун"},{"pl":"-ulec: hamulec, budulec","ru":"тормоз, стройматериал"},{"pl":"-uchna: matuchna, córuchna","ru":"матушка, доченька"},{"pl":"-utki: malutki, skromniutki","ru":"малюсенький, скромненький"},{"pl":"-unek: wizerunek, stosunek","ru":"облик, отношение"},{"pl":"-uch: leniuch, pastuch","ru":"лентяй, пастух"},{"pl":"-uszek: staruszek, garnuszek","ru":"старичок, горшочек"},{"pl":"-us: dzikus, lizus","ru":"дикарь, подлиза"}]},{"title":"Когда пишем U — правило (в): глаголы на -ować","text":"U пишется в формах глаголов, инфинитив которых оканчивается на -ować:","examples":[{"pl":"studiować — studiuje","ru":"учиться — (он) учится"},{"pl":"rysować — rysuje","ru":"рисовать — (он) рисует"},{"pl":"projektować — projektuje","ru":"проектировать — (он) проектирует"}]},{"title":"Обратите внимание! Исключения — u там, где ожидается о","text":"Есть слова, в которых польское u соответствует русскому о (вместо ожидаемого у по общеславянскому правилу). Запомните их написание:","examples":[{"pl":"długi","ru":"долгий"},{"pl":"zasuwać","ru":"засовывать"},{"pl":"skuwać","ru":"сковывать"},{"pl":"bruzda","ru":"борозда"},{"pl":"dłuto","ru":"долото"},{"pl":"kłuć","ru":"колоть"},{"pl":"płukać","ru":"полоскать"},{"pl":"pruć","ru":"пороть"},{"pl":"but","ru":"ботинок"},{"pl":"rum","ru":"ром"},{"pl":"sum","ru":"сом"},{"pl":"rumianek","ru":"ромашка"}]}],"tables":[],"exercises":[]}'::jsonb);
INSERT INTO theme_section (theme_id, type, sort_order, content) VALUES ('pl_theme01', 'exercises', 2, '{"notes":[],"tables":[],"exercises":[{"type":"write_answer","category":"Перевод","prompt":"стой (команда)","answer":"stój","hint":"Чередование [u/ó]: stój — stoi."},{"type":"write_answer","category":"Перевод","prompt":"не бойся","answer":"nie bój się","hint":"Чередование [u/ó]: nie bój się — boi się."},{"type":"write_answer","category":"Перевод","prompt":"успокойся","answer":"uspokój się","hint":"Чередование [u/ó]: uspokój się — uspokoi się."},{"type":"write_answer","category":"Перевод","prompt":"соль","answer":"sól","hint":"Чередование [u/ó]: sól — soli."},{"type":"write_answer","category":"Перевод","prompt":"Бог","answer":"Bóg","hint":"Чередование [u/ó]: Bóg — Boga."},{"type":"write_answer","category":"Перевод","prompt":"восьмой","answer":"ósmy","hint":"Чередование [u/ó]: ósmy — osiem."},{"type":"write_answer","category":"Перевод","prompt":"боль","answer":"ból","hint":"Чередование [u/ó]: ból — boli."},{"type":"write_answer","category":"Перевод","prompt":"профессия","answer":"zawód","hint":"Чередование [u/ó]: zawód — zawody."},{"type":"write_answer","category":"Перевод","prompt":"образец","answer":"wzór","hint":"Чередование [u/ó]: wzór — wzory."},{"type":"write_answer","category":"Перевод","prompt":"путешествие","answer":"podróż","hint":"Чередование [u/ó]: podróż — droga."},{"type":"write_answer","category":"Перевод","prompt":"гора","answer":"góra","hint":"В русском «гора» → в польском ó."},{"type":"write_answer","category":"Перевод","prompt":"король","answer":"król","hint":"В русском «король» → в польском ó."},{"type":"write_answer","category":"Перевод","prompt":"короткий","answer":"krótki","hint":"В русском «короткий» → в польском ó."},{"type":"write_answer","category":"Перевод","prompt":"мозг","answer":"mózg","hint":"В русском «мозг» → в польском ó."},{"type":"write_answer","category":"Перевод","prompt":"хор","answer":"chór","hint":"В русском «хор» → в польском ó."},{"type":"write_answer","category":"Перевод","prompt":"мёд","answer":"miód","hint":"В русском «мёд» → в польском ó."},{"type":"write_answer","category":"Перевод","prompt":"роза","answer":"róża","hint":"В русском «роза» → в польском ó."},{"type":"write_answer","category":"Перевод","prompt":"воробей","answer":"wróbel","hint":"В русском «воробей» → в польском ó."},{"type":"write_answer","category":"Перевод","prompt":"поздно","answer":"późno","hint":"В русском «поздно» → в польском ó."},{"type":"write_answer","category":"Перевод","prompt":"проба","answer":"próba","hint":"В русском «проба» → в польском ó."},{"type":"write_answer","category":"Перевод","prompt":"до тех пор","answer":"póty","hint":"В русском «до тех пор» → в польском ó."},{"type":"write_answer","category":"Перевод","prompt":"ворожба","answer":"wróżba","hint":"В русском «ворожба» → в польском ó."},{"type":"write_answer","category":"Перевод","prompt":"источник","answer":"źródło","hint":"В русском «средство / источник» → в польском ó."},{"type":"write_answer","category":"Перевод","prompt":"жёлтый","answer":"żółty","hint":"В русском «жёлтый» → в польском ó."},{"type":"write_answer","category":"Перевод","prompt":"сторож","answer":"stróż","hint":"В русском «сторож» → в польском ó."},{"type":"write_answer","category":"Перевод","prompt":"кроме","answer":"prócz","hint":"В русском «кроме» → в польском ó."},{"type":"write_answer","category":"Перевод","prompt":"ровный","answer":"równy","hint":"В русском «ровный» → в польском ó."},{"type":"write_answer","category":"Перевод","prompt":"разный","answer":"różny","hint":"В русском «разный» → в польском ó."},{"type":"write_answer","category":"Перевод","prompt":"колотить","answer":"kłócić","hint":"В русском «колотить» → в польском ó."},{"type":"write_answer","category":"Перевод","prompt":"полотно","answer":"płótno","hint":"В русском «полотно» → в польском ó."},{"type":"write_answer","category":"Перевод","prompt":"пока","answer":"póki","hint":"В русском «пока» → в польском ó."},{"type":"write_answer","category":"Перевод","prompt":"волокно","answer":"włókno","hint":"В русском «волокно» → в польском ó."},{"type":"write_answer","category":"Перевод","prompt":"хорёк","answer":"tchórz","hint":"В русском «хорёк» → в польском ó."},{"type":"write_answer","category":"Перевод","prompt":"тащить","answer":"włóczyć","hint":"В русском «тащить» → в польском ó."},{"type":"write_answer","category":"Перевод","prompt":"огурец","answer":"ogórek","hint":"Исключение! Пишется через o + ó: ogórek."},{"type":"write_answer","category":"Перевод","prompt":"Краков","answer":"Kraków","hint":"Географическое название на -ów."},{"type":"write_answer","category":"Перевод","prompt":"Тарнув","answer":"Tarnów","hint":"Географическое название на -ów."},{"type":"write_answer","category":"Перевод","prompt":"Хожув","answer":"Chorzów","hint":"Географическое название на -ów."},{"type":"write_answer","category":"Перевод","prompt":"Янув","answer":"Janów","hint":"Географическое название на -ów."},{"type":"write_answer","category":"Род. п. мн. ч.","prompt":"мальчиков (род. п. мн. ч.)","answer":"chłopców","hint":"Окончание -ów род. п. мн. ч."},{"type":"write_answer","category":"Род. п. мн. ч.","prompt":"домов (род. п. мн. ч.)","answer":"domów","hint":"Окончание -ów род. п. мн. ч."},{"type":"write_answer","category":"Род. п. мн. ч.","prompt":"блоков (род. п. мн. ч.)","answer":"bloków","hint":"Окончание -ów род. п. мн. ч."},{"type":"write_answer","category":"Род. п. мн. ч.","prompt":"проектов (род. п. мн. ч.)","answer":"projektów","hint":"Окончание -ów род. п. мн. ч."},{"type":"write_answer","category":"Фамилия (-ówna)","prompt":"фамилия Родзевич (незамужная дочь)","answer":"Rodziewiczówna","hint":"Фамилия незамужной дочери на -ówna."},{"type":"write_answer","category":"Фамилия (-ówna)","prompt":"фамилия Иллакович (незамужная дочь)","answer":"Iłłakowiczówna","hint":"Фамилия незамужной дочери на -ówna."},{"type":"write_answer","category":"Фамилия (-ówna)","prompt":"фамилия Беднаж (незамужная дочь)","answer":"Bednarzówna","hint":"Фамилия незамужной дочери на -ówna."},{"type":"write_answer","category":"Перевод","prompt":"жилищный вопрос","answer":"mieszkaniówka","hint":"Суффикс -ówka."},{"type":"write_answer","category":"Перевод","prompt":"пункт (учреждение)","answer":"placówka","hint":"Суффикс -ówka."},{"type":"write_answer","category":"Перевод","prompt":"лампочка","answer":"żarówka","hint":"Суффикс -ówka."},{"type":"write_answer","category":"Перевод","prompt":"открытка","answer":"pocztówka","hint":"Суффикс -ówka."},{"type":"write_answer","category":"Перевод","prompt":"ухо","answer":"ucho","hint":"Исконный звук [u] → буква u."},{"type":"write_answer","category":"Перевод","prompt":"улица","answer":"ulica","hint":"Исконный звук [u] → буква u."},{"type":"write_answer","category":"Перевод","prompt":"сухой","answer":"suchy","hint":"Исконный звук [u] → буква u."},{"type":"write_answer","category":"Перевод","prompt":"искать","answer":"szukać","hint":"Исконный звук [u] → буква u."},{"type":"write_answer","category":"Перевод","prompt":"статья","answer":"artykuł","hint":"Исконный звук [u] → буква u."},{"type":"write_answer","category":"Перевод","prompt":"мех","answer":"futro","hint":"Исконный звук [u] → буква u."},{"type":"write_answer","category":"Перевод","prompt":"опекун","answer":"opiekun","hint":"Суффикс -un."},{"type":"write_answer","category":"Перевод","prompt":"вестник","answer":"zwiastun","hint":"Суффикс -un."},{"type":"write_answer","category":"Перевод","prompt":"тормоз","answer":"hamulec","hint":"Суффикс -ulec."},{"type":"write_answer","category":"Перевод","prompt":"стройматериал","answer":"budulec","hint":"Суффикс -ulec."},{"type":"write_answer","category":"Перевод","prompt":"матушка","answer":"matuchna","hint":"Суффикс -uchna."},{"type":"write_answer","category":"Перевод","prompt":"доченька","answer":"córuchna","hint":"Суффикс -uchna."},{"type":"write_answer","category":"Перевод","prompt":"пастух","answer":"pastuch","hint":"Суффикс -uch."},{"type":"write_answer","category":"Перевод","prompt":"лентяй","answer":"leniuch","hint":"Суффикс -uch."},{"type":"write_answer","category":"Перевод","prompt":"отношение","answer":"stosunek","hint":"Суффикс -unek."},{"type":"write_answer","category":"Перевод","prompt":"облик","answer":"wizerunek","hint":"Суффикс -unek."},{"type":"write_answer","category":"Перевод","prompt":"старичок","answer":"staruszek","hint":"Суффикс -uszek."},{"type":"write_answer","category":"Перевод","prompt":"горшочек","answer":"garnuszek","hint":"Суффикс -uszek."},{"type":"write_answer","category":"Перевод","prompt":"малюсенький","answer":"malutki","hint":"Суффикс -utki."},{"type":"write_answer","category":"Перевод","prompt":"скромненький","answer":"skromniutki","hint":"Суффикс -utki."},{"type":"write_answer","category":"Перевод","prompt":"дикарь","answer":"dzikus","hint":"Суффикс -us."},{"type":"write_answer","category":"Перевод","prompt":"подлиза","answer":"lizus","hint":"Суффикс -us."},{"type":"write_answer","category":"Перевод","prompt":"долгий","answer":"długi","hint":"Исключение: u, хотя в рус. «долгий» нет у."},{"type":"write_answer","category":"Перевод","prompt":"засовывать","answer":"zasuwać","hint":"Исключение: u, хотя в рус. «засовывать» — о."},{"type":"write_answer","category":"Перевод","prompt":"сковывать","answer":"skuwać","hint":"Исключение: u, хотя в рус. «сковывать» — о."},{"type":"write_answer","category":"Перевод","prompt":"борозда","answer":"bruzda","hint":"Исключение: u, хотя в рус. «борозда» — о."},{"type":"write_answer","category":"Перевод","prompt":"долото","answer":"dłuto","hint":"Исключение: u, хотя в рус. «долото» — о."},{"type":"write_answer","category":"Перевод","prompt":"колоть","answer":"kłuć","hint":"Исключение: u, хотя в рус. «колоть» — о."},{"type":"write_answer","category":"Перевод","prompt":"полоскать","answer":"płukać","hint":"Исключение: u, хотя в рус. «полоскать» — о."},{"type":"write_answer","category":"Перевод","prompt":"пороть","answer":"pruć","hint":"Исключение: u, хотя в рус. «пороть» — о."},{"type":"write_answer","category":"Перевод","prompt":"ботинок","answer":"but","hint":"Исключение: u, хотя в рус. «ботинок» — о."},{"type":"write_answer","category":"Перевод","prompt":"ром","answer":"rum","hint":"Исключение: u, хотя в рус. «ром» — о."},{"type":"write_answer","category":"Перевод","prompt":"сом","answer":"sum","hint":"Исключение: u, хотя в рус. «сом» — о."},{"type":"write_answer","category":"Перевод","prompt":"ромашка","answer":"rumianek","hint":"Исключение: u, хотя в рус. «ромашка» — о."},{"type":"write_answer","category":"Перевод","prompt":"он рисует","answer":"rysuje","hint":"Инфинитив на -ować → форма на -uje."},{"type":"write_answer","category":"Перевод","prompt":"он проектирует","answer":"projektuje","hint":"Инфинитив на -ować → форма на -uje."},{"type":"write_answer","category":"Перевод","prompt":"он учится (в вузе)","answer":"studiuje","hint":"Инфинитив studiować → форма на -uje."}]}'::jsonb);
INSERT INTO theme_section (theme_id, type, sort_order, content) VALUES ('pl_theme02', 'grammar', 0, '{"notes":[{"title":"Семь диграфов польского языка","text":"В польской графике семь буквосочетаний, обозначающих один звук:","examples":[{"rule":"cz = [ч]","words":[{"pl":"czysty","ru":"чистый"},{"pl":"człowiek","ru":"человек"},{"pl":"lecz","ru":"но"}]},{"rule":"dz = [дз]","words":[{"pl":"władza","ru":"власть"},{"pl":"widzę","ru":"вижу"},{"pl":"sadza","ru":"сажа"}]},{"rule":"dź = [дз'']","words":[{"pl":"niedźwiedź","ru":"медведь"},{"pl":"dźwięk","ru":"звук"},{"pl":"chodźmy","ru":"давай пойдём"}]},{"rule":"dż = [дж]","words":[{"pl":"jeżdżę","ru":"езжу"},{"pl":"dżdżysty","ru":"дождливый"},{"pl":"dżuma","ru":"чума"}]},{"rule":"ch = [х]","words":[{"pl":"chory","ru":"больной"},{"pl":"pech","ru":"неудача"},{"pl":"chłopski","ru":"крестьянский"}]},{"rule":"rz = [ж] / [ш]","words":[{"pl":"morze","ru":"море"},{"pl":"krzesło","ru":"стул"},{"pl":"drzewo","ru":"дерево"}]},{"rule":"sz = [ш]","words":[{"pl":"szósty","ru":"шестой"},{"pl":"Warszawa","ru":"Варшава"},{"pl":"czaszka","ru":"череп"}]}]},{"title":"Обратите внимание: dz, dż как два звука","text":"В некоторых случаях буквосочетания dz, dż обозначают не один, а два звука (на стыке приставки и корня):","examples":[{"pl":"odznaka","ru":"награда, отличие [od-znaka]"},{"pl":"odzwierciedlić","ru":"отразить [od-zwierciedlić]"},{"pl":"podżegać","ru":"подталкивать [pod-żegać]"},{"pl":"nadzwyczajny","ru":"чрезвычайный [nad-zwyczajny]"},{"pl":"odzyskać","ru":"отыскать [od-zyskać]"},{"pl":"podżartować","ru":"пошутить [pod-żartować]"}]},{"title":"Диграф rz чаще всего читается как [ж]","text":"Диграф rz чаще всего обозначает согласный звук [ж], например:","examples":[{"pl":"rzadko","ru":"редко"},{"pl":"rzecz","ru":"вещь, дело"},{"pl":"porządek","ru":"порядок"},{"pl":"marzec","ru":"март"},{"pl":"rzucać","ru":"бросать"}]},{"title":"Диграф rz после глухих согласных","text":"После глухих согласных rz всегда произносится как глухой звук [ш]:","examples":[{"pl":"powietrze","ru":"воздух [poveczse]"},{"pl":"przestrzeń","ru":"пространство [пшестшень]"},{"pl":"trzeba","ru":"надо [тшеба]"},{"pl":"krzyk","ru":"крик [кшык]"},{"pl":"chrzan","ru":"хрен [хшан]"}]},{"title":"Исключения: rz после глухих как [рз]","text":"Но в некоторых случаях rz после глухих согласных надо произносить иначе — как [рз] (два звука):","examples":[{"pl":"marznąć","ru":"мёрзнуть"},{"pl":"zmarzły","ru":"замёрзший"},{"pl":"erzac","ru":"эрзац"},{"pl":"zmierznąć","ru":"опротиветь"},{"pl":"zmierzły","ru":"противный"}]}],"tables":[],"exercises":[]}'::jsonb);
INSERT INTO theme_section (theme_id, type, sort_order, content) VALUES ('pl_theme02', 'exercises', 1, '{"notes":[],"tables":[],"exercises":[{"type":"write_answer","category":"Перевод","prompt":"чистый","answer":"czysty","hint":"Диграф cz = [ч]."},{"type":"write_answer","category":"Перевод","prompt":"человек","answer":"człowiek","hint":"Диграф cz."},{"type":"write_answer","category":"Перевод","prompt":"но / однако","answer":"lecz","hint":"cz в конце слова."},{"type":"write_answer","category":"Перевод","prompt":"власть","answer":"władza","hint":"Диграф dz = [дз]."},{"type":"write_answer","category":"Перевод","prompt":"вижу","answer":"widzę","hint":"Диграф dz."},{"type":"write_answer","category":"Перевод","prompt":"сажа","answer":"sadza","hint":"Диграф dz."},{"type":"write_answer","category":"Перевод","prompt":"медведь","answer":"niedźwiedź","hint":"Диграф dź (мягкий)."},{"type":"write_answer","category":"Перевод","prompt":"звук","answer":"dźwięk","hint":"Диграф dź в начале слова."},{"type":"write_answer","category":"Перевод","prompt":"давай пойдём","answer":"chodźmy","hint":"Диграф dź."},{"type":"write_answer","category":"Перевод","prompt":"езжу","answer":"jeżdżę","hint":"Диграф dż."},{"type":"write_answer","category":"Перевод","prompt":"чума","answer":"dżuma","hint":"Диграф dż в начале слова."},{"type":"write_answer","category":"Перевод","prompt":"больной","answer":"chory","hint":"Диграф ch = [х]."},{"type":"write_answer","category":"Перевод","prompt":"неудача","answer":"pech","hint":"Диграф ch в конце слова."},{"type":"write_answer","category":"Перевод","prompt":"крестьянский","answer":"chłopski","hint":"Диграф ch."},{"type":"write_answer","category":"Перевод","prompt":"море","answer":"morze","hint":"Диграф rz = [ж]."},{"type":"write_answer","category":"Перевод","prompt":"стул","answer":"krzesło","hint":"Диграф rz после k читается как [ш]."},{"type":"write_answer","category":"Перевод","prompt":"дерево","answer":"drzewo","hint":"Диграф rz после d."},{"type":"write_answer","category":"Перевод","prompt":"шестой","answer":"szósty","hint":"Диграф sz = [ш]."},{"type":"write_answer","category":"Перевод","prompt":"Варшава","answer":"Warszawa","hint":"Диграф sz."},{"type":"write_answer","category":"Перевод","prompt":"череп","answer":"czaszka","hint":"Диграф sz."},{"type":"write_answer","category":"Перевод","prompt":"надо / нужно","answer":"trzeba","hint":"После глухой t диграф rz звучит как [ш]."},{"type":"write_answer","category":"Перевод","prompt":"крик","answer":"krzyk","hint":"После k диграф rz читается как [ш]."},{"type":"write_answer","category":"dz/dż = два звука","prompt":"награда, отличие","answer":"odznaka","hint":"Приставка od- + znaka: dz здесь два звука [d-z]."},{"type":"write_answer","category":"dz/dż = два звука","prompt":"отразить","answer":"odzwierciedlić","hint":"Приставка od- + корень zwierciedl-: dz читается как [d-z]."},{"type":"write_answer","category":"dz/dż = два звука","prompt":"подталкивать","answer":"podżegać","hint":"Приставка pod- + żegać: dż читается как [d-ż]."},{"type":"write_answer","category":"rz = [ж]","prompt":"редко","answer":"rzadko","hint":"Диграф rz чаще всего читается как [ж]."},{"type":"write_answer","category":"rz = [ж]","prompt":"вещь, дело","answer":"rzecz","hint":"rz в начале слова = [ж]."},{"type":"write_answer","category":"rz = [ж]","prompt":"порядок","answer":"porządek","hint":"rz внутри слова звучит как [ж]."},{"type":"write_answer","category":"rz = [ж]","prompt":"март","answer":"marzec","hint":"Название месяца; rz = [ж]."},{"type":"write_answer","category":"rz = [ж]","prompt":"бросать","answer":"rzucać","hint":"Глагол с rz в начале = [ж]."},{"type":"write_answer","category":"rz после глухих = [ш]","prompt":"воздух","answer":"powietrze","hint":"После глухой t диграф rz читается как [ш]."},{"type":"write_answer","category":"Исключения: rz = [рз]","prompt":"мёрзнуть","answer":"marznąć","hint":"Исключение: rz после глухой здесь произносится как два звука [рз]."},{"type":"write_answer","category":"Исключения: rz = [рз]","prompt":"замёрзший","answer":"zmarzły","hint":"Исключение: rz = [рз]."},{"type":"write_answer","category":"Исключения: rz = [рз]","prompt":"эрзац","answer":"erzac","hint":"Заимствование; rz = [рз], два звука."},{"type":"write_answer","category":"Исключения: rz = [рз]","prompt":"опротиветь","answer":"zmierznąć","hint":"Исключение: rz после глухой = [рз]."},{"type":"write_answer","category":"Исключения: rz = [рз]","prompt":"противный","answer":"zmierzły","hint":"Исключение: rz = [рз]."}]}'::jsonb);
INSERT INTO theme_section (theme_id, type, sort_order, content) VALUES ('pl_theme03', 'grammar', 0, '{"notes":[{"title":"Когда пишем ć, ń, ś, ź, dź (с чёрточкой)?","text":"Надстрочный знак kreska ставится над согласной в двух позициях: в конце слова и перед другой согласной.","examples":[{"pl":"ćwiczyć","ru":"упражняться"},{"pl":"dziś","ru":"сегодня"},{"pl":"pończocha","ru":"чулок"},{"pl":"iść","ru":"идти"},{"pl":"część","ru":"часть"},{"pl":"ćmić","ru":"темнить"},{"pl":"dźgać","ru":"пороть"},{"pl":"tańczyć","ru":"танцевать"},{"pl":"babuleńka","ru":"старушка"},{"pl":"tańszy","ru":"более дешёвый"},{"pl":"groźba","ru":"угроза"},{"pl":"rzeźba","ru":"скульптура"}]},{"title":"Когда пишем i (между согласной и гласной)?","text":"Перед гласными a, ą, e, ę, o, ó, u мягкость обозначается с помощью буквы i, которая пишется между согласной и гласной:","examples":[{"pl":"bielizna","ru":"бельё (b + i + e)"},{"pl":"lakier","ru":"лак (k + i + e)"},{"pl":"mięso","ru":"мясо (m + i + ę)"},{"pl":"ziemia","ru":"земля (z + i + e, m + i + a)"},{"pl":"wiosna","ru":"весна (w + i + o)"},{"pl":"ciągle","ru":"постоянно (c + i + ą)"},{"pl":"biuro","ru":"бюро (b + i + u)"},{"pl":"dziecko","ru":"ребёнок (dz + i + e)"},{"pl":"pięć","ru":"пять (p + i + ę)"},{"pl":"wiele","ru":"много (w + i + e)"},{"pl":"nauczyciel","ru":"учитель (c + i + e)"},{"pl":"inżynier","ru":"инженер (n + i + e)"}]}],"tables":[],"exercises":[]}'::jsonb);
INSERT INTO theme_section (theme_id, type, sort_order, content) VALUES ('pl_theme03', 'exercises', 1, '{"notes":[],"tables":[],"exercises":[{"type":"write_answer","category":"Перевод","prompt":"упражняться","answer":"ćwiczyć","hint":"ć перед согласной."},{"type":"write_answer","category":"Перевод","prompt":"сегодня","answer":"dziś","hint":"ś в конце слова."},{"type":"write_answer","category":"Перевод","prompt":"идти","answer":"iść","hint":"ć в конце слова."},{"type":"write_answer","category":"Перевод","prompt":"часть","answer":"część","hint":"ś перед согласной ć."},{"type":"write_answer","category":"Перевод","prompt":"тыкать / пороть","answer":"dźgać","hint":"dź в начале перед согласной."},{"type":"write_answer","category":"Перевод","prompt":"угроза","answer":"groźba","hint":"ź перед согласной b."},{"type":"write_answer","category":"Перевод","prompt":"скульптура","answer":"rzeźba","hint":"ź перед согласной."},{"type":"write_answer","category":"Перевод","prompt":"старушка / бабушка","answer":"babuleńka","hint":"ń перед согласной."},{"type":"write_answer","category":"Перевод","prompt":"чулок","answer":"pończocha","hint":"Носится на ноге."},{"type":"write_answer","category":"Перевод","prompt":"бельё","answer":"bielizna","hint":"Перед гласной e пишем i (мягкость b)."},{"type":"write_answer","category":"Перевод","prompt":"лак","answer":"lakier","hint":"Перед e пишем i (мягкость k)."},{"type":"write_answer","category":"Перевод","prompt":"мясо","answer":"mięso","hint":"Перед ę пишем i (мягкость m)."},{"type":"write_answer","category":"Перевод","prompt":"земля","answer":"ziemia","hint":"Перед e пишем i (мягкость z)."},{"type":"write_answer","category":"Перевод","prompt":"весна","answer":"wiosna","hint":"Перед o пишем i (мягкость w)."},{"type":"write_answer","category":"Перевод","prompt":"постоянно","answer":"ciągle","hint":"Перед ą пишем i (мягкость c)."},{"type":"write_answer","category":"Перевод","prompt":"бюро","answer":"biuro","hint":"Перед u пишем i (мягкость b)."},{"type":"write_answer","category":"Перевод","prompt":"ребёнок","answer":"dziecko","hint":"Перед e пишем i (мягкость dz → dź)."},{"type":"write_answer","category":"Перевод","prompt":"пять","answer":"pięć","hint":"Перед ę пишем i (мягкость p)."},{"type":"write_answer","category":"Перевод","prompt":"много","answer":"wiele","hint":"Перед e пишем i (мягкость w)."},{"type":"write_answer","category":"Перевод","prompt":"учитель","answer":"nauczyciel","hint":"Перед e пишем i (мягкость c → ć)."},{"type":"write_answer","category":"Перевод","prompt":"инженер","answer":"inżynier","hint":"Перед e пишем i (мягкость n → ń)."},{"type":"write_answer","category":"Перевод","prompt":"более дешёвый / дешевле","answer":"tańszy","hint":"ń перед согласной sz."}]}'::jsonb);
INSERT INTO theme_section (theme_id, type, sort_order, content) VALUES ('pl_theme04', 'grammar', 0, '{"notes":[{"title":"Когда пишем ż?","text":"Буква ż обозначает [ж] общеславянского происхождения (в русском соответствует ж: żona — жена, ważny — важный). Правила:","examples":[{"rule":"а) чередование ż // g, dz, z, s, ź, h","words":[{"pl":"drużyna — druh","ru":"дружина — друг"},{"pl":"mrożenie — mróz","ru":"заморозка — мороз"},{"pl":"trwożnie — trwoga","ru":"тревожно — беда"},{"pl":"pieniążek — pieniądz","ru":"денежка — деньги"},{"pl":"grożę — groza","ru":"угрожаю — угроза"},{"pl":"obrażać — obraźliwy","ru":"обижать — обидчивый"},{"pl":"podwyższenie — wysoko","ru":"повышение — высоко"},{"pl":"przerażenie — przerazić","ru":"ужас — ужаснуть"},{"pl":"narożnik — na rogu","ru":"угол — на углу"},{"pl":"zwężać — wąsko","ru":"сужать — узко"}]},{"rule":"б) окончания -aż, -eż","words":[{"pl":"sprzedaż","ru":"продажа"},{"pl":"bandaż","ru":"бандаж"},{"pl":"witraż","ru":"витраж"},{"pl":"młodzież","ru":"молодёжь"},{"pl":"odzież","ru":"одежда"},{"pl":"grabież","ru":"грабёж"}]},{"rule":"в) частицы -że, -ż","words":[{"pl":"tenże","ru":"этот же"},{"pl":"bądźże","ru":"будь же"},{"pl":"stańże","ru":"стань же"},{"pl":"cóż","ru":"что же"},{"pl":"czyż","ru":"неужели / разве"},{"pl":"gdyż","ru":"если же / поскольку"}]},{"rule":"г) после n в заимствованиях","words":[{"pl":"aranżować","ru":"организовывать / аранжировать"},{"pl":"branża","ru":"отрасль (промышленности или торговли)"},{"pl":"oranżada","ru":"апельсиновый охлаждающий напиток"},{"pl":"rewanż","ru":"реванш"}]}]},{"title":"Когда пишем rz?","text":"Диграф rz — тот же звук, но другое историческое происхождение. Правила:","examples":[{"rule":"а) чередование ż // r","words":[{"pl":"reformatorzy — reformator","ru":"реформаторы — реформатор"},{"pl":"radarzysta — radar","ru":"оператор радара — радар"},{"pl":"literatura — w literaturze","ru":"литература — в литературе"},{"pl":"dworzanin — dwór","ru":"придворный — двор"},{"pl":"komputer — w komputerze","ru":"компьютер — на компьютере"},{"pl":"maturzysta — matura","ru":"выпускник — выпускной"},{"pl":"tworzyć — twórca","ru":"творить — творец"},{"pl":"dworzec — na dworcu","ru":"вокзал — на вокзале"},{"pl":"powtórzyć — powtórka","ru":"повторить — повтор"},{"pl":"lekarz — lekarstwo","ru":"врач — лекарство"},{"pl":"wzorzec — wzorca","ru":"образец — образца"},{"pl":"ślusarz — ślusarski","ru":"слесарь — слесарный"},{"pl":"charakter — o charakterze","ru":"характер — о характере"},{"pl":"harcerz — harcerstwo","ru":"скаут — скаутизм"}]},{"rule":"б) русскому р соответствует rz","words":[{"pl":"rzeka","ru":"река"},{"pl":"rzadko","ru":"редко"},{"pl":"orzech","ru":"орех"},{"pl":"korzeń","ru":"корень"},{"pl":"porządek","ru":"порядок"},{"pl":"rząd","ru":"ряд"},{"pl":"rzemień","ru":"ремень"},{"pl":"rzemiosło","ru":"ремесло"},{"pl":"Rzym","ru":"Рим"},{"pl":"wierzba","ru":"верба"},{"pl":"wierzch","ru":"верх"}]},{"rule":"в) после v, b, p, d, t, g, k, x","words":[{"pl":"wyprzedaż","ru":"распродажа"},{"pl":"potrzeba","ru":"потребность"},{"pl":"wytrzymać","ru":"выдержать"},{"pl":"skrzydło","ru":"крыло"},{"pl":"chrześcijański","ru":"христианский"},{"pl":"brzmienie","ru":"звучание"},{"pl":"wrzątek","ru":"кипяток"},{"pl":"wydrzeć","ru":"вырвать"},{"pl":"przekonanie","ru":"убеждение"},{"pl":"ugrzęznąć","ru":"погрязнуть"}]}]},{"title":"Исключения (пишем ż, не rz)","text":"Запомните эти слова:","examples":[{"rule":"Базовые слова с sz","words":[{"pl":"pszenica","ru":"пшеница"},{"pl":"pszczoła","ru":"пчела"},{"pl":"kształt","ru":"форма"},{"pl":"bukszpan","ru":"самшит"}]},{"rule":"Наречия","words":[{"pl":"wszystko","ru":"всё"},{"pl":"wszędzie","ru":"везде"},{"pl":"zawsze","ru":"всегда"}]},{"rule":"Формы сравнительной степени","words":[{"pl":"głupszy","ru":"более глупый"},{"pl":"krótszy","ru":"более короткий / короче"},{"pl":"rzadszy","ru":"более редкий / реже"}]},{"rule":"С приставками ob-, od-, pod- + ż","words":[{"pl":"obżerać się","ru":"объедаться"},{"pl":"odżałować","ru":"оплакать / не поскупиться"},{"pl":"odżyć","ru":"ожить"},{"pl":"nadżółkły","ru":"пожелтевший"}]},{"rule":"Окончание -że (не -rze)","words":[{"pl":"dajże","ru":"дай же"},{"pl":"zróbże","ru":"сделай же"},{"pl":"także","ru":"также"},{"pl":"skądże","ru":"откуда же"}]},{"rule":"Окончания -mierz, -mistrz","words":[{"pl":"Kazimierz","ru":"Казимир"},{"pl":"Włodzimierz","ru":"Влодзимеж"},{"pl":"sztukmistrz","ru":"мастер своего дела / иллюзионист"},{"pl":"zegarmistrz","ru":"часовщик"},{"pl":"kuchmistrz","ru":"шеф-повар"}]}]}],"tables":[],"exercises":[]}'::jsonb);
