INSERT INTO theme_section (theme_id, type, sort_order, content) VALUES ('pl_theme05', 'grammar', 0, '{"notes":[{"title":"Когда пишем ch?","text":"Диграф ch пишется:","examples":[{"rule":"а) при чередовании [х // ш]","words":[{"pl":"mucha — muszka","ru":""},{"pl":"suchy — suszyć","ru":""},{"pl":"duch — dusza","ru":""},{"pl":"piechota — pieszo","ru":""}]},{"rule":"б) в конце слова (исключения: Boh, druh)","words":[{"pl":"mech","ru":"мох"},{"pl":"ruch","ru":"движение"},{"pl":"w oczach","ru":""},{"pl":"strach","ru":"страх"},{"pl":"gmach","ru":"здание"}]},{"rule":"в) после буквы s","words":[{"pl":"pascha","ru":"пасха"},{"pl":"schemat","ru":""},{"pl":"scholastyka","ru":""},{"pl":"schudnąć","ru":"похудеть"}]},{"rule":"г) в заимствованиях, если в исходном языке писалось ch","words":[{"pl":"charakter","ru":""},{"pl":"chaotyczny","ru":""},{"pl":"charytatywny","ru":""},{"pl":"chemia","ru":""}]}]},{"title":"Когда пишем h?","text":"Буква h пишется:","examples":[{"rule":"а) при чередованиях [х // г / з / ж / дз]","words":[{"pl":"wahać się — waga, ważyć","ru":""},{"pl":"druh — drużyna","ru":""},{"pl":"błahy — błazen","ru":""},{"pl":"wataha — watadze","ru":""}]},{"rule":"б) существуют варианты без начального h","words":[{"pl":"harfa или arfa","ru":""},{"pl":"Hanusia или Anusia","ru":""},{"pl":"Hanna или Anna","ru":""},{"pl":"Hindus или Indus","ru":""}]},{"rule":"в) в словах с hiper-, hipo-","words":[{"pl":"hiperbola","ru":""},{"pl":"hipochondria","ru":""},{"pl":"hipoteka","ru":""}]},{"rule":"г) русскому [г] (или его отсутствию) соответствует польское [х]","words":[{"pl":"historia","ru":"история"},{"pl":"nahajka","ru":"нагайка"},{"pl":"honor","ru":"гонор"},{"pl":"Bohdan","ru":"Богдан"},{"pl":"hamak","ru":"гамак"},{"pl":"Himalaje","ru":"Гималаи"},{"pl":"higiena","ru":"гигиена"},{"pl":"Mahomet","ru":"Магомет"},{"pl":"hołota","ru":"голота"},{"pl":"Holandia","ru":"Голландия"},{"pl":"hrabia","ru":"граф"},{"pl":"hulać","ru":"гулять"},{"pl":"huragan","ru":"ураган"},{"pl":"gehenna","ru":"геена"},{"pl":"alkohol","ru":"алкоголь"},{"pl":"Hipolit","ru":"Ипполит"}]}]},{"title":"Слова, которые нужно запомнить (пишем h)","text":"Часто употребляемые слова с h:","examples":[{"pl":"hamować","ru":"тормозить"},{"pl":"harmonia","ru":"гармония"},{"pl":"hart","ru":"закалка"},{"pl":"hasło","ru":"лозунг"},{"pl":"hazard","ru":"азарт"},{"pl":"herbata","ru":"чай"},{"pl":"hermetyczny","ru":"герметичный"},{"pl":"hierarchia","ru":"иерархия"},{"pl":"honorarium","ru":"гонорар"},{"pl":"horyzont","ru":"горизонт"},{"pl":"hotel","ru":"гостиница"},{"pl":"humanizm","ru":"гуманизм"},{"pl":"nihilizm","ru":"нигилизм"},{"pl":"rehabilitacja","ru":"реабилитация"},{"pl":"hokej","ru":"хоккей — ИСКЛЮЧЕНИЕ: пишется с h, хотя по правилу должно быть ch"}]}],"tables":[],"exercises":[]}'::jsonb);
INSERT INTO theme_section (theme_id, type, sort_order, content) VALUES ('pl_theme05', 'exercises', 1, '{"notes":[],"tables":[],"exercises":[{"type":"write_answer","category":"Перевод","prompt":"муха","answer":"mucha","hint":"Чередование mucha // muszka (ch // sz), значит ch."},{"type":"write_answer","category":"Перевод","prompt":"сухой","answer":"suchy","hint":"Чередование suchy // suszyć, значит ch."},{"type":"write_answer","category":"Перевод","prompt":"дух","answer":"duch","hint":"ch в конце слова + чередование duch // dusza."},{"type":"write_answer","category":"Перевод","prompt":"страх","answer":"strach","hint":"ch в конце слова."},{"type":"write_answer","category":"Перевод","prompt":"мох","answer":"mech","hint":"ch в конце слова."},{"type":"write_answer","category":"Перевод","prompt":"движение","answer":"ruch","hint":"ch в конце слова."},{"type":"write_answer","category":"Перевод","prompt":"пасха","answer":"pascha","hint":"ch после s."},{"type":"write_answer","category":"Перевод","prompt":"схема","answer":"schemat","hint":"ch после s."},{"type":"write_answer","category":"Перевод","prompt":"похудеть","answer":"schudnąć","hint":"ch после s."},{"type":"write_answer","category":"Перевод","prompt":"характер","answer":"charakter","hint":"Заимствование, в оригинале ch."},{"type":"write_answer","category":"Перевод","prompt":"химия","answer":"chemia","hint":"Заимствование, пишем ch."},{"type":"write_answer","category":"Перевод","prompt":"история","answer":"historia","hint":"Русскому г соответствует польское h."},{"type":"write_answer","category":"Перевод","prompt":"гонор / честь","answer":"honor","hint":"Русскому г соответствует h."},{"type":"write_answer","category":"Перевод","prompt":"гамак","answer":"hamak","hint":"Русскому г соответствует h."},{"type":"write_answer","category":"Перевод","prompt":"гигиена","answer":"higiena","hint":"Русскому г соответствует h."},{"type":"write_answer","category":"Перевод","prompt":"гипербола","answer":"hiperbola","hint":"Приставка hiper-."},{"type":"write_answer","category":"Перевод","prompt":"ипотека","answer":"hipoteka","hint":"Приставка hipo-."},{"type":"write_answer","category":"Перевод","prompt":"чай","answer":"herbata","hint":"Запоминаем: пишется с h."},{"type":"write_answer","category":"Перевод","prompt":"отель / гостиница","answer":"hotel","hint":"Запоминаем: пишется с h."},{"type":"write_answer","category":"Перевод","prompt":"гуманизм","answer":"humanizm","hint":"Запоминаем: пишется с h."},{"type":"write_answer","category":"Перевод","prompt":"колебаться","answer":"wahać się","hint":"Чередование wahać // waga (h // g)."},{"type":"write_answer","category":"Перевод","prompt":"друг / товарищ","answer":"druh","hint":"Чередование druh // drużyna (h // ż). Исключение из правила о ch в конце слова!"},{"type":"write_answer","category":"Перевод","prompt":"нагайка","answer":"nahajka","hint":"Русскому г нет — пишем h (ho-)."},{"type":"write_answer","category":"Перевод","prompt":"голландия","answer":"Holandia","hint":"Русскому г нет — пишем H (Ho-)."},{"type":"write_answer","category":"Перевод","prompt":"голота","answer":"hołota","hint":"Русскому г нет — пишем h (hoł-)."},{"type":"write_answer","category":"Перевод","prompt":"граф","answer":"hrabia","hint":"Русскому г нет — пишем h (hr-)."},{"type":"write_answer","category":"Перевод","prompt":"гулять / прогуливаться","answer":"hulać","hint":"Русскому г соответствует h (hu-)."},{"type":"write_answer","category":"Перевод","prompt":"ураган","answer":"huragan","hint":"Русскому г нет — пишем h (hu-)."},{"type":"write_answer","category":"Перевод","prompt":"геена (библейское)","answer":"gehenna","hint":"Русскому г нет — пишем geh- с h."},{"type":"write_answer","category":"Перевод","prompt":"алкоголь","answer":"alkohol","hint":"Русскому г нет — пишем h в конце (alkoho-l)."},{"type":"write_answer","category":"Перевод","prompt":"ипполит","answer":"Hipolit","hint":"Русскому г соответствует h (Hi-)."},{"type":"write_answer","category":"Перевод","prompt":"гармония","answer":"harmonia","hint":"Запоминаем: пишется с h."},{"type":"write_answer","category":"Перевод","prompt":"закалка / закалять","answer":"hart","hint":"Запоминаем: пишется с h."},{"type":"write_answer","category":"Перевод","prompt":"лозунг / пароль","answer":"hasło","hint":"Запоминаем: пишется с h."},{"type":"write_answer","category":"Перевод","prompt":"азарт","answer":"hazard","hint":"Запоминаем: пишется с h."},{"type":"write_answer","category":"Перевод","prompt":"хоккей","answer":"hokej","hint":"ИСКЛЮЧЕНИЕ! Пишется с h, хотя по правилу ожидалось бы ch."},{"type":"write_answer","category":"Перевод","prompt":"Богдан","answer":"Bohdan","hint":"Русскому г соответствует h."},{"type":"write_answer","category":"Перевод","prompt":"Магомет","answer":"Mahomet","hint":"Русскому г соответствует h."}]}'::jsonb);
INSERT INTO theme_section (theme_id, type, sort_order, content) VALUES ('pl_theme06', 'grammar', 0, '{"notes":[{"title":"Когда пишем j?","text":"Буква j пишется:","examples":[{"rule":"а) в начале слова","words":[{"pl":"jezioro","ru":"озеро"},{"pl":"jesień","ru":"осень"},{"pl":"jutro","ru":"завтра"},{"pl":"język","ru":"язык"},{"pl":"jeść","ru":"есть"}]},{"rule":"б) после гласных","words":[{"pl":"nadzieja","ru":"надежда"},{"pl":"zając","ru":"заяц"},{"pl":"moja","ru":"моя"},{"pl":"pije","ru":"пьёт"}]},{"rule":"в) после согласных c, z, s","words":[{"pl":"stacja","ru":"станция"},{"pl":"operacja","ru":"операция"},{"pl":"Rosja","ru":"Россия"},{"pl":"poezja","ru":"поэзия"},{"pl":"dygresja","ru":"экскурс"}]},{"rule":"г) после приставок nad-, ob-, od-, pod-, przed-, w-, zd-","words":[{"pl":"nadjechać","ru":"подъехать"},{"pl":"objąć","ru":"обнять"},{"pl":"objętość","ru":"объём"},{"pl":"odjechać","ru":"отъехать"},{"pl":"wjazd","ru":"въезд"},{"pl":"zdjąć","ru":"снять"},{"pl":"zdjęcie","ru":"снимок"}]}]},{"title":"Когда пишем i?","text":"Буква i обозначает звук [й] перед гласными после других согласных (кроме c, z, s):","examples":[{"pl":"kopia","ru":"копия"},{"pl":"utopia","ru":"утопия"},{"pl":"premiera","ru":"премьера"},{"pl":"chemia","ru":"химия"},{"pl":"premia","ru":"премия"},{"pl":"fiołek","ru":"фиалка"},{"pl":"fiasko","ru":"фиаско"},{"pl":"miniatura","ru":"миниатюра"},{"pl":"linia","ru":"линия"},{"pl":"mania","ru":"мания"},{"pl":"dialog","ru":"диалог"},{"pl":"dieta","ru":"диета"},{"pl":"radio","ru":"радио"},{"pl":"studiować","ru":"изучать"},{"pl":"sympatia","ru":"симпатия"},{"pl":"bariera","ru":"барьер"},{"pl":"materia","ru":"материя"},{"pl":"liana","ru":"лиана"},{"pl":"felieton","ru":"фельетон"},{"pl":"lilia","ru":"лилия"},{"pl":"ażiotaż","ru":"ажиотаж"},{"pl":"legion","ru":"легион"},{"pl":"kiosk","ru":"киоск"},{"pl":"hiacynt","ru":"гиацинт"},{"pl":"monarchia","ru":"монархия"},{"pl":"teoria","ru":"теория"}]}],"tables":[],"exercises":[]}'::jsonb);
