INSERT INTO theme_section (theme_id, type, sort_order, content) VALUES ('pl_theme07', 'grammar', 0, '{"notes":[{"title":"Когда пишем gie?","text":"Сочетание gie пишем:","examples":[{"rule":"а) в словах польского происхождения","words":[{"pl":"ogień","ru":"огонь"},{"pl":"drugie","ru":"другое"},{"pl":"długie","ru":"долгое"}]},{"rule":"б) в именах литовского происхождения","words":[{"pl":"Jagiełło","ru":""},{"pl":"Giedymin","ru":""},{"pl":"Olgierd","ru":""}]},{"rule":"в) в существительных на -giel, -gier, -gierz","words":[{"pl":"cyngiel","ru":"курок"},{"pl":"żagiel","ru":"парус"},{"pl":"ogier","ru":"жеребец"},{"pl":"szwagier","ru":"шурин"}]},{"rule":"г) в словах, связанных с Алжиром и Англией","words":[{"pl":"Algieria","ru":""},{"pl":"Algierczyk","ru":""},{"pl":"Algierka","ru":""},{"pl":"algierski","ru":""},{"pl":"Angielka","ru":""},{"pl":"angielski","ru":""},{"pl":"angielszczyzna","ru":""},{"pl":"Archangielsk","ru":""},{"pl":"giełda","ru":"биржа"},{"pl":"megiera","ru":""}]}]},{"title":"Когда пишем ge?","text":"Сочетание ge пишется в заимствованных словах:","examples":[{"rule":"с мягким произношением [г''е]","words":[{"pl":"germanista","ru":""},{"pl":"generał","ru":"генерал"},{"pl":"geometria","ru":"геометрия"},{"pl":"algebra","ru":"алгебра"},{"pl":"geografia","ru":"география"},{"pl":"georgina","ru":"георгин"},{"pl":"geranium","ru":"герань"}]},{"rule":"с твёрдым произношением [гэ]","words":[{"pl":"gehenna","ru":"геенна"},{"pl":"getto","ru":"гетто"},{"pl":"gejsza","ru":"гейша"},{"pl":"generacja","ru":"поколение"},{"pl":"gest","ru":"жест"},{"pl":"gestapo","ru":""},{"pl":"gestykulacja","ru":"жестикуляция"},{"pl":"tragedia","ru":"трагедия"},{"pl":"geneza","ru":"генезис"},{"pl":"genealogia","ru":"генеалогия"}]}]}],"tables":[],"exercises":[]}'::jsonb);
INSERT INTO theme_section (theme_id, type, sort_order, content) VALUES ('pl_theme07', 'exercises', 1, '{"notes":[],"tables":[],"exercises":[{"type":"write_answer","category":"Перевод","prompt":"огонь","answer":"ogień","hint":"Польское слово, пишем gie."},{"type":"write_answer","category":"Перевод","prompt":"другое","answer":"drugie","hint":"Польское слово, пишем gie."},{"type":"write_answer","category":"Перевод","prompt":"долгое","answer":"długie","hint":"Польское слово, пишем gie."},{"type":"write_answer","category":"Перевод","prompt":"Ягайло","answer":"Jagiełło","hint":"Имя литовского происхождения, gie."},{"type":"write_answer","category":"Перевод","prompt":"Гедимин","answer":"Giedymin","hint":"Имя литовского происхождения, gie."},{"type":"write_answer","category":"Перевод","prompt":"Ольгерд","answer":"Olgierd","hint":"Имя литовского происхождения, gie."},{"type":"write_answer","category":"Перевод","prompt":"курок","answer":"cyngiel","hint":"Окончание -giel."},{"type":"write_answer","category":"Перевод","prompt":"парус","answer":"żagiel","hint":"Окончание -giel."},{"type":"write_answer","category":"Перевод","prompt":"жеребец","answer":"ogier","hint":"Окончание -gier."},{"type":"write_answer","category":"Перевод","prompt":"шурин / свояк","answer":"szwagier","hint":"Окончание -gier."},{"type":"write_answer","category":"Перевод","prompt":"Алжир","answer":"Algieria","hint":"Пишем gie."},{"type":"write_answer","category":"Перевод","prompt":"английский","answer":"angielski","hint":"Пишем gie."},{"type":"write_answer","category":"Перевод","prompt":"биржа","answer":"giełda","hint":"Пишем gie."},{"type":"write_answer","category":"Перевод","prompt":"мегера","answer":"megiera","hint":"Пишем gie."},{"type":"write_answer","category":"Перевод","prompt":"генерал","answer":"generał","hint":"Заимствование, пишем ge."},{"type":"write_answer","category":"Перевод","prompt":"геометрия","answer":"geometria","hint":"Заимствование, пишем ge."},{"type":"write_answer","category":"Перевод","prompt":"география","answer":"geografia","hint":"Заимствование, пишем ge."},{"type":"write_answer","category":"Перевод","prompt":"алгебра","answer":"algebra","hint":"Заимствование, пишем ge."},{"type":"write_answer","category":"Перевод","prompt":"германист","answer":"germanista","hint":"Заимствование, пишем ge."},{"type":"write_answer","category":"Перевод","prompt":"геенна","answer":"gehenna","hint":"Заимствование, пишем ge (твёрдое [гэ])."},{"type":"write_answer","category":"Перевод","prompt":"гетто","answer":"getto","hint":"Заимствование, пишем ge."},{"type":"write_answer","category":"Перевод","prompt":"гейша","answer":"gejsza","hint":"Заимствование, пишем ge."},{"type":"write_answer","category":"Перевод","prompt":"жест","answer":"gest","hint":"Заимствование, пишем ge."},{"type":"write_answer","category":"Перевод","prompt":"трагедия","answer":"tragedia","hint":"Заимствование, пишем ge."},{"type":"write_answer","category":"Перевод","prompt":"генезис","answer":"geneza","hint":"Заимствование, пишем ge."}]}'::jsonb);
INSERT INTO theme_section (theme_id, type, sort_order, content) VALUES ('pl_theme08', 'grammar', 0, '{"notes":[{"title":"Когда пишем ę, ą?","text":"Буквы ę, ą пишем:","examples":[{"rule":"а) в словах польского происхождения (в русском часто соответствуют [а], [у])","words":[{"pl":"dąb","ru":"дуб"},{"pl":"dębowy","ru":""},{"pl":"krąg","ru":"круг"},{"pl":"kąt","ru":"угол"},{"pl":"piąty","ru":"пятый"},{"pl":"ciągnąć","ru":"тянуть"},{"pl":"wąsy","ru":"усы"},{"pl":"ząb","ru":"зуб"},{"pl":"będzie","ru":"будет"},{"pl":"gęsty","ru":"густой"},{"pl":"ręka","ru":"рука"},{"pl":"pragnąć","ru":"желать"}]},{"rule":"в) в полностью освоенных заимствованиях","words":[{"pl":"brąz","ru":"бронза"},{"pl":"ląd","ru":"суша"},{"pl":"flądra","ru":"камбала"},{"pl":"pąsowy","ru":"пунцовый"},{"pl":"cęgi","ru":"щипцы"},{"pl":"kolęda","ru":"колядка"},{"pl":"pędzel","ru":"кисть"},{"pl":"wędrować","ru":"путешествовать"}]}]},{"title":"ę, ą в окончаниях и суффиксах","text":"Грамматические окончания:","examples":[{"rule":"-ę (вин.пад., ж.р., ед.ч. сущ.)","words":[{"pl":"siostrę"},{"pl":"studentkę"},{"pl":"zimę"}]},{"rule":"-ą (тв.пад., ж.р., ед.ч. сущ.)","words":[{"pl":"siostrą"},{"pl":"studentką"},{"pl":"zimą"}]},{"rule":"-ę (им.пад., ср.р., ед.ч.)","words":[{"pl":"cielę"},{"pl":"imię"},{"pl":"prosię"},{"pl":"plemię"}]},{"rule":"-ą (вин./тв. пад. прил./мест., ж.р., ед.ч.)","words":[{"pl":"moją siostrę"},{"pl":"moją siostrą"}]},{"rule":"-ę (1-е лицо наст./буд.вр. глагола)","words":[{"pl":"idę"},{"pl":"piszę"},{"pl":"wezmę"}]},{"rule":"-ą (3-е лицо наст./буд.вр. глагола)","words":[{"pl":"idą"},{"pl":"piszą"},{"pl":"wezmą"}]},{"rule":"-ąc- (причастие, деепричастие)","words":[{"pl":"pragnący"},{"pl":"piszący"},{"pl":"idąc"}]},{"rule":"-ę (вин.пад. местоимения)","words":[{"pl":"cię"},{"pl":"się"}]}]},{"title":"Когда пишем en, em, on, om?","text":"Сочетания букв en, em, on, om пишутся в НЕ полностью освоенных заимствованиях, которым в русском соответствуют [эм], [ом], [эн], [он], [ан]:","examples":[{"pl":"kompas","ru":"компас"},{"pl":"kompres","ru":"компресс"},{"pl":"kompozycja","ru":"композиция"},{"pl":"kompetencja","ru":"компетенция"},{"pl":"kombinacja","ru":"комбинация"},{"pl":"temperatura","ru":"температура"},{"pl":"stempel","ru":"штемпель"},{"pl":"embargo","ru":"эмбарго"},{"pl":"emblemat","ru":"эмблема"},{"pl":"kontrola","ru":"контроль"},{"pl":"koncert","ru":"концерт"},{"pl":"kalendarz","ru":"календарь"},{"pl":"konkurencja","ru":"конкуренция"},{"pl":"kongres","ru":"конгресс"},{"pl":"konfiskacja","ru":"конфискация"},{"pl":"konstrukcja","ru":"конструкция"}]}],"tables":[],"exercises":[]}'::jsonb);
INSERT INTO theme_section (theme_id, type, sort_order, content) VALUES ('pl_theme08', 'exercises', 1, '{"notes":[],"tables":[],"exercises":[{"type":"write_answer","category":"Перевод","prompt":"дуб","answer":"dąb","hint":"Польское слово, пишем ą."},{"type":"write_answer","category":"Перевод","prompt":"дубовый","answer":"dębowy","hint":"Польское слово, пишем ę."},{"type":"write_answer","category":"Перевод","prompt":"круг","answer":"krąg","hint":"Польское слово, пишем ą."},{"type":"write_answer","category":"Перевод","prompt":"угол","answer":"kąt","hint":"Польское слово, пишем ą."},{"type":"write_answer","category":"Перевод","prompt":"пятый","answer":"piąty","hint":"Польское слово, пишем ą."},{"type":"write_answer","category":"Перевод","prompt":"усы","answer":"wąsy","hint":"Польское слово, пишем ą."},{"type":"write_answer","category":"Перевод","prompt":"зуб","answer":"ząb","hint":"Польское слово, пишем ą."},{"type":"write_answer","category":"Перевод","prompt":"будет","answer":"będzie","hint":"Польское слово, пишем ę."},{"type":"write_answer","category":"Перевод","prompt":"густой","answer":"gęsty","hint":"Польское слово, пишем ę."},{"type":"write_answer","category":"Перевод","prompt":"рука","answer":"ręka","hint":"Польское слово, пишем ę."},{"type":"write_answer","category":"Перевод","prompt":"желать","answer":"pragnąć","hint":"Польское слово, пишем ą."},{"type":"write_answer","category":"Перевод","prompt":"тянуть","answer":"ciągnąć","hint":"Польское слово, пишем ą."},{"type":"write_answer","category":"Перевод","prompt":"бронза","answer":"brąz","hint":"Освоенное заимствование, пишем ą."},{"type":"write_answer","category":"Перевод","prompt":"колядка","answer":"kolęda","hint":"Освоенное заимствование, пишем ę."},{"type":"write_answer","category":"Перевод","prompt":"кисть (для рисования)","answer":"pędzel","hint":"Освоенное заимствование, пишем ę."},{"type":"write_answer","category":"Перевод","prompt":"я иду","answer":"idę","hint":"1-е лицо глагола — ę."},{"type":"write_answer","category":"Перевод","prompt":"я пишу","answer":"piszę","hint":"1-е лицо глагола — ę."},{"type":"write_answer","category":"Перевод","prompt":"они идут","answer":"idą","hint":"3-е лицо множественного числа — ą."},{"type":"write_answer","category":"Перевод","prompt":"сестру (вин.пад.)","answer":"siostrę","hint":"Винительный падеж ед.ч. ж.р. — ę."},{"type":"write_answer","category":"Перевод","prompt":"со студенткой (тв.пад.)","answer":"studentką","hint":"Творительный падеж ед.ч. ж.р. — ą."},{"type":"write_answer","category":"Перевод","prompt":"имя","answer":"imię","hint":"Существительное ср.р. им.пад. — ę."},{"type":"write_answer","category":"Перевод","prompt":"пятерых","answer":"pięciu","hint":"После мягкого p пишем ę."},{"type":"write_answer","category":"Перевод","prompt":"компас","answer":"kompas","hint":"Неосвоенное заимствование, пишем om, НЕ ą!"},{"type":"write_answer","category":"Перевод","prompt":"концерт","answer":"koncert","hint":"Неосвоенное заимствование, пишем en, НЕ ę!"},{"type":"write_answer","category":"Перевод","prompt":"конгресс","answer":"kongres","hint":"Неосвоенное заимствование, пишем on, НЕ ą!"},{"type":"write_answer","category":"Перевод","prompt":"температура","answer":"temperatura","hint":"Неосвоенное заимствование, пишем em."},{"type":"write_answer","category":"Перевод","prompt":"календарь","answer":"kalendarz","hint":"Неосвоенное заимствование, пишем en."},{"type":"write_answer","category":"Перевод","prompt":"контроль","answer":"kontrola","hint":"Неосвоенное заимствование, пишем on."},{"type":"write_answer","category":"Перевод","prompt":"комбинация","answer":"kombinacja","hint":"Неосвоенное заимствование + j после c."}]}'::jsonb);
INSERT INTO theme_section (theme_id, type, sort_order, content) VALUES ('pl_theme09', 'grammar', 0, '{"notes":[{"title":"Главное отличие от русского","text":"Польские и русские правила написания прописной и строчной букв в основном совпадают. ОДНАКО названия национальностей в польском языке ВСЕГДА начинаются с заглавной буквы:","examples":[{"pl":"Amerykanin — Amerykanka","ru":"американец — американка (в русском строчная!)"},{"pl":"Anglik — Angielka","ru":"англичанин — англичанка"},{"pl":"Arab — Arabka","ru":"араб — арабка"},{"pl":"Austriak — Austriaczka","ru":"австриец — австрийка"},{"pl":"Polak — Polka","ru":"поляк — полька"},{"pl":"Rosjanin — Rosjanka","ru":"русский — русская"},{"pl":"Niemiec — Niemka","ru":"немец — немка"},{"pl":"Francuz — Francuzka","ru":"француз — француженка"}]},{"title":"Но: названия языков и прилагательные — со строчной","text":"Язык, к которому относится национальность, и прилагательные от названий стран пишутся со строчной:","examples":[{"pl":"język polski — польский язык","ru":"Polak, но polski"},{"pl":"język angielski — английский язык","ru":"Anglik, но angielski"},{"pl":"kultura rosyjska — русская культура","ru":"Rosjanin, но rosyjski"},{"pl":"Uczę się języka polskiego","ru":"(с маленькой буквы!)"}]},{"title":"Географические названия","text":"Как и в русском, пишутся с заглавной буквы:","examples":[{"pl":"Polska, Warszawa, Kraków","ru":"Польша, Варшава, Краков"},{"pl":"Wisła, Bałtyk","ru":"Висла, Балтика"},{"pl":"nad Wisłą","ru":"над Вислой (сохраняется заглавная)"}]}],"tables":[],"exercises":[]}'::jsonb);
INSERT INTO theme_section (theme_id, type, sort_order, content) VALUES ('pl_theme09', 'exercises', 1, '{"notes":[],"tables":[],"exercises":[{"type":"write_answer","category":"Перевод","prompt":"поляк","answer":"Polak","hint":"Национальность — в польском ВСЕГДА с заглавной!"},{"type":"write_answer","category":"Перевод","prompt":"полька (ж.р., национальность)","answer":"Polka","hint":"Национальность (ж.р.). С заглавной!"},{"type":"write_answer","category":"Перевод","prompt":"англичанин","answer":"Anglik","hint":"Национальность. С заглавной!"},{"type":"write_answer","category":"Перевод","prompt":"англичанка","answer":"Angielka","hint":"Национальность. С заглавной!"},{"type":"write_answer","category":"Перевод","prompt":"араб","answer":"Arab","hint":"Национальность. С заглавной!"},{"type":"write_answer","category":"Перевод","prompt":"австриец","answer":"Austriak","hint":"Национальность. С заглавной!"},{"type":"write_answer","category":"Перевод","prompt":"американец","answer":"Amerykanin","hint":"Национальность. С заглавной!"},{"type":"write_answer","category":"Перевод","prompt":"немец","answer":"Niemiec","hint":"Национальность. С заглавной!"},{"type":"write_answer","category":"Перевод","prompt":"француз","answer":"Francuz","hint":"Национальность. С заглавной!"},{"type":"write_answer","category":"Перевод","prompt":"русский (человек)","answer":"Rosjanin","hint":"Национальность. С заглавной!"},{"type":"write_answer","category":"Перевод","prompt":"Мои соседи — поляки","answer":"Moi sąsiedzi to Polacy","hint":"Поляки — национальность. Всегда с заглавной!"},{"type":"write_answer","category":"Перевод","prompt":"польский язык","answer":"język polski","hint":"Название языка — со строчной!"},{"type":"write_answer","category":"Перевод","prompt":"Я изучаю польский язык","answer":"Uczę się języka polskiego","hint":"Прилагательное polski — со строчной!"},{"type":"write_answer","category":"Перевод","prompt":"английский язык","answer":"język angielski","hint":"Со строчной (прилагательное)."},{"type":"write_answer","category":"Перевод","prompt":"Польша","answer":"Polska","hint":"Страна. С заглавной."},{"type":"write_answer","category":"Перевод","prompt":"Варшава","answer":"Warszawa","hint":"Город. С заглавной."},{"type":"write_answer","category":"Перевод","prompt":"Краков","answer":"Kraków","hint":"Город. С заглавной."},{"type":"write_answer","category":"Перевод","prompt":"Я люблю гулять над Вислой","answer":"Lubię spacerować nad Wisłą","hint":"Висла — название реки. С заглавной, даже в падежной форме!"}]}'::jsonb);
INSERT INTO theme_section (theme_id, type, sort_order, content) VALUES ('pl_theme10', 'grammar', 0, '{"notes":[{"title":"Типы работы","text":"В современном польском языке существует множество способов организации работы:","examples":[{"pl":"praca zdalna","ru":"удалённая работа"},{"pl":"praca w biurze","ru":"работа в офисе"},{"pl":"praca hybrydowa","ru":"гибридная работа"},{"pl":"freelancing","ru":"фриланс"},{"pl":"samozatrudniony","ru":"самозанятый"}]},{"title":"Рабочее время","text":"Основные термины для описания рабочего времени:","examples":[{"pl":"dzień roboczy","ru":"рабочий день"},{"pl":"godziny pracy","ru":"рабочее время"},{"pl":"nadgodziny","ru":"сверхурочные"},{"pl":"weekend","ru":"выходные"},{"pl":"urlop","ru":"отпуск"},{"pl":"zwolnienie lekarskie","ru":"больничный"}]},{"title":"Доход и вознаграждение","text":"Слова для обсуждения зарплаты и бонусов:","examples":[{"pl":"pensja / wynagrodzenie","ru":"зарплата / вознаграждение"},{"pl":"podwyżka","ru":"повышение зарплаты"},{"pl":"premia / bonus","ru":"премия / бонус"}]},{"title":"Люди на работе","text":"Ключевые роли в профессиональной среде:","examples":[{"pl":"pracodawca","ru":"работодатель"},{"pl":"pracownik","ru":"работник"},{"pl":"kolega / zespół","ru":"коллега / команда"},{"pl":"szef / przełożony","ru":"босс / начальник"},{"pl":"kierownictwo","ru":"руководство"}]},{"title":"Поиск работы","text":"Как говорят о поиске работы на польском:","examples":[{"pl":"rozmowa kwalifikacyjna","ru":"собеседование"},{"pl":"CV","ru":"резюме"},{"pl":"poszukiwanie pracy","ru":"поиск работы"},{"pl":"znaleźć pracę / stracić pracę","ru":"найти работу / потерять работу"},{"pl":"zmienić pracę","ru":"сменить работу"}]}],"tables":[],"exercises":[]}'::jsonb);
INSERT INTO theme_section (theme_id, type, sort_order, content) VALUES ('pl_theme11', 'grammar', 0, '{"notes":[{"title":"Уровни образования","text":"Основные термины для обозначения уровней образования в Польше:","examples":[{"pl":"szkoła","ru":"школа"},{"pl":"uczelnia / uniwersytet","ru":"вуз / университет"},{"pl":"wyższe wykształcenie","ru":"высшее образование"},{"pl":"studia","ru":"учёба в вузе"},{"pl":"wydział","ru":"факультет"}]},{"title":"Люди в школе","text":"Ключевые участники учебного процесса:","examples":[{"pl":"nauczyciel — nauczycielka","ru":"учитель — учительница"},{"pl":"uczeń — uczennica","ru":"ученик — ученица"},{"pl":"wykładowca","ru":"преподаватель (вуз)"},{"pl":"absolwent — absolwentka","ru":"выпускник — выпускница"},{"pl":"rówieśnicy","ru":"сверстники"}]},{"title":"В школе: предметы и принадлежности","text":"Что используется на уроках:","examples":[{"pl":"przedmiot / ulubiony przedmiot","ru":"предмет / любимый предмет"},{"pl":"lekcja — zajęcia","ru":"урок — занятия"},{"pl":"praca domowa","ru":"домашнее задание"},{"pl":"podręcznik / zeszyt","ru":"учебник / тетрадь"},{"pl":"klasa / ławka / tablica","ru":"класс / парта / доска"},{"pl":"laptop / komputer / słuchawki","ru":"ноутбук / компьютер / наушники"}]},{"title":"Оценки и экзамены","text":"Система оценивания и контроля:","examples":[{"pl":"ocena","ru":"оценка"},{"pl":"egzamin / egzamin ustny","ru":"экзамен / устный экзамен"},{"pl":"zdać egzamin","ru":"сдать экзамен"},{"pl":"zdający / egzaminator","ru":"сдающий / экзаменатор"}]},{"title":"Способы обучения","text":"Различные форматы и методы обучения:","examples":[{"pl":"nauka zdalna","ru":"дистанционное обучение"},{"pl":"nauka stacjonarna","ru":"очное обучение"},{"pl":"model hybrydowy","ru":"гибридная модель"},{"pl":"zajęcia online","ru":"онлайн-занятия"},{"pl":"uczyć się samodzielnie","ru":"учиться самостоятельно"},{"pl":"uczyć się w grupie","ru":"учиться в группе"}]},{"title":"Методы запоминания","text":"Как эффективно учить слова:","examples":[{"pl":"fiszki","ru":"карточки для запоминания"},{"pl":"powtórki interwałowe","ru":"интервальное повторение"}]}],"tables":[],"exercises":[]}'::jsonb);
INSERT INTO theme_section (theme_id, type, sort_order, content) VALUES ('pl_theme12', 'grammar', 0, '{"notes":[{"title":"Охрана окружающей среды","text":"Ключевые глаголы для описания воздействия на природу:","examples":[{"pl":"chronić / ochronić przyrodę","ru":"охранять / охранить природу"},{"pl":"dbać / zadbać o środowisko","ru":"следить за окружающей средой"},{"pl":"troszczyć się o planetę","ru":"заботиться о планете"},{"pl":"zanieczyszczać wodę","ru":"загрязнять воду"},{"pl":"zatruwać powietrze","ru":"отравлять воздух"},{"pl":"zapobiegać zanieczyszczeniu","ru":"предотвращать загрязнение"}]},{"title":"Парниковый эффект","text":"Как говорят о глобальном потеплении на польском:","examples":[{"pl":"efekt cieplarniany (= szklarniowy)","ru":"парниковый эффект (= тепличный)"},{"pl":"ocieplenie klimatu Ziemi","ru":"потепление климата"},{"pl":"dwutlenek węgla (CO₂)","ru":"диоксид углерода"},{"pl":"temperatura powierzchni Ziemi","ru":"температура поверхности Земли"}]},{"title":"Вымирание видов","text":"Термины, связанные с исчезновением видов:","examples":[{"pl":"wymierać → wymarły gatunek","ru":"вымирать → вымерший вид"},{"pl":"wymierający gatunek (= ginący gatunek)","ru":"вымирающий (= исчезающий) вид"},{"pl":"zagłada gatunku","ru":"гибель вида"}]}],"tables":[],"exercises":[]}'::jsonb);
INSERT INTO theme_section (theme_id, type, sort_order, content) VALUES ('pl_theme13', 'grammar', 0, '{"notes":[{"title":"Пожар (Pożar)","text":"Как описывают огонь и пожар на польском:","examples":[{"pl":"ogień → pożar","ru":"огонь → пожар"},{"pl":"palić się / płonąć","ru":"гореть / пылать"},{"pl":"gasić pożar","ru":"тушить пожар"},{"pl":"ogień trawi budynek","ru":"огонь пожирает здание"},{"pl":"wybuchać","ru":"вспыхнуть / взорваться"}]},{"title":"Наводнение (Powódź)","text":"Термины, связанные с наводнениями:","examples":[{"pl":"powódź → fala powodziowa","ru":"наводнение → паводковая волна"},{"pl":"fala kulminacyjna","ru":"кульминационная волна"},{"pl":"występować z brzegów","ru":"выходить из берегов"},{"pl":"zalewać miasto","ru":"затапливать город"},{"pl":"porywać samochody","ru":"уносить машины"},{"pl":"podmywać brzegi","ru":"подмывать берега"}]},{"title":"Ураган, тайфун, торнадо","text":"Ветер и шторм на польском:","examples":[{"pl":"huragan / tajfun / tornado","ru":"ураган / тайфун / торнадо"},{"pl":"wichura","ru":"шторм, буря"},{"pl":"wiatr porywisty / gwałtowny","ru":"порывистый / резкий ветер"},{"pl":"szaleć → cichnąć","ru":"бушевать → стихать"}]},{"title":"Засуха (Susza)","text":"Как говорят о засухе:","examples":[{"pl":"susza","ru":"засуха"},{"pl":"słońce pali ziemię","ru":"солнце жжёт землю"},{"pl":"ziemia pęka / wysycha","ru":"земля трескается / пересыхает"}]},{"title":"Землетрясение (Trzęsienie ziemi)","text":"Описания последствий землетрясений:","examples":[{"pl":"trzęsienie ziemi","ru":"землетрясение"},{"pl":"ziemia trzęsie się","ru":"земля трясётся"},{"pl":"budynek wali się / zawali się","ru":"здание рушится / обрушится"},{"pl":"ulegać zniszczeniu","ru":"подвергаться разрушению"},{"pl":"runąć → ruiny budynku","ru":"рухнуть → руины здания"}]},{"title":"Катастрофа: помощь и последствия","text":"Слова для обсуждения катастроф и спасения:","examples":[{"pl":"dochodzić do katastrofy","ru":"доходить до катастрофы"},{"pl":"unikać katastrofy","ru":"избегать катастрофы"},{"pl":"katastrofa może mieć miejsce","ru":"катастрофа может произойти"},{"pl":"ewakuować ludzi i zwierzęta","ru":"эвакуировать людей и животных"},{"pl":"ocalać ludzi","ru":"спасать людей"},{"pl":"ofiara → szkoda","ru":"жертва → ущерб"}]}],"tables":[],"exercises":[]}'::jsonb);
INSERT INTO theme_section (theme_id, type, sort_order, content) VALUES ('pl_theme14', 'grammar', 0, '{"notes":[{"title":"Мусор и отходы","text":"Основные термины для описания мусора:","examples":[{"pl":"śmieci / odpady","ru":"мусор / отходы"},{"pl":"odpadki / resztki","ru":"отбросы / остатки"},{"pl":"śmiecić","ru":"мусорить"},{"pl":"śmietnik","ru":"мусорный бак"}]},{"title":"Свалки и утилизация","text":"Как говорят о местах хранения мусора:","examples":[{"pl":"wysypisko śmieci","ru":"свалка мусора"},{"pl":"wysypisko komunalne","ru":"муниципальная свалка"},{"pl":"wysypisko dzikie","ru":"стихийная свалка"},{"pl":"ścieki → oczyszczalnia ścieków","ru":"сточные воды → очистные сооружения"},{"pl":"rozkładać się → rozkład","ru":"разлагаться → разложение"}]},{"title":"Сортировка и переработка","text":"Экологичная утилизация:","examples":[{"pl":"segregować śmieci","ru":"сортировать мусор"},{"pl":"segregacja szkła, plastiku, metalu, papieru","ru":"сортировка стекла, пластика, металла, бумаги"},{"pl":"recykling","ru":"переработка, рециклинг"},{"pl":"makulatura","ru":"макулатура"}]},{"title":"Экономия ресурсов","text":"Как говорят о бережном отношении к ресурсам:","examples":[{"pl":"marnować wodę, czas, pieniądze","ru":"тратить впустую воду, время, деньги"},{"pl":"cenny → bezcenny","ru":"ценный → бесценный"},{"pl":"zużywać wodę, energię","ru":"расходовать воду, энергию"},{"pl":"odzyskiwać metal, papier","ru":"восстанавливать металл, бумагу"},{"pl":"tryb czuwania","ru":"режим ожидания (электроприборов)"}]}],"tables":[],"exercises":[]}'::jsonb);
INSERT INTO theme_section (theme_id, type, sort_order, content) VALUES ('pl_theme15', 'grammar', 0, '{"notes":[{"title":"Ключевые выражения: стиль жизни","text":"Выражения для описания образа жизни цифрового кочевника:","examples":[{"pl":"być cyfrowym nomadą","ru":"быть цифровым номадом (твор. падеж)"},{"pl":"styl pracy i życia","ru":"стиль работы и жизни"},{"pl":"staje się coraz popularniejszy","ru":"становится всё более популярным"},{"pl":"Na czym to polega?","ru":"В чём это заключается?"}]},{"title":"Путешествия и работа","text":"Как говорят о совмещении работы и путешествий:","examples":[{"pl":"łączyć pracę z podróżowaniem","ru":"совмещать работу с путешествиями"},{"pl":"zatrzymać się w ciekawym miejscu","ru":"остановиться в интересном месте"},{"pl":"korzystać z atutów miejsca","ru":"пользоваться преимуществами места"},{"pl":"zostać gdzieś na dłużej","ru":"остаться где-то надолго"}]},{"title":"Отношения и семья","text":"Выражения о социальных связях и семье:","examples":[{"pl":"nawiązywać nowe znajomości","ru":"заводить новые знакомства"},{"pl":"poznawać kulturę kraju","ru":"узнавать культуру страны"},{"pl":"widywać się z rodziną","ru":"видеться с семьёй"},{"pl":"kontakty się rozluźniają","ru":"контакты ослабевают"},{"pl":"założyć rodzinę","ru":"создать семью"}]},{"title":"Мнение и оценка","text":"Как выражать личное мнение:","examples":[{"pl":"Moim zdaniem to wspaniałe doświadczenie","ru":"По моему мнению, это замечательный опыт"},{"pl":"według mnie","ru":"по моему мнению"},{"pl":"Osobiście lubię...","ru":"Лично я люблю..."},{"pl":"nie żałuję, że się zdecydowałem","ru":"не жалею, что решился"}]},{"title":"Работа и доход","text":"Как описывают работу и финансы:","examples":[{"pl":"prowadzić sklep internetowy","ru":"вести интернет-магазин"},{"pl":"zarabiać naprawdę dobrze","ru":"зарабатывать действительно хорошо"},{"pl":"Dzięki temu nie muszę się martwić o...","ru":"Благодаря этому мне не нужно беспокоиться о..."},{"pl":"koszty życia i podróżowania","ru":"стоимость жизни и путешествий"}]}],"tables":[],"exercises":[]}'::jsonb);
INSERT INTO theme_section (theme_id, type, sort_order, content) VALUES ('pl_theme16', 'grammar', 0, '{"notes":[{"title":"Дательный + Родительный (Celownik + Dopełniacz)","text":"Конструкция «komuś potrzeba czegoś»:","examples":[{"pl":"coś jest komuś potrzebne do czegoś","ru":"что-то кому-то нужно для чего-то"},{"pl":"Cyfrowym nomadom do pracy potrzebny jest tylko komputer","ru":"Цифровым номадам для работы нужен только компьютер"}]},{"title":"Винительный + Творительный (Biernik + Narzędnik)","text":"Глагоł «łączyć» требует вин. + твор. падежей:","examples":[{"pl":"łączyć coś z czymś","ru":"соединять что-то с чем-то"},{"pl":"łączyć pracę z życiem rodzinnym","ru":"соединять работу с семейной жизнью"}]},{"title":"Местный падеж (Miejscownik)","text":"После предлога «w» используется местный падеж:","examples":[{"pl":"zatrzymać się w ciekawym miejscu","ru":"остановиться в интересном месте"},{"pl":"w jakimś mieście","ru":"в каком-то городе"}]},{"title":"Родительный падеж (Dopełniacz)","text":"Глагол «korzystać» требует родительного с предлогом «z»:","examples":[{"pl":"korzystać z atutów","ru":"пользоваться преимуществами"},{"pl":"korzystać z udogodnień","ru":"пользоваться удобствами"},{"pl":"korzystać z życia","ru":"наслаждаться жизнью"}]},{"title":"Творительный падеж (Narzędnik)","text":"Глагол «zostać» (стать) требует творительного:","examples":[{"pl":"zostać cyfrowym nomadą","ru":"стать цифровым номадом"},{"pl":"widywać się z rodziną, z przyjaciółmi","ru":"видеться с семьёй, с друзьями"}]},{"title":"Винительный падеж (Biernik)","text":"Многие глаголы требуют винительного падежа:","examples":[{"pl":"nawiązywać kontakty, znajomości","ru":"заводить контакты, знакомства"},{"pl":"uczęszczać do szkoły","ru":"посещать школу"},{"pl":"wybierać kraj, zawód, studia","ru":"выбирать страну, профессию, учёбу"},{"pl":"prowadzić sklep internetowy, firmę","ru":"вести интернет-магазин, фирму"},{"pl":"martwić się o pieniądze, o pracę","ru":"беспокоиться о деньгах, о работе"}]}],"tables":[],"exercises":[]}'::jsonb);
INSERT INTO theme_section (theme_id, type, sort_order, content) VALUES ('pl_theme17', 'grammar', 0, '{"notes":[{"title":"Вводные конструкции и статистика","text":"Как описывают мир социальных сетей:","examples":[{"pl":"Żyjemy w świecie, w którym...","ru":"Мы живём в мире, в котором..."},{"pl":"na wyciągnięcie ręki","ru":"на расстоянии вытянутой руки"},{"pl":"Nietrudno się zgodzić z twierdzeniem, że...","ru":"Нетрудно согласиться, что..."}]},{"title":"Сравнительные конструкции","text":"Конструкция «im... tym...» (чем... тем...):","examples":[{"pl":"im bardziej popularny stał się Instagram, tym więcej osób zaczęło zastanawiać się","ru":"чем популярнее Instagram, тем больше людей задумывалось"}]},{"title":"Психологическое влияние","text":"Выражения о влиянии соцсетей на психику:","examples":[{"pl":"wywołują przypływ zazdrości","ru":"вызывают прилив зависти"},{"pl":"trudny do zniesienia","ru":"тяжело переносимый"},{"pl":"podbudowują swoje poczucie wartości","ru":"укрепляют чувство собственной значимости"}]},{"title":"Две стороны медали","text":"Как выражать противоположные аспекты:","examples":[{"pl":"To jedna strona medalu","ru":"Это одна сторона медали"},{"pl":"Druga pokazuje, że...","ru":"Другая показывает, что..."}]},{"title":"Зависимость от соцсетей","text":"Выражения о зависимости:","examples":[{"pl":"nie możemy oprzeć się pokusie","ru":"не можем устоять перед искушением"},{"pl":"trudniejsze do opanowania niż powstrzymanie się od palenia","ru":"труднее контролировать, чем отказаться от курения"}]}],"tables":[],"exercises":[]}'::jsonb);
INSERT INTO theme_section (theme_id, type, sort_order, content) VALUES ('pl_theme18', 'grammar', 0, '{"notes":[{"title":"Газеты и утренние ритуалы","text":"Как описывают привычку чтения газет:","examples":[{"pl":"Nie wyobrażam sobie śniadania bez czytania gazety","ru":"Не представляю завтрак без чтения газеты"},{"pl":"święty czas, przeznaczony wyłącznie dla mnie","ru":"святое время, предназначенное для меня"},{"pl":"nie ma mnie dla nikogo","ru":"меня ни для кого нет"}]},{"title":"Радио и музыка","text":"Выражения о радио и музыкальных предпочтениях:","examples":[{"pl":"Nie znoszę radia","ru":"Не выношу радио"},{"pl":"odkąd odkryłam Spotify","ru":"с тех пор как открыла Spotify"},{"pl":"radio znakomicie umila mi czas","ru":"радио прекрасно скрашивает время"}]},{"title":"Телевизор vs Интернет","text":"Противопоставление ТВ и интернета:","examples":[{"pl":"żyć bez tego pudła","ru":"жить без этого ящика"},{"pl":"Internet jest całym światem","ru":"Интернет — это весь мир"},{"pl":"jasno pokazuje jego wyższość","ru":"ясно показывает его превосходство"}]},{"title":"Стриминговые платформы","text":"Как говорят о Netflix и подписках:","examples":[{"pl":"jestem gorącym zwolennikiem platform takich jak Netflix","ru":"я горячий сторонник платформ типа Netflix"},{"pl":"namawiam na wykupienie abonamentu","ru":"уговариваю купить подписку"},{"pl":"pracuję na zmiany","ru":"работаю по сменам"}]},{"title":"Печать и YouTube","text":"Отношение к печати и видео:","examples":[{"pl":"Wolę magazyny kobiece","ru":"Предпочитаю женские журналы"},{"pl":"najwięcej czasu spędzam, przeglądając YouTube","ru":"больше всего времени провожу на YouTube"},{"pl":"Subskrybuję kilka kanałów","ru":"Подписан на несколько каналов"}]},{"title":"Игры и консоль","text":"Выражения об игровой культуре:","examples":[{"pl":"jestem urodzonym graczem","ru":"я прирождённый игрок"},{"pl":"nie zawalać spraw zawodowych","ru":"не запускать рабочие дела"},{"pl":"sprzęt szybko się starzeje","ru":"оборудование быстро устаревает"}]}],"tables":[],"exercises":[]}'::jsonb);
INSERT INTO theme_section (theme_id, type, sort_order, content) VALUES ('pl_theme19', 'email_writing', 0, '{"notes":[],"tables":[],"exercises":[{"id":"email_01","type":"telc","level":"B1","register":"nieformalny","category":"Nieformalny — do kolegi","scenario":"Właśnie wróciłeś/wróciłaś do domu z Wrocławia, gdzie spędziłeś/spędziłaś 4 tygodnie na Intensywnym Letnim Kursie Języka Polskiego. Jesteś bardzo zadowolony/zadowolona z zajęć językowych oraz wszystkich warunków (zakwaterowania, wyżywienia itd.).","recipient":"Twój kolega Marek","points":["Opisz, jak był zorganizowany kurs i jak wyglądał Twój plan dnia.","Opowiedz o innych uczestnikach kursu.","Napisz, co i dlaczego podobało Ci się najbardziej."],"etiquetteHint":"Nie zapomnij użyć odpowiednich zwrotów grzecznościowych na początku i na końcu e-maila.","minWords":100,"maxWords":150,"usefulPhrases":[{"label":"POCZĄTEK MAILA","phrases":["Cześć Marku!","Drogi Marku!","Co u Ciebie słychać?"]},{"label":"GŁÓWNA TREŚĆ MAILA","phrases":["Właśnie wróciłem z intensywnego kursu języka polskiego we Wrocławiu.","Chciałem Ci opowiedzieć, jak minęły mi te 4 tygodnie."]},{"label":"Konstrukcje czasu","phrases":["w zeszłym miesiącu","przez 4 tygodnie","codziennie od 9:00 do 14:00","w ubiegłym tygodniu"]},{"label":"Przysłówki częstotliwości","phrases":["codziennie","często","regularnie","czasem"]},{"label":"Konstrukcje miejsca","phrases":["na kursie","we Wrocławiu","w akademiku","w sali wykładowej"]},{"label":"Zwroty opisujące kolejność","phrases":["najpierw","potem","następnie","na zakończenie"]},{"label":"Inne przydatne zwroty","phrases":["zwłaszcza","oczywiście","koniecznie","również"]},{"label":"ZAKOŃCZENIE MAILA","phrases":["Pozdrawiam ciepło","Pozdrawiam serdecznie","Czekam na Twoją odpowiedź!"]}]},{"id":"email_02","type":"telc","level":"B1","register":"nieformalny","category":"Nieformalny — do koleżanki","scenario":"Właśnie przyjechałeś/przyjechałaś do Polski na studia i wprowadziłeś/wprowadziłaś się do nowego mieszkania, które dzielisz ze współlokatorami — innymi studentami.","recipient":"Twoja koleżanka Aleksandra","points":["Opisz, jak wygląda Twój pokój.","Opisz krótko swoich współlokatorów.","Przedstaw wady i zalety zakwaterowania w mieszkaniu studenckim."],"etiquetteHint":"Nie zapomnij użyć odpowiednich zwrotów grzecznościowych na początku i na końcu e-maila.","minWords":100,"maxWords":150,"usefulPhrases":[{"label":"POCZĄTEK MAILA","phrases":["Hej Ola!","Cześć Olu!","Co tam u Ciebie?"]},{"label":"GŁÓWNA TREŚĆ MAILA","phrases":["Właśnie wprowadziłem się do nowego mieszkania w Polsce.","Chciałam Ci opowiedzieć o moich współlokatorach."]},{"label":"Konstrukcje miejsca","phrases":["w nowym mieszkaniu","w pokoju","w kuchni","w akademiku"]},{"label":"Przysłówki częstotliwości","phrases":["codziennie","często","czasem","rzadko"]},{"label":"Zwroty opisujące kolejność","phrases":["po pierwsze","po drugie","po trzecie"]},{"label":"Inne przydatne zwroty","phrases":["zwłaszcza","również","oczywiście","zależy mi na tym, żeby"]},{"label":"ZAKOŃCZENIE MAILA","phrases":["Ściskam!","Pisz!","Czekam na wiadomości!"]}]},{"id":"email_03","type":"telc","level":"B1","register":"nieformalny","category":"Nieformalny — opis doświadczeń","scenario":"Właśnie wróciłeś/wróciłaś z wycieczki objazdowej po największych miastach Polski. Zwiedziłeś/zwiedziłaś Warszawę, Kraków, Gdańsk, Poznań i Wrocław. Wyjazd bardzo Ci się podobał.","recipient":"Twój kolega Marek","points":["Opisz, jak zorganizowana była wycieczka (transport, noclegi, wyżywienie itd.).","Napisz, co szczególnie Ci się podobało.","Opowiedz o innych uczestnikach wycieczki, których poznałeś/poznałaś."],"etiquetteHint":"Nie zapomnij użyć odpowiednich zwrotów grzecznościowych na początku i na końcu e-maila.","minWords":100,"maxWords":150,"usefulPhrases":[{"label":"POCZĄTEK MAILA","phrases":["Cześć Marku!","Hej!","Co u Ciebie?"]},{"label":"GŁÓWNA TREŚĆ MAILA","phrases":["Właśnie wróciłem z niesamowitej wycieczki po Polsce.","Muszę Ci opowiedzieć, co widziałem!"]},{"label":"Konstrukcje czasu","phrases":["w zeszłym tygodniu","przez 5 dni","w ubiegłym miesiącu","za rok"]},{"label":"Konstrukcje miejsca","phrases":["w Warszawie","w Krakowie","w Gdańsku","na wycieczce","na Starym Mieście"]},{"label":"Zwroty opisujące kolejność","phrases":["najpierw","potem","następnie","na zakończenie"]},{"label":"Inne przydatne zwroty","phrases":["zwłaszcza","na pewno","koniecznie","wszędzie"]},{"label":"ZAKOŃCZENIE MAILA","phrases":["Pozdrawiam!","Musisz tam pojechać!","Do zobaczenia!"]}]},{"id":"email_04","type":"telc","level":"B1","register":"nieformalny","category":"Nieformalny — nowa praca","scenario":"Właśnie zacząłeś/zaczęłaś nową pracę. Po pierwszym dniu wracasz do domu zestresowany/zestresowana nowymi obowiązkami.","recipient":"Twój brat lub Twoja siostra","points":["Opisz warunki i obowiązki w swojej nowej pracy.","Opisz krótko nowych współpracowników.","Przedstaw wady i zalety pracy na tym stanowisku."],"etiquetteHint":"Nie zapomnij użyć odpowiednich zwrotów grzecznościowych na początku i na końcu e-maila.","minWords":100,"maxWords":150,"usefulPhrases":[{"label":"POCZĄTEK MAILA","phrases":["Cześć!","Hej!","Wiesz co się stało?"]},{"label":"GŁÓWNA TREŚĆ MAILA","phrases":["Właśnie zacząłem nową pracę.","Po pierwszym dniu jestem trochę zestresowany."]},{"label":"Konstrukcje czasu","phrases":["dzisiaj","wczoraj","od jutra","w przyszłym tygodniu"]},{"label":"Konstrukcje miejsca","phrases":["w biurze","w nowej firmie","na stanowisku"]},{"label":"Zwroty opisujące kolejność","phrases":["po pierwsze","po drugie","przede wszystkim"]},{"label":"Inne przydatne zwroty","phrases":["na pewno","oczywiście","również","lepiej / gorzej"]},{"label":"ZAKOŃCZENIE MAILA","phrases":["Ściskam!","Trzymaj kciuki!","Dam znać, jak pójdzie!"]}]},{"id":"email_05","type":"telc","level":"B1","register":"nieformalny","category":"Nieformalny — propozycja wizyty","scenario":"Odwiedzi Cię kolega/koleżanka z Polski i spędzicie razem kilka dni. Bardzo chciałbyś/chciałabyś zobaczyć najciekawsze miejsca w Twoim mieście.","recipient":"Kolega/koleżanka z Polski","points":["Wymień i krótko opisz kilka interesujących obiektów w okolicy.","Napisz, co będziecie robić wieczorami.","Uzasadnij, dlaczego proponujesz taki plan spędzenia czasu."],"etiquetteHint":"Nie zapomnij użyć odpowiednich zwrotów grzecznościowych na początku i na końcu e-maila.","minWords":100,"maxWords":150,"usefulPhrases":[{"label":"POCZĄTEK MAILA","phrases":["Cześć!","Hej!","Super, że przyjeżdżasz!"]},{"label":"GŁÓWNA TREŚĆ MAILA","phrases":["Przygotowałem plan zwiedzania na kilka dni.","Mam nadzieję, że będzie Ci się podobało."]},{"label":"Konstrukcje czasu","phrases":["w przyszłym tygodniu","za kilka dni","wieczorami","jutro"]},{"label":"Konstrukcje miejsca","phrases":["w moim mieście","w okolicy","w restauracji","na koncercie"]},{"label":"Zwroty opisujące kolejność","phrases":["najpierw","potem","wieczorem","na zakończenie dnia"]},{"label":"Inne przydatne zwroty","phrases":["zwłaszcza","na pewno","koniecznie","być może"]},{"label":"ZAKOŃCZENIE MAILA","phrases":["Do zobaczenia!","Będzie fajnie!","Czekam z niecierpliwością!"]}]},{"id":"email_06","type":"telc","level":"B1","register":"półformalny","category":"Półformalny — do redaktorki","scenario":"Brałeś/brałaś ze swoją klasą udział w bardzo ciekawym festiwalu filmowym, który teraz chcesz opisać na stronie internetowej swojej szkoły.","recipient":"Pani Marzena Nowicka (redaktorka strony)","points":["Opisz przebieg festiwalu i najważniejsze wydarzenia.","Napisz, jakie dokładnie to było wydarzenie i kiedy się odbyło.","Przedstaw swoją opinię o tym wydarzeniu."],"etiquetteHint":"Nie zapomnij użyć odpowiednich zwrotów grzecznościowych na początku i na końcu e-maila.","minWords":100,"maxWords":150,"usefulPhrases":[{"label":"POCZĄTEK MAILA","phrases":["Szanowna Pani Nowicka","Szanowna Pani","Dzień dobry"]},{"label":"GŁÓWNA TREŚĆ MAILA","phrases":["Zwracam się z uprzejmą prośbą o opublikowanie relacji z festiwalu filmowego.","Chciałbym podzielić się wrażeniami z wydarzenia."]},{"label":"Konstrukcje czasu","phrases":["w ubiegłym tygodniu","w zeszłym miesiącu","w piątek 10 maja"]},{"label":"Konstrukcje miejsca","phrases":["na festiwalu","w kinie","na sali projekcyjnej"]},{"label":"Inne przydatne zwroty","phrases":["przede wszystkim","zwłaszcza","zależy mi na tym, żeby","oczywiście"]},{"label":"ZAKOŃCZENIE MAILA","phrases":["Z wyrazami szacunku","Z poważaniem","Będę wdzięczna za odpowiedź."]}]},{"id":"email_07","type":"telc","level":"B1","register":"nieformalny","category":"Nieformalny — zaproszenie","scenario":"W najbliższą sobotę organizujesz przyjęcie urodzinowe w domu. Chcesz zaprosić kilku przyjaciół na wieczór pełen muzyki, dobrego jedzenia i gier towarzyskich.","recipient":"Twój przyjaciel Tomek","points":["Podaj datę, godzinę i dokładny adres przyjęcia.","Opisz, co planujesz przygotować (jedzenie, muzyka, atrakcje).","Poproś o potwierdzenie przybycia i informację o ewentualnych alergiach pokarmowych."],"etiquetteHint":"Nie zapomnij użyć odpowiednich zwrotów grzecznościowych na początku i na końcu e-maila.","minWords":100,"maxWords":150,"usefulPhrases":[{"label":"POCZĄTEK MAILA","phrases":["Hej Tomek!","Cześć Tomku!","Zapraszam Cię serdecznie!"]},{"label":"GŁÓWNA TREŚĆ MAILA","phrases":["W najbliższą sobotę organizuję przyjęcie urodzinowe.","Planuję wieczór pełen muzyki i dobrego jedzenia."]},{"label":"Konstrukcje czasu","phrases":["w sobotę","o godzinie 18:00","w najbliższy weekend","od 18:00 do północy"]},{"label":"Konstrukcje miejsca","phrases":["w domu","w ogrodzie","na tarasie"]},{"label":"Inne przydatne zwroty","phrases":["przede wszystkim","oczywiście","również","koniecznie"]},{"label":"ZAKOŃCZENIE MAILA","phrases":["Będzie super!","Daj znać, czy przyjdziesz!","Pozdrawiam!"]}]},{"id":"email_08","type":"telc","level":"B1","register":"formalny","category":"Formalny — skarga do zarządcy","scenario":"Od trzech tygodni sąsiedzi z mieszkania powyżej organizują głośne imprezy w każdy piątek i sobotę. Przeszkadza Ci to w pracy i wypoczynku. Napiszesz oficjalną skargę do zarządcy budynku.","recipient":"Zarządca budynku","points":["Opisz problem z hałasem — kiedy, jak często i jak bardzo Ci to przeszkadza.","Napisz, jakie kroki już podjąłeś/podjęłaś (np. rozmowa z sąsiadami).","Określ, czego oczekujesz od zarządcy."],"etiquetteHint":"Nie zapomnij użyć odpowiednich zwrotów grzecznościowych na początku i na końcu e-maila.","minWords":120,"maxWords":180,"usefulPhrases":[{"label":"POCZĄTEK MAILA","phrases":["Szanowny Panie Zarządco","Szanowni Państwo"]},{"label":"GŁÓWNA TREŚĆ MAILA","phrases":["Zwracam się z uprzejmą prośbą o interwencję w sprawie hałasu.","Kontaktuję się w związku z powtarzającym się zakłócaniem spokoju."]},{"label":"Konstrukcje czasu","phrases":["od trzech tygodni","w każdy piątek i sobotę","w godzinach nocnych"]},{"label":"Przysłówki częstotliwości","phrases":["regularnie","często","codziennie","sporadycznie"]},{"label":"Zwroty opisujące kolejność","phrases":["po pierwsze","po drugie","przede wszystkim"]},{"label":"Inne przydatne zwroty","phrases":["przede wszystkim","również","zwłaszcza","na pewno"]},{"label":"ZAKOŃCZENIE MAILA","phrases":["Z wyrazami szacunku","Z poważaniem","Liczę na pozytywne rozpatrzenie mojej prośby.","Będę wdzięczny za szybką odpowiedź."]}]},{"id":"email_09","type":"telc","level":"B1","register":"formalny","category":"Formalny — rejestracja na kurs","scenario":"Chcesz zapisać się na kurs języka niemieckiego w centrum językowym „Lingua\" w Warszawie. Potrzebujesz informacji o dostępnych terminach, cenie i wymaganiach wstępnych.","recipient":"Sekretariat centrum „Lingua\"","points":["Przedstaw się krótko i podaj swój aktualny poziom znajomości niemieckiego.","Zapytaj o dostępne terminy kursów, cenę oraz czy potrzebne są materiały dodatkowe.","Zapytaj o możliwość płatności w ratach lub dofinansowanie."],"etiquetteHint":"Nie zapomnij użyć odpowiednich zwrotów grzecznościowych na początku i na końcu e-maila.","minWords":100,"maxWords":150,"usefulPhrases":[{"label":"POCZĄTEK MAILA","phrases":["Szanowni Państwo","Szanowna Pani / Szanowny Panie"]},{"label":"GŁÓWNA TREŚĆ MAILA","phrases":["Chciałbym się zapisać na kurs języka niemieckiego.","Zwracam się z uprzejmą prośbą o udzielenie informacji na temat kursu.","Zapoznałem się z informacjami na stronie Państwa szkoły."]},{"label":"Konstrukcje czasu","phrases":["w przyszłym miesiącu","od września","w semestrze jesiennym","za tydzień"]},{"label":"Konstrukcje miejsca","phrases":["w Warszawie","w centrum językowym „Lingua\"","na kursie"]},{"label":"Inne przydatne zwroty","phrases":["przede wszystkim","również","oczywiście"]},{"label":"ZAKOŃCZENIE MAILA","phrases":["Z góry dziękuję za odpowiedź.","Z poważaniem","Będę wdzięczny za szybką odpowiedź."]}]},{"id":"email_10","type":"telc","level":"B2","register":"formalny","category":"Formalny — list motywacyjny","scenario":"Znalazłeś/znalazłaś ogłoszenie o pracę na stanowisku asystenta/asystentki w biurze podróży „Globtour\". Chcesz aplikować i przesłać swoje CV oraz list motywacyjny.","recipient":"Dział Rekrutacji firmy „Globtour\"","points":["Wskaż, na jakie stanowisko aplikujesz i skąd znasz ogłoszenie.","Opisz swoje doświadczenie zawodowe i umiejętności przydatne w tej pracy.","Wyjaśnij, dlaczego chcesz pracować właśnie w firmie „Globtour\"."],"etiquetteHint":"Nie zapomnij użyć odpowiednich zwrotów grzecznościowych na początku i na końcu e-maila.","minWords":150,"maxWords":200,"usefulPhrases":[{"label":"POCZĄTEK MAILA","phrases":["Szanowni Państwo","Szanowna Pani / Szanowny Panie"]},{"label":"GŁÓWNA TREŚĆ MAILA","phrases":["W odpowiedzi na Państwa ogłoszenie zamieszczone na stronie...","Pragnę złożyć swoją kandydaturę na stanowisko asystenta.","W załączniku przesyłam swoje CV."]},{"label":"Konstrukcje czasu","phrases":["w zeszłym roku","przez 2 lata","od trzech miesięcy","w ubiegłym miesiącu"]},{"label":"Konstrukcje miejsca","phrases":["w firmie „Globtour\"","w biurze podróży","na stanowisku asystenta"]},{"label":"Inne przydatne zwroty","phrases":["przede wszystkim","zwłaszcza","również","zależy mi na tym, żeby","na pewno"]},{"label":"ZAKOŃCZENIE MAILA","phrases":["Z poważaniem","Z wyrazami szacunku","Będę wdzięczny za rozpatrzenie mojej kandydatury.","Liczę na pozytywną odpowiedź."]}]},{"id":"email_11","type":"telc","level":"B1","register":"formalny","category":"Formalny — zamówienie cateringowe","scenario":"Organizujesz spotkanie firmowe dla 20 osób i chcesz zamówić catering z restauracji „Smakosz\". Potrzebujesz potwierdzenia dostawy i menu.","recipient":"Restauracja „Smakosz\"","points":["Podaj datę, godzinę dostawy oraz adres miejsca imprezy.","Zapytaj o dostępne menu i cenę za osobę.","Poinformuj o osobach z alergiami pokarmowymi (2 osoby bezglutenowe)."],"etiquetteHint":"Nie zapomnij użyć odpowiednich zwrotów grzecznościowych na początku i na końcu e-maila.","minWords":100,"maxWords":150,"usefulPhrases":[{"label":"POCZĄTEK MAILA","phrases":["Szanowni Państwo","Szanowna Pani / Szanowny Panie"]},{"label":"GŁÓWNA TREŚĆ MAILA","phrases":["Chciałbym zamówić catering na spotkanie firmowe.","Zwracam się z uprzejmą prośbą o przygotowanie oferty cateringowej."]},{"label":"Konstrukcje czasu","phrases":["w piątek 15 czerwca","o godzinie 12:00","w przyszłym tygodniu"]},{"label":"Konstrukcje miejsca","phrases":["w biurze","pod wskazany adres","na miejscu"]},{"label":"Inne przydatne zwroty","phrases":["przede wszystkim","również","zwłaszcza","oczywiście"]},{"label":"ZAKOŃCZENIE MAILA","phrases":["Proszę o potwierdzenie dostawy.","Z góry dziękuję za odpowiedź.","Z poważaniem"]}]},{"id":"email_12","type":"telc","level":"B1","register":"półformalny","category":"Półformalny — zapytanie o mieszkanie","scenario":"Znalazłeś/znalazłaś w internecie ogłoszenie o wynajmie mieszkania dwupokojowego w Krakowie. Mieszkanie Ci się podoba, ale chcesz uzyskać więcej informacji.","recipient":"Właściciel mieszkania","points":["Przedstaw się krótko i napisz, skąd masz informacje o mieszkaniu.","Zapytaj o dokładny adres, piętro oraz czy mieszkanie jest umeblowane.","Zapytaj o wysokość czynszu, kaucję oraz kiedy możliwe jest wprowadzenie."],"etiquetteHint":"Nie zapomnij użyć odpowiednich zwrotów grzecznościowych na początku i na końcu e-maila.","minWords":100,"maxWords":150,"usefulPhrases":[{"label":"POCZĄTEK MAILA","phrases":["Dzień dobry","Szanowny Panie / Szanowna Pani"]},{"label":"GŁÓWNA TREŚĆ MAILA","phrases":["Piszę w sprawie ogłoszenia zamieszczonego na stronie...","Jestem zainteresowany wynajmem mieszkania."]},{"label":"Konstrukcje czasu","phrases":["w przyszłym miesiącu","od września","za tydzień","jak najszybciej"]},{"label":"Konstrukcje miejsca","phrases":["w Krakowie","w mieszkaniu","w centrum","na piętrze"]},{"label":"Inne przydatne zwroty","phrases":["również","przede wszystkim","oczywiście","być może"]},{"label":"ZAKOŃCZENIE MAILA","phrases":["Z góry dziękuję za odpowiedź.","Z wyrazami szacunku","Będę wdzięczny za szybką odpowiedź."]}]},{"id":"email_13","type":"telc","level":"B1","register":"nieformalny","category":"Nieformalny — relacja z wakacji","scenario":"Właśnie wróciłeś/wróciłaś z dwutygodniowych wakacji nad Morzem Bałtyckim. Pogoda była fantastyczna, a ty spędziłeś/spędziłaś dużo czasu na plaży i zwiedzaniu okolicy.","recipient":"Twój przyjaciel Piotr","points":["Opisz, gdzie dokładnie byłeś/byłaś i z kim podróżowałeś/podróżowałaś.","Napisz o najpiękniejszych miejscach, które odwiedziłeś/odwiedziłaś.","Przedstaw swoje wrażenia z podróży i czy polecasz to miejsce."],"etiquetteHint":"Nie zapomnij użyć odpowiednich zwrotów grzecznościowych na początku i na końcu e-maila.","minWords":100,"maxWords":150,"usefulPhrases":[{"label":"POCZĄTEK MAILA","phrases":["Cześć Piotrze!","Hej!","Co u Ciebie słychać?"]},{"label":"GŁÓWNA TREŚĆ MAILA","phrases":["Właśnie wróciłem z dwutygodniowych wakacji nad Bałtykiem.","Pogoda była fantastyczna!"]},{"label":"Konstrukcje czasu","phrases":["w zeszłym tygodniu","przez 2 tygodnie","codziennie","w ubiegłym miesiącu"]},{"label":"Konstrukcje miejsca","phrases":["nad Morzem Bałtyckim","na plaży","w hotelu","w okolicy"]},{"label":"Zwroty opisujące kolejność","phrases":["najpierw","potem","na zakończenie"]},{"label":"Inne przydatne zwroty","phrases":["na pewno","koniecznie","zwłaszcza","wszędzie","być może"]},{"label":"ZAKOŃCZENIE MAILA","phrases":["Pozdrawiam!","Musisz tam pojechać!","Czekam na Twoją wiadomość!"]}]},{"id":"email_14","type":"telc","level":"B1","register":"formalny","category":"Formalny — zmiana wizyty u lekarza","scenario":"Masz umówioną wizytę u lekarza na następny wtorek o godzinie 10:00, ale niestety nie możesz przyjść w tym terminie z powodu wyjazdu służbowego. Musisz zmienić termin.","recipient":"Przychodnia „Zdrowie\"","points":["Podaj datę i godzinę obecnej wizyty oraz imię i nazwisko.","Wyjaśnij przyczynę nieobecności.","Zaproponuj 2-3 alternatywne terminy wizyty."],"etiquetteHint":"Nie zapomnij użyć odpowiednich zwrotów grzecznościowych na początku i na końcu e-maila.","minWords":80,"maxWords":130,"usefulPhrases":[{"label":"POCZĄTEK MAILA","phrases":["Szanowni Państwo","Szanowna Pani / Szanowny Panie"]},{"label":"GŁÓWNA TREŚĆ MAILA","phrases":["Chciałbym odwołać wizytę zaplanowaną na wtorek.","Zwracam się z uprzejmą prośbą o przełożenie terminu wizyty."]},{"label":"Konstrukcje czasu","phrases":["w następny wtorek","o godzinie 10:00","w środę lub czwartek","za tydzień"]},{"label":"Konstrukcje miejsca","phrases":["w przychodni „Zdrowie\"","w gabinecie lekarskim"]},{"label":"Inne przydatne zwroty","phrases":["niestety","z powodu","przede wszystkim","oczywiście"]},{"label":"ZAKOŃCZENIE MAILA","phrases":["Z poważaniem","Z góry dziękuję za odpowiedź.","Proszę o potwierdzenie zmiany terminu."]}]},{"id":"email_15","type":"telc","level":"B1","register":"nieformalny","category":"Nieformalny — zaproszenie na grilla","scenario":"W sobotę planujesz zorganizować grilla w ogrodzie z okazji Twoich urodzin. Chcesz zaprosić przyjaciół na wieczór pełen dobrej atmosfery, muzyki i pysznego jedzenia.","recipient":"Twoi przyjaciele","points":["Podaj datę, godzinę i miejsce grillowania.","Opisz, co planujesz przygotować na grilla i jakie atrakcje będą dostępne.","Poproś gości o informację, czy przyjdą i czy coś konkretnego chcą przynieść."],"etiquetteHint":"Nie zapomnij użyć odpowiednich zwrotów grzecznościowych na początku i na końcu e-maila.","minWords":100,"maxWords":150,"usefulPhrases":[{"label":"POCZĄTEK MAILA","phrases":["Hej wszystkim!","Cześć!","Zapraszam Was serdecznie!"]},{"label":"GŁÓWNA TREŚĆ MAILA","phrases":["W sobotę organizuję grilla w ogrodzie z okazji moich urodzin.","Planuję wieczór pełen dobrej atmosfery i muzyki."]},{"label":"Konstrukcje czasu","phrases":["w sobotę","o godzinie 16:00","od 16:00 do późnego wieczora","w najbliższy weekend"]},{"label":"Konstrukcje miejsca","phrases":["w ogrodzie","w moim domu","na tarasie","na grillu"]},{"label":"Inne przydatne zwroty","phrases":["przede wszystkim","oczywiście","również","koniecznie","zwłaszcza"]},{"label":"ZAKOŃCZENIE MAILA","phrases":["Będzie wesoło!","Dajcie znać, czy przyjdziecie!","Pozdrawiam!"]}]},{"id":"email_16","type":"telc","level":"B1","register":"nieformalny","category":"Nieformalny — adopcja zwierzęcia","scenario":"Zdecydowałeś/zdecydowałaś się na adopcję zwierzęcia ze schroniska i chcesz podzielić się swoim doświadczeniem. Chcesz opowiedzieć znajomemu o procesie adopcji i zachęcić go do podjęcia podobnej decyzji.","recipient":"Twój znajomy","points":["Opisz, jakie zwierzę adoptowałeś/adoptowałaś i jak wyglądał proces adopcji.","Opisz pierwsze wrażenia związane z pobytem zwierzęcia w domu.","Zachęć znajomego do adopcji i wyjaśnij, dlaczego warto pomagać zwierzętom ze schronisk."],"etiquetteHint":"Nie zapomnij użyć odpowiednich zwrotów grzecznościowych na początku i na końcu e-maila.","minWords":100,"maxWords":150,"usefulPhrases":[{"label":"POCZĄTEK MAILA","phrases":["Cześć!","Hej!","Muszę Ci coś opowiedzieć!"]},{"label":"GŁÓWNA TREŚĆ MAILA","phrases":["Zdecydowałem się na adopcję zwierzęcia ze schroniska.","Chciałem podzielić się z Tobą tym doświadczeniem."]},{"label":"Konstrukcje czasu","phrases":["w zeszłym tygodniu","przedwczoraj","od kilku dni","w ubiegłym miesiącu"]},{"label":"Konstrukcje miejsca","phrases":["w schronisku","w domu","w pokoju","w nowym miejscu"]},{"label":"Zwroty opisujące kolejność","phrases":["najpierw","potem","następnie","na zakończenie"]},{"label":"Inne przydatne zwroty","phrases":["przede wszystkim","na pewno","koniecznie","zależy mi na tym, żeby"]},{"label":"ZAKOŃCZENIE MAILA","phrases":["Pozdrawiam serdecznie","Daj znać, co o tym myślisz!","Czekam na Twoją odpowiedź!"]}]},{"id":"email_17","type":"telc","level":"B1","register":"nieformalny","category":"Nieformalny — ekologiczne porady","scenario":"Twój znajomy chciałby prowadzić bardziej ekologiczny tryb życia i poprosił Cię o kilka praktycznych wskazówek. Chcesz podzielić się z nim poradami dotyczącymi codziennych działań na rzecz ochrony środowiska.","recipient":"Twój znajomy","points":["Przedstaw proste sposoby na zmniejszenie zużycia plastiku.","Zaproponuj ekologiczne nawyki, które można wprowadzić w codziennym życiu.","Zmotywuj znajomego do stopniowej zmiany stylu życia na bardziej przyjazny dla środowiska."],"etiquetteHint":"Nie zapomnij użyć odpowiednich zwrotów grzecznościowych na początku i na końcu e-maila.","minWords":100,"maxWords":150,"usefulPhrases":[{"label":"POCZĄTEK MAILA","phrases":["Hej!","Cześć!","Świetnie, że chcesz żyć bardziej ekologicznie!"]},{"label":"GŁÓWNA TREŚĆ MAILA","phrases":["Przygotowałem dla Ciebie kilka praktycznych wskazówek.","Oto moje pomysły na zmniejszenie zużycia plastiku."]},{"label":"Przysłówki częstotliwości","phrases":["codziennie","często","regularnie","czasem","rzadko"]},{"label":"Zwroty opisujące kolejność","phrases":["po pierwsze","po drugie","po trzecie","przede wszystkim"]},{"label":"Inne przydatne zwroty","phrases":["na pewno","zależy mi na tym, żeby","również","oczywiście","lepiej"]},{"label":"ZAKOŃCZENIE MAILA","phrases":["Daj znać, jak Ci idzie!","Pozdrawiam!","Powodzenia!"]}]},{"id":"email_18","type":"telc","level":"B1","register":"nieformalny","category":"Nieformalny — porady dla autostopowicza","scenario":"Twój znajomy planuje podróż autostopem, ale ma pewne obawy i chciałby otrzymać kilka wskazówek. Chcesz doradzić mu, jak dobrze przygotować się do takiej podróży i na co zwrócić uwagę.","recipient":"Twój znajomy","points":["Doradź, jak wybrać trasę i przygotować się do podróży autostopem.","Napisz, jakie rzeczy powinien/powinna ze sobą zabrać.","Poleć sprawdzone aplikacje, fora lub grupy dla autostopowiczów."],"etiquetteHint":"Nie zapomnij użyć odpowiednich zwrotów grzecznościowych na początku i na końcu e-maila.","minWords":100,"maxWords":150,"usefulPhrases":[{"label":"POCZĄTEK MAILA","phrases":["Cześć!","Hej!","To świetna przygoda!"]},{"label":"GŁÓWNA TREŚĆ MAILA","phrases":["Przygotowałem dla Ciebie kilka wskazówek dotyczących podróży autostopem.","Pamiętaj, żeby dobrze zaplanować trasę."]},{"label":"Konstrukcje czasu","phrases":["w przyszłym tygodniu","za kilka dni","w ciągu dnia","wieczorem"]},{"label":"Konstrukcje miejsca","phrases":["na trasie","na autostradzie","na stacji benzynowej","w aplikacji"]},{"label":"Zwroty opisujące kolejność","phrases":["po pierwsze","po drugie","najpierw","potem"]},{"label":"Inne przydatne zwroty","phrases":["przede wszystkim","koniecznie","na pewno","być może","zależy mi na tym, żeby"]},{"label":"ZAKOŃCZENIE MAILA","phrases":["Trzymaj się!","Daj znać, jak podróżujesz!","Pozdrawiam!"]}]},{"id":"email_19","type":"telc","level":"B1","register":"nieformalny","category":"Nieformalny — organizacja przyjęcia dla dziecka","scenario":"Twój znajomy organizuje przyjęcie urodzinowe dla swojego dziecka w domu i poprosił Cię o rady dotyczące przygotowań. Chcesz podzielić się praktycznymi wskazówkami dotyczącymi organizacji takiej imprezy.","recipient":"Twój znajomy","points":["Zaproponuj pomysły na dekoracje i motyw przewodni przyjęcia.","Poleć zabawy i atrakcje odpowiednie dla dzieci.","Doradź, jakie przekąski i napoje najlepiej sprawdzą się na imprezie."],"etiquetteHint":"Nie zapomnij użyć odpowiednich zwrotów grzecznościowych na początku i na końcu e-maila.","minWords":100,"maxWords":150,"usefulPhrases":[{"label":"POCZĄTEK MAILA","phrases":["Hej!","Cześć!","Z przyjemnością pomogę!"]},{"label":"GŁÓWNA TREŚĆ MAILA","phrases":["Przygotowałam kilka pomysłów na przyjęcie urodzinowe dla dziecka.","Oto moje propozycje dekoracji i zabaw."]},{"label":"Konstrukcje miejsca","phrases":["w domu","w ogrodzie","w salonie","na podwórku"]},{"label":"Zwroty opisujące kolejność","phrases":["po pierwsze","po drugie","najpierw","potem","na zakończenie"]},{"label":"Inne przydatne zwroty","phrases":["przede wszystkim","na pewno","również","zwłaszcza","oczywiście"]},{"label":"ZAKOŃCZENIE MAILA","phrases":["Powodzenia!","Daj znać, jak poszło!","Pozdrawiam!"]}]}]}'::jsonb);
INSERT INTO theme_section (theme_id, type, sort_order, content) VALUES ('pl_theme20', 'grammar', 0, '{"notes":[{"title":"Глаголы с -m в форме ja","text":"У многих частотных польских глаголов в 1-м лице единственного числа окончание -m. Часто достаточно убрать -ć у инфинитива и добавить личное окончание: -m, -sz, нулевое, -my, -cie, -ją.","examples":[{"pl":"rozumieć → rozumiem, rozumiesz, rozumie","ru":"понимать → я понимаю, ты понимаешь, он/она понимает"},{"pl":"szukać → szukam, szukasz, szuka","ru":"искать → я ищу, ты ищешь, он/она ищет"},{"pl":"mieszkać → mieszkam w Polsce","ru":"жить → я живу в Польше"},{"pl":"czytać → czytam książkę","ru":"читать → я читаю книгу"},{"pl":"kochać → kocham cię","ru":"любить → я тебя люблю"},{"pl":"pamiętać → Pamiętam to.","ru":"помнить → Я это помню."},{"pl":"trzymać → Trzymam książkę.","ru":"держать → Я держу книгу."},{"pl":"grać → Gram w piłkę.","ru":"играть → Я играю в футбол."},{"pl":"śpiewać → Śpiewam piosenkę.","ru":"петь → Я пою песню."}]},{"title":"Глаголы с się","text":"Возвратная частица się обычно стоит после глагола или рядом с ним. В форме ja окончание глагола остаётся тем же: spotykam się.","examples":[{"pl":"spotykać się → Spotykam się z Anną.","ru":"встречаться → Я встречаюсь с Анной."},{"pl":"Spotykasz się z Markiem?","ru":"Ты встречаешься с Мареком?"}]},{"title":"Управление частотных глаголов","text":"У некоторых глаголов важно запоминать не только форму ja, но и падеж или предлог после глагола.","examples":[{"pl":"pomagać komuś → Pomagam mamie.","ru":"помогать кому-то → Я помогаю маме."},{"pl":"odpowiadać na coś → Odpowiadam na pytanie.","ru":"отвечать на что-то → Я отвечаю на вопрос."},{"pl":"używać czegoś → Używam słownika.","ru":"пользоваться чем-то → Я пользуюсь словарём."},{"pl":"sprawdzać coś → Sprawdzam słowo.","ru":"проверять что-то → Я проверяю слово."},{"pl":"zbierać coś → Zbieram znaczki.","ru":"собирать что-то → Я собираю марки."}]},{"title":"Czekać na + biernik","text":"Глагол czekać требует предлога na и винительного падежа.","examples":[{"pl":"Czekam na Annę.","ru":"Я жду Анну."},{"pl":"Czekasz na tramwaj?","ru":"Ты ждёшь трамвай?"}]},{"title":"Как задавать вопросы","text":"Вопрос можно сделать интонацией или частицей czy. Частица czy ставится в начало предложения и делает вопрос более явным.","examples":[{"pl":"Przyjdziesz na moje urodziny?","ru":"Ты придёшь ко мне на день рождения?"},{"pl":"Czy przyjdziesz na moje urodziny?","ru":"Придёшь ли ты ко мне на день рождения?"},{"pl":"Słyszysz?","ru":"Ты слышишь?"}]},{"title":"Вежливое обращение Pan/Pani","text":"В польском вежливое обращение строится не через wy, а через Pan/Pani с глаголом в 3-м лице единственного числа.","examples":[{"pl":"Czy Pan mówi po polsku?","ru":"Вы говорите по-польски? (к мужчине)"},{"pl":"Czy Pani mieszka tutaj?","ru":"Вы живёте здесь? (к женщине)"},{"pl":"Panowie / Panie / Państwo","ru":"господа / дамы / дамы и господа, смешанная группа"}]},{"title":"Звательный падеж","text":"При прямом обращении Pan меняется на Panie, а Pani остаётся Pani.","examples":[{"pl":"Panie Profesorze!","ru":"Господин профессор!"},{"pl":"Pani Anno!","ru":"Госпожа Анна!"}]},{"title":"Глагол как целое предложение","text":"Личное окончание часто уже показывает подлежащее, поэтому местоимение можно опустить.","examples":[{"pl":"Widzę.","ru":"Я вижу."},{"pl":"Słyszysz?","ru":"Ты слышишь?"},{"pl":"Idę.","ru":"Я иду."}]}],"tables":[{"verb":"rozumieć","translation":"понимать","rows":[{"pronoun":"ja","form":"rozumiem","ipa":"/rɔˈzumjɛm/"},{"pronoun":"ty","form":"rozumiesz","ipa":"/rɔˈzumjɛʂ/"},{"pronoun":"on/ona/ono","form":"rozumie","ipa":"/rɔˈzumjɛ/"},{"pronoun":"my","form":"rozumiemy","ipa":"/rɔzuˈmjɛmɨ/"},{"pronoun":"wy","form":"rozumiecie","ipa":"/rɔzuˈmjɛt͡ɕɛ/"},{"pronoun":"oni/one","form":"rozumieją","ipa":"/rɔzuˈmjɛjɔ̃/"}]},{"verb":"szukać","translation":"искать","rows":[{"pronoun":"ja","form":"szukam","ipa":"/ˈʂukam/"},{"pronoun":"ty","form":"szukasz","ipa":"/ˈʂukaʂ/"},{"pronoun":"on/ona/ono","form":"szuka","ipa":"/ˈʂuka/"},{"pronoun":"my","form":"szukamy","ipa":"/ʂuˈkamɨ/"},{"pronoun":"wy","form":"szukacie","ipa":"/ʂuˈkat͡ɕɛ/"},{"pronoun":"oni/one","form":"szukają","ipa":"/ʂuˈkajɔ̃/"}]}],"exercises":[]}'::jsonb);
INSERT INTO theme_section (theme_id, type, sort_order, content) VALUES ('pl_theme21', 'grammar', 0, '{"notes":[{"title":"Глаголы 2-го спряжения (Koniugacja II)","text":"Большинство польских глаголов 2-го спряжения соответствуют русским глаголам 2-го спряжения. В форме 2-го лица единственного числа (ты) они имеют окончание -isz или -ysz — аналог русского -ишь.","examples":[{"pl":"mówić → mówisz (ты говоришь)","ru":"говорить → говоришь"},{"pl":"myśleć → myślisz (ты думаешь)","ru":"думать → думаешь"},{"pl":"robić → robisz (ты делаешь)","ru":"делать → делаешь"},{"pl":"wierzyć → wierzysz (ты веришь)","ru":"верить → веришь"}]},{"title":"Окончания глаголов 2-го спряжения","text":"Таблица окончаний для всех лиц. Основа берётся от инфинитива без -ć/-eć/-ić/-yć:","examples":[{"pl":"ja: -ę","ru":"я: -ę"},{"pl":"ty: -isz / -ysz","ru":"ты: -isz / -ysz"},{"pl":"on/ona/ono: -i / -y","ru":"он/она/оно: -i / -y"},{"pl":"my: -imy / -ymy","ru":"мы: -imy / -ymy"},{"pl":"wy: -icie / -ycie","ru":"вы: -icie / -ycie"},{"pl":"oni/one: -ą","ru":"они: -ą"}]},{"title":"Важное замечание","text":"Не путайте это спряжение с типом на -m (например, rozumieć → rozumiem). Глаголы на -m — это другая группа, изученная в уроке 3.","examples":[]},{"title":"Существительные мужского рода — падежи в единственном числе","text":"В польском языке склонение существительных мужского рода зависит от основы (твёрдая или мягкая) и от того, является ли предмет одушевлённым. Ниже представлены основные окончания падежей единственного числа.","examples":[{"pl":"Mianownik (кто? что?): kot, student, dom, nóż","ru":"Именительный: кот, студент, дом, нож"},{"pl":"Dopełniacz (кого? чего?): kota, studenta, domu, noża","ru":"Родительный: кота, студента, дома, ножа"},{"pl":"Celownik (кому? чему?): kotu, studentowi, domowi, nożowi","ru":"Дательный: коту, студенту, дому, ножу"},{"pl":"Biernik (кого? что?): kota/dom, studenta/nóż","ru":"Винительный: кота (одуш.) / дом (неодуш.)"},{"pl":"Narzędnik (кем? чем?): kotem, studentem, domem, nożem","ru":"Творительный: котом, студентом, домом, ножом"},{"pl":"Miejscownik (о ком? о чём?): o kocie, o studencie, o domu, o nożu","ru":"Предложный: о коте, о студенте, о доме, о ноже"},{"pl":"Wołacz (обращение!): kocie!, studencie!, domu!, nożu!","ru":"Звательный: кот!, студент!, дом!, нож!"}]},{"title":"Ключевые правила падежей мужского рода","text":"Родительный падеж (Dopełniacz): -a для одушевлённых и некоторых неодушевлённых, -u для многих неодушевлённых. Дательный (Celownik): основное окончание -owi, иногда -u (bogu, panu, ojcu). Винительный (Biernik): для одушевлённых совпадает с родительным, для неодушевлённых — с именительным. Творительный (Narzędnik): -em, после k/g — -iem.","examples":[{"pl":"dopełniacz: studenta, kota, domu, języka","ru":"род.: студента, кота, дома, языка"},{"pl":"celownik: studentowi, bogu, panu, ojcu","ru":"дат.: студенту, богу, господину, отцу"},{"pl":"narzędnik: kotem, studentem, językiem, bogiem","ru":"твор.: котом, студентом, языком, богом"},{"pl":"miejscownik: o studencie, o kocie, o domu, o języku","ru":"предл.: о студенте, о коте, о доме, о языке"},{"pl":"wołacz: Studencie! Kocie! Domu!","ru":"зват.: Студент! Кот! Дом!"}]},{"title":"Чередования согласных в местном и звательном падежах","text":"При образовании форм на -ie происходят чередования: t→cie (student→studencie), k→ce (kot→kocie), ch→sze, g→dze, r→rze.","examples":[{"pl":"student → o studencie","ru":"студент → о студенте"},{"pl":"kot → o kocie","ru":"кот → о коте"},{"pl":"brat → o bracie","ru":"брат → о брате"}]},{"title":"Множественное число мужского рода — две категории","text":"В польском языке во множественном числе принципиально различаются две категории: męskoosobowy (лично-мужской) — только мужчины или группы с хотя бы одним мужчиной; и niemęskoosobowy (женско-вещный) — женщины, дети, животные, неодушевлённые предметы.","examples":[{"pl":"Лично-мужской: studenci, Polacy, aktorzy, sąsiedzi","ru":"студенты, поляки, актёры, соседи"},{"pl":"Женско-вещный: kobiety, koty, domy, noże","ru":"женщины, коты, дома, ножи"}]},{"title":"Животные во множественном числе","text":"Категория одушевлённости во множественном числе работает иначе. Животные (psy, koty, ptaki) во множественном числе грамматически относятся к женско-вещной категории, то есть к «неодушевлённой».","examples":[{"pl":"To są koty. (niemęskoosobowy)","ru":"Это коты. (женско-вещная форма)"},{"pl":"Widzę psy. (biernik = mianownik)","ru":"Я вижу собак. (вин. = имен.)"}]},{"title":"Предлог «od» — временное значение","text":"Когда мы говорим, как долго что-то длится (и продолжается сейчас), используется настоящее время и предлог od с родительным падежом.","examples":[{"pl":"Znam go od pięciu lat.","ru":"Я знаю его пять лет (и сейчас знаю)."},{"pl":"Mieszkam tu od urodzenia.","ru":"Я живу здесь с рождения."}]},{"title":"Глаголы «работать»: pracować, robić, działać","text":"В польском языке есть три разных слова, которые можно перевести как «работать», но с разными оттенками.","examples":[{"pl":"pracować — трудиться где-то: Mój ojciec pracuje w szkole.","ru":"Мой отец работает в школе."},{"pl":"robić — делать; в разговорной речи «работать»: On robi w japońskiej korporacji.","ru":"Он работает в японской корпорации."},{"pl":"działać — действовать, функционировать: Mikrofon nie działa.","ru":"Микрофон не работает."}]},{"title":"Открыто / Закрыто (о магазинах и учреждениях)","text":"О магазинах и учреждениях не говорят «работает/не работает». Используют прилагательные otwarte / zamknięte.","examples":[{"pl":"Sklepy są zamknięte w niedzielę.","ru":"Магазины закрыты по воскресеньям."},{"pl":"Czy bank jest otwarty?","ru":"Банк открыт?"}]},{"title":"Беглые гласные (e ruchome)","text":"Как и в русском языке, гласная -e- часто выпадает при склонении существительных мужского рода.","examples":[{"pl":"ojciec → ojca (отец → отца)","ru":"отец → отца"},{"pl":"chłopiec → chłopca (мальчик → мальчика)","ru":"мальчик → мальчика"},{"pl":"sweter → swetra (свитер → свитера)","ru":"свитер → свитера"},{"pl":"pies → psa (пёс → пса)","ru":"пёс → пса"}]}],"tables":[{"verb":"mówić","translation":"говорить","rows":[{"pronoun":"ja","form":"mówię","ipa":"/ˈmuvʲɛ/"},{"pronoun":"ty","form":"mówisz","ipa":"/ˈmuviʂ/"},{"pronoun":"on/ona/ono","form":"mówi","ipa":"/ˈmuvi/"},{"pronoun":"my","form":"mówimy","ipa":"/muˈvimɨ/"},{"pronoun":"wy","form":"mówicie","ipa":"/muˈvit͡ɕɛ/"},{"pronoun":"oni/one","form":"mówią","ipa":"/ˈmuvʲɔ̃/"}]},{"verb":"myśleć","translation":"думать","rows":[{"pronoun":"ja","form":"myślę","ipa":"/ˈmɨɕlɛ/"},{"pronoun":"ty","form":"myślisz","ipa":"/ˈmɨɕliʂ/"},{"pronoun":"on/ona/ono","form":"myśli","ipa":"/ˈmɨɕli/"},{"pronoun":"my","form":"myślimy","ipa":"/mɨˈɕlimɨ/"},{"pronoun":"wy","form":"myślicie","ipa":"/mɨˈɕlit͡ɕɛ/"},{"pronoun":"oni/one","form":"myślą","ipa":"/ˈmɨɕlɔ̃/"}]}],"exercises":[]}'::jsonb);
INSERT INTO theme_section (theme_id, type, sort_order, content) VALUES ('pl_theme22', 'grammar', 0, '{"notes":[{"title":"Структура maila","text":"Польский e-mail удобно строить из трех частей: początek maila, główna treść maila и zakończenie maila. Сначала выбираем регистр: oficjalny для учреждения, незнакомого адресата или просьбы; nieoficjalny для друзей и семьи.","examples":[{"pl":"Początek maila: Szanowni Państwo / Drogi Tomku","ru":"начало письма: официальное / неофициальное обращение"},{"pl":"Główna treść maila: Kontaktuję się w sprawie kursu.","ru":"основная часть: зачем пишем"},{"pl":"Zakończenie maila: Z poważaniem / Pozdrawiam serdecznie","ru":"завершение: формула прощания"}]},{"title":"Официальное начало","text":"В официальном письме используем Szanowni Państwo, Szanowna Pani... или Szanowny Panie... При прямом обращении к мужчине форма Pan переходит в Panie.","examples":[{"pl":"Szanowni Państwo","ru":"Уважаемые господа / уважаемые дамы и господа"},{"pl":"Szanowna Pani Dyrektor","ru":"Уважаемая госпожа директор"},{"pl":"Szanowny Panie Dyrektorze","ru":"Уважаемый господин директор"}]},{"title":"Неофициальное начало","text":"В письме знакомым можно начать с Drogi..., Droga..., Kochana... или Drodzy... Часто после обращения добавляют короткое вступление: благодарность за письмо, радость от новости или извинение за долгую паузу.","examples":[{"pl":"Drogi Tomku","ru":"Дорогой Томек"},{"pl":"Kochana Aniu","ru":"Дорогая Аня"},{"pl":"Dziękuję za Twój mail.","ru":"Спасибо за твое письмо."}]},{"title":"Основная часть: официальный стиль","text":"Официальная основная часть обычно начинается с цели письма: на что ссылаемся, по какому вопросу пишем, какую информацию просим предоставить.","examples":[{"pl":"W nawiązaniu do naszej korespondencji zwracam się z uprzejmą prośbą o udzielenie informacji.","ru":"Ссылаясь на нашу переписку, вежливо прошу предоставить информацию."},{"pl":"Kontaktuję się w sprawie kursu językowego.","ru":"Пишу по поводу языкового курса."},{"pl":"Zapoznałam się z informacjami na stronie Państwa szkoły językowej.","ru":"Я ознакомилась с информацией на сайте вашей языковой школы."}]},{"title":"Основная часть: неофициальный стиль","text":"В неофициальном письме естественно звучат личные вступления: радость от письма, благодарность, извинение за молчание, переход к новостям.","examples":[{"pl":"Dostałem od Ciebie maila i bardzo się ucieszyłem.","ru":"Я получил от тебя письмо и очень обрадовался."},{"pl":"Dawno do siebie nie pisaliśmy.","ru":"Мы давно друг другу не писали."},{"pl":"Przepraszam za dłuższe milczenie.","ru":"Извини за долгое молчание."}]},{"title":"Время, место и порядок","text":"Для связного письма нужны опоры времени, места и последовательности. Обращайте внимание на падеж после na: gdzie? na koncercie, dokąd? na koncert.","examples":[{"pl":"w ubiegłym tygodniu / za tydzień","ru":"на прошлой неделе / через неделю"},{"pl":"być na konferencji / pojechać na konferencję","ru":"быть на конференции / поехать на конференцию"},{"pl":"po pierwsze, potem, następnie, na zakończenie","ru":"во-первых, потом, затем, в завершение"}]},{"title":"Завершение maila","text":"Официально можно поблагодарить заранее, попросить о подтверждении или выразить надежду на положительное рассмотрение. Неофициально можно спросить о делах, написать, что ждете ответа, и попрощаться тепло.","examples":[{"pl":"Z góry dziękuję uprzejmie za odpowiedź.","ru":"Заранее вежливо благодарю за ответ."},{"pl":"Będę wdzięczna za szybką odpowiedź.","ru":"Буду благодарна за быстрый ответ."},{"pl":"Pozdrawiam serdecznie","ru":"Сердечно приветствую / с теплыми пожеланиями"}]},{"title":"Жалоба и рекламация","text":"В письме-жалобе (reklamacja, skarga) сначала называем причину обращения и выражаем недовольство, затем описываем проблему — что не так и чем реальность отличается от обещанного, — и в конце формулируем требование: возврат, замену или компенсацию. Тон остается официальным и вежливым, но твердым.","examples":[{"pl":"Piszę do Państwa, aby wyrazić swoje niezadowolenie.","ru":"Пишу Вам, чтобы выразить своё неудовлетворение."},{"pl":"Niestety rzeczywistość nie pokrywa się z opisem.","ru":"К сожалению, реальность не совпадает с описанием."},{"pl":"Żądam natychmiastowej reakcji.","ru":"Требую немедленной реакции."}]},{"title":"Пунктуация и заглавные буквы","text":"После финальной формулы прощания в польском письме не ставим запятую перед именем. Местоимения и формы обращения к адресату пишем с заглавной: Ty, Tobie, Was, Pan, Pani, Państwo.","examples":[{"pl":"Pozdrawiam\nTadek","ru":"правильно: без запятой после Pozdrawiam"},{"pl":"Czekam na Twoją odpowiedź.","ru":"Twoją с заглавной, потому что обращаемся к адресату"},{"pl":"Będę wdzięczny za odpowiedź od Państwa.","ru":"Państwa с заглавной в вежливом обращении"}]}],"tables":[],"exercises":[]}'::jsonb);
INSERT INTO theme_section (theme_id, type, sort_order, content) VALUES ('pl_theme22', 'exercises', 1, '{"notes":[],"tables":[],"exercises":[{"type":"write_answer","category":"Официальное начало","prompt":"Уважаемые дамы и господа","answer":"Szanowni Państwo","hint":"Официальное обращение к учреждению или группе адресатов."},{"type":"write_answer","category":"Официальное начало","prompt":"Уважаемая госпожа директор","answer":"Szanowna Pani Dyrektor","hint":"Pani + должность; официальная форма."},{"type":"write_answer","category":"Официальное начало","prompt":"Уважаемый господин директор","answer":"Szanowny Panie Dyrektorze","hint":"При обращении Pan меняется на Panie, а должность часто в звательном падеже."},{"type":"write_answer","category":"Неофициальное начало","prompt":"Дорогой Томек","answers":["Drogi Tomku","Kochany Tomku"],"hint":"В обращении к Tomku используем звательный падеж."},{"type":"write_answer","category":"Неофициальное начало","prompt":"Дорогая Аня","answers":["Droga Aniu","Kochana Aniu"],"hint":"В обращении к Ania: Aniu."},{"type":"write_answer","category":"Неофициальное начало","prompt":"Дорогие друзья","answer":"Drodzy Przyjaciele","hint":"Форма множественного числа: Drodzy..."},{"type":"write_answer","category":"Вступление","prompt":"Спасибо за твой mail.","answer":"Dziękuję za Twój mail.","hint":"Twój пишем с заглавной, потому что это обращение к адресату."},{"type":"write_answer","category":"Вступление","prompt":"Мы (мужчины или смешанная группа) давно друг другу не писали.","answer":"Dawno do siebie nie pisaliśmy.","hint":"Мужская/смешанная форма: pisaliśmy."},{"type":"write_answer","category":"Вступление","prompt":"Мы (женщины) давно друг другу не писали.","answer":"Dawno do siebie nie pisałyśmy.","hint":"Женская форма: pisałyśmy."},{"type":"write_answer","category":"Вступление","prompt":"Извини за долгое молчание.","answer":"Przepraszam za dłuższe milczenie.","hint":"Неофициальное объяснение паузы в переписке."},{"type":"write_answer","category":"Вступление","prompt":"Пишу по поводу языкового курса.","answers":["Kontaktuję się w sprawie kursu językowego.","Piszę z powodu kursu językowego."],"hint":"Официальная формула: Kontaktuję się w sprawie... (допускается также Piszę z powodu kursu językowego)."},{"type":"write_answer","category":"Вступление","prompt":"Я ознакомился с информацией на сайте вашей школы.","answer":"Zapoznałem się z informacjami na stronie Państwa szkoły.","hint":"Мужская форма: Zapoznałem się; Państwa с заглавной."},{"type":"write_answer","category":"Вступление","prompt":"Я ознакомилась с информацией на сайте вашей школы.","answer":"Zapoznałam się z informacjami na stronie Państwa szkoły.","hint":"Женская форма: Zapoznałam się."},{"type":"write_answer","category":"Просьба","prompt":"Вежливо прошу предоставить информацию.","answer":"Zwracam się z uprzejmą prośbą o udzielenie informacji.","hint":"Официальная просьба: zwracam się z uprzejmą prośbą o..."},{"type":"write_answer","category":"Просьба","prompt":"Прошу сообщить мне о цене курса.","answer":"Proszę o poinformowanie mnie o cenie kursu.","hint":"Официально: proszę o poinformowanie mnie o..."},{"type":"write_answer","category":"Просьба","prompt":"Буду благодарен за быстрый ответ.","answer":"Będę wdzięczny za szybką odpowiedź.","hint":"Мужская форма: wdzięczny."},{"type":"write_answer","category":"Просьба","prompt":"Буду благодарна за быстрый ответ.","answer":"Będę wdzięczna za szybką odpowiedź.","hint":"Женская форма: wdzięczna."},{"type":"write_answer","category":"Благодарность","prompt":"Заранее вежливо благодарю за ответ.","answer":"Z góry dziękuję uprzejmie za odpowiedź.","hint":"Официальное завершение: Z góry dziękuję..."},{"type":"write_answer","category":"Ожидание ответа","prompt":"Я жду твоего ответа.","answer":"Czekam na Twoją odpowiedź.","hint":"Czekać na + biernik; Twoją с заглавной."},{"type":"write_answer","category":"Время","prompt":"на прошлой неделе","answer":"w ubiegłym tygodniu","hint":"Прошлое время: w ubiegłym / zeszłym tygodniu."},{"type":"write_answer","category":"Время","prompt":"через неделю","answer":"za tydzień","hint":"Будущее время: za + период."},{"type":"write_answer","category":"Время","prompt":"два месяца назад","answer":"dwa miesiące temu","hint":"Прошлое: liczba + okres + temu."},{"type":"write_answer","category":"Время","prompt":"через три года","answer":"za trzy lata","hint":"Будущее: za + biernik czasu."},{"type":"write_answer","category":"Частотность","prompt":"почти всегда","answer":"prawie zawsze","hint":"Противоположность: prawie nigdy."},{"type":"write_answer","category":"Частотность","prompt":"время от времени","answer":"od czasu do czasu","hint":"Готовое выражение частотности."},{"type":"write_answer","category":"Место","prompt":"быть на конференции","answer":"być na konferencji","hint":"Gdzie? na + miejscownik: na konferencji."},{"type":"write_answer","category":"Место","prompt":"ехать на конференцию","answers":["pojechać na konferencję","jechać na konferencję"],"hint":"Dokąd? na + biernik: na konferencję."},{"type":"write_answer","category":"Место","prompt":"быть в отпуске","answer":"być na urlopie","hint":"Gdzie? na urlopie."},{"type":"write_answer","category":"Место","prompt":"ехать в отпуск","answer":"jechać na urlop","hint":"Dokąd? na urlop."},{"type":"write_answer","category":"Порядок","prompt":"во-первых","answer":"po pierwsze","hint":"Фраза для перечисления аргументов."},{"type":"write_answer","category":"Порядок","prompt":"затем / потом","answers":["potem","następnie"],"hint":"Фразы для порядка событий."},{"type":"write_answer","category":"Порядок","prompt":"в завершение","answers":["na zakończenie","na koniec"],"hint":"Фраза для последнего пункта письма; na zakończenie / na koniec."},{"type":"write_answer","category":"Порядок","prompt":"прежде всего","answer":"przede wszystkim","hint":"Полезно для выделения главного аргумента."},{"type":"write_answer","category":"Полезные слова","prompt":"особенно сейчас","answer":"zwłaszcza teraz","hint":"Zwłaszcza = особенно."},{"type":"write_answer","category":"Полезные слова","prompt":"конечно, я хотел бы поблагодарить","answer":"oczywiście chciałbym podziękować","hint":"Мужская форма: chciałbym."},{"type":"write_answer","category":"Полезные слова","prompt":"мы обязательно должны встретиться","answer":"koniecznie musimy się spotkać","hint":"Koniecznie усиливает необходимость."},{"type":"write_answer","category":"Полезные слова","prompt":"мне важно увидеть город","answer":"zależy mi na tym, żeby zobaczyć miasto","hint":"Конструкция: zależy mi na tym, żeby + bezokolicznik."},{"type":"write_answer","category":"Полезные слова","prompt":"без сомнения","answers":["nie wątpię","bez wątpienia"],"hint":"Обе формы подходят для уверенного утверждения."},{"type":"write_answer","category":"Полезные слова","prompt":"рано или поздно мы увидимся","answer":"prędzej czy później się zobaczymy","hint":"Готовая фраза: prędzej czy później."},{"type":"write_answer","category":"Завершение","prompt":"С уважением","answers":["Z poważaniem","Z wyrazami szacunku"],"hint":"Официальная финальная формула."},{"type":"write_answer","category":"Завершение","prompt":"С теплыми пожеланиями","answers":["Pozdrawiam ciepło","Pozdrawiam serdecznie"],"hint":"Неофициальное или теплое завершение."},{"type":"write_answer","category":"Завершение","prompt":"Жду ваших новостей.","answer":"Czekam na Wasze wiadomości.","hint":"Wasze с заглавной как обращение к адресатам."},{"type":"write_answer","category":"Завершение","prompt":"Ждем с нетерпением твоего приезда.","answer":"Czekamy z niecierpliwością na Twój przyjazd.","hint":"Twój с заглавной; czekać na + biernik."},{"type":"write_answer","category":"Пунктуация","prompt":"Напиши правильно: Pozdrawiam + Tadek","answer":"Pozdrawiam Tadek","hint":"После финального Pozdrawiam запятую не ставим; в упражнении ответ вводится в одну строку."},{"type":"write_answer","category":"Заглавная буква","prompt":"твою (в письме к адресату)","answer":"Twoją","hint":"Местоимения адресата в письме пишем с заглавной."},{"type":"write_answer","category":"Заглавная буква","prompt":"господин / вы, вежливо","answer":"Pan","hint":"Pan, Pani, Państwo в обращении пишем с заглавной."},{"type":"write_answer","category":"Заглавная буква","prompt":"господа / вы, вежливо","answer":"Państwo","hint":"Официальная форма обращения к группе."},{"type":"write_answer","category":"Рекламация: начало","prompt":"Пишу Вам, чтобы выразить своё неудовлетворение.","answers":["Piszę do Państwa, aby wyrazić swoje niezadowolenie.","Piszę do Państwa, żeby wyrazić swoje niezadowolenie."],"hint":"Официальное начало жалобы; do Państwa — вежливое обращение."},{"type":"write_answer","category":"Рекламация: начало","prompt":"Обращаюсь к вам с рекламацией.","answer":"Zwracam się do Państwa z reklamacją.","hint":"Zwracać się z + narzędnik: z reklamacją."},{"type":"write_answer","category":"Рекламация: начало","prompt":"Я (мужчина) хотел бы подать рекламацию.","answer":"Chciałbym złożyć reklamację.","hint":"Złożyć reklamację = подать рекламацию; мужская форма chciałbym."},{"type":"write_answer","category":"Рекламация: начало","prompt":"Я (женщина) хотела бы подать рекламацию.","answer":"Chciałabym złożyć reklamację.","hint":"Женская форма: chciałabym."},{"type":"write_answer","category":"Рекламация: проблема","prompt":"К сожалению, реальность не совпадает с описанием.","answers":["Niestety rzeczywistość nie pokrywa się z opisem.","Niestety rzeczywistość nie zgadza się z opisem."],"hint":"Pokrywać się / zgadzać się z + narzędnik: z opisem."},{"type":"write_answer","category":"Рекламация: проблема","prompt":"Я (мужчина) не доволен сложившейся ситуацией.","answer":"Nie jestem zadowolony z zaistniałej sytuacji.","hint":"Zadowolony z + dopełniacz; zaistniała sytuacja = сложившаяся ситуация."},{"type":"write_answer","category":"Рекламация: проблема","prompt":"Я (женщина) не довольна сложившейся ситуацией.","answer":"Nie jestem zadowolona z zaistniałej sytuacji.","hint":"Женская форма: zadowolona."},{"type":"write_answer","category":"Рекламация: проблема","prompt":"Товар оказался бракованным.","answer":"Towar okazał się wadliwy.","hint":"Okazać się + przymiotnik: okazał się wadliwy."},{"type":"write_answer","category":"Рекламация: проблема","prompt":"Услуга не оправдала моих ожиданий.","answer":"Usługa nie spełniła moich oczekiwań.","hint":"Spełnić oczekiwania = оправдать ожидания."},{"type":"write_answer","category":"Рекламация: требования","prompt":"Требую немедленной реакции.","answer":"Żądam natychmiastowej reakcji.","hint":"Żądać + dopełniacz: żądam reakcji."},{"type":"write_answer","category":"Рекламация: требования","prompt":"Ожидаю возврата денег.","answer":"Oczekuję zwrotu pieniędzy.","hint":"Oczekiwać + dopełniacz: oczekuję zwrotu."},{"type":"write_answer","category":"Рекламация: требования","prompt":"Прошу обменять товар на новый.","answer":"Proszę o wymianę towaru na nowy.","hint":"Prosić o + biernik: o wymianę towaru."},{"type":"write_answer","category":"Рекламация: требования","prompt":"Требую компенсации.","answers":["Domagam się rekompensaty.","Żądam rekompensaty."],"hint":"Domagać się / żądać + dopełniacz: rekompensaty."},{"type":"write_answer","category":"Рекламация: завершение","prompt":"Рассчитываю на быстрое решение вопроса.","answer":"Liczę na szybkie rozwiązanie sprawy.","hint":"Liczyć na + biernik: na rozwiązanie sprawy."},{"type":"write_answer","category":"Рекламация: завершение","prompt":"Я (мужчина) буду вынужден предпринять дальнейшие шаги.","answer":"Będę zmuszony podjąć dalsze kroki.","hint":"Podjąć kroki = предпринять шаги; мужская форма zmuszony."},{"type":"write_answer","category":"Рекламация: завершение","prompt":"Я (женщина) буду вынуждена предпринять дальнейшие шаги.","answer":"Będę zmuszona podjąć dalsze kroki.","hint":"Женская форма: zmuszona."}]}'::jsonb);
